import * as m from './statsMath.js';
import { additionalAttributeKeys } from './parseXes.js';

function formatBytes(bytes) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function formatDuration(ms) {
  if (ms === null || Number.isNaN(ms)) return null;
  const seconds = ms / 1000;
  const minutes = seconds / 60;
  const hours = minutes / 60;
  const days = hours / 24;
  const weeks = days / 7;
  if (weeks >= 1) return `${weeks.toFixed(1)} weeks`;
  if (days >= 1) return `${days.toFixed(1)} days`;
  if (hours >= 1) return `${hours.toFixed(1)} hours`;
  if (minutes >= 1) return `${minutes.toFixed(1)} minutes`;
  return `${seconds.toFixed(1)} seconds`;
}

function traceDurationMs(trace) {
  const timestamps = trace.events.map((e) => e.timestamp).filter(Boolean);
  if (timestamps.length < 2) return 0;
  const min = timestamps.reduce((a, b) => (b < a ? b : a));
  const max = timestamps.reduce((a, b) => (b > a ? b : a));
  return max - min;
}

function variantSignature(trace) {
  return trace.events.map((e) => e.activity).join('');
}

/**
 * Derives the schema fields that ARE computable directly from a parsed XES
 * file (basic_info, data_characteristics, resource_context) — everything
 * that needs human judgement (domain_application, event_log_type,
 * process_type, academic_context, path_observation, ...) is left null for
 * the Add Dataset modal's review step to fill in.
 */
export function computeLogStats(traces, file) {
  const nTraces = traces.length;
  const nEvents = m.sum(traces.map((t) => t.events.length));
  const activityNames = new Set();
  traces.forEach((t) => t.events.forEach((e) => activityNames.add(e.activity)));

  const variantCounts = new Map();
  traces.forEach((t) => {
    const key = variantSignature(t);
    variantCounts.set(key, (variantCounts.get(key) || 0) + 1);
  });
  const variantEntries = [...variantCounts.values()].sort((a, b) => b - a);
  const nVariants = variantCounts.size;
  const nUniqueVariants = variantEntries.filter((c) => c === 1).length;
  const top5Coverage = m.sum(variantEntries.slice(0, 5));

  const resourceCounts = new Map();
  const activityCounts = new Map();
  traces.forEach((t) => t.events.forEach((e) => {
    if (e.resource) resourceCounts.set(e.resource, (resourceCounts.get(e.resource) || 0) + 1);
    activityCounts.set(e.activity, (activityCounts.get(e.activity) || 0) + 1);
  }));
  const resources = new Set(resourceCounts.keys());
  const mostFrequent = (counts, n) => [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, n).map(([k]) => k);

  const durations = traces.map(traceDurationMs);
  const top5VariantKeys = new Set(
    [...variantCounts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5).map(([k]) => k)
  );
  const top5Durations = traces
    .filter((t) => top5VariantKeys.has(variantSignature(t)))
    .map(traceDurationMs);

  const allTimestamps = traces.flatMap((t) => t.events.map((e) => e.timestamp)).filter(Boolean);
  const startDate = allTimestamps.length ? allTimestamps.reduce((a, b) => (b < a ? b : a)) : null;
  const endDate = allTimestamps.length ? allTimestamps.reduce((a, b) => (b > a ? b : a)) : null;

  const additionalAttributes = additionalAttributeKeys(traces);

  return {
    basic_info: {
      event_log_dataset_file_name: file.name,
      event_log_year: null,
      dataset_size: formatBytes(file.size),
      dataset_format: (/\.(xes|csv)(\.gz)?$/i.exec(file.name)?.[0] || '.xes').toLowerCase(),
      number_of_cases: nTraces,
      number_of_variants: nVariants,
      number_of_unique_variants: nUniqueVariants,
      number_of_events: nEvents,
      number_of_activities: activityNames.size,
      number_of_additional_attributes: additionalAttributes.length,
      additional_attributes: additionalAttributes.length ? additionalAttributes : null,
      resource_availability: resources.size > 0,
      median_case_duration: formatDuration(m.median(durations)),
      mean_case_duration: formatDuration(m.mean(durations)),
      start_date: startDate ? startDate.toISOString().slice(0, 10) : null,
      end_date: endDate ? endDate.toISOString().slice(0, 10) : null,
      notes: null,
    },
    data_characteristics: {
      activity_label: true,
      activity_label_description: mostFrequent(activityCounts, 3).join(', ') || null,
      variant_proportion_ratio: nVariants ? Math.round((nUniqueVariants / nVariants) * 10000) / 10000 : null,
      case_coverage_top5: top5Coverage,
      pct_case_coverage_top5: Math.round((top5Coverage / nTraces) * 10000) / 10000,
      mean_duration_top5: formatDuration(m.mean(top5Durations)),
      potential_performance_issues: null,
      performance_issues_notes: null,
      prominent_exhibited_behavior: null,
      primary_dependency: null,
      pct_primary_dependency_case_coverage: null,
    },
    resource_context: {
      number_of_resources: resources.size,
      number_of_unique_resources: resources.size,
      resource_type: null,
      type_indication: resources.size ? mostFrequent(resourceCounts, 3).join(', ') : null,
    },
    path_observation: {
      consistency: null,
      observed_path: null,
      notes_for_path_reduction: null,
    },
  };
}
