import { addStoredUserDataset, getStoredUserDatasets, markStoredUserDatasetsSent, removeStoredUserDataset } from './userDatasets';
import { slugify } from './slugify';
import { normalizeFeatureSet } from './featureSets';
import { recomputeFeatureSelection, recomputeFeatureSpace } from './recompute';

const BASE_PATH = import.meta.env.BASE_URL || '/';
const DATA_FILE = 'event_logs.json';
const dataFile = (kind, featureSet = 'default') =>
  DATA_FILE.replace(/\.json$/, featureSet === 'default' ? `.${kind}.json` : `.${kind}.${featureSet}.json`);

let cachedCorpus = null;
let cachedDatasets = null;
let cachedConfig = null;
let cachedFeatureSpace = null;
let cachedProjectedSpace = null;
let cachedFeatureSelection = null;
let cachedSelectionView = null;

async function fetchJson(file) {
  const res = await fetch(`${BASE_PATH}data/${file}`);
  if (!res.ok) throw new Error(`Failed to load ${file}: ${res.status}`);
  return res.json();
}

function withUserDatasets(corpus) {
  const used = new Set(corpus.map((d) => d._id));
  const added = getStoredUserDatasets().map((record) => ({
    ...record,
    _id: slugify(`${record.basic_info?.event_log_name || 'event log'} added`, used),
  }));
  return [...corpus, ...added];
}

export async function loadDatasets() {
  if (cachedDatasets) return cachedDatasets;
  if (!cachedCorpus) cachedCorpus = await fetchJson(DATA_FILE);
  cachedDatasets = withUserDatasets(cachedCorpus);
  return cachedDatasets;
}

export async function addUserDataset(record) {
  const stored = addStoredUserDataset(record);
  cachedDatasets = null;
  cachedProjectedSpace = null;
  cachedSelectionView = null;
  const datasets = await loadDatasets();
  return { dataset: datasets.find((d) => d._userKey === record._userKey) || null, stored };
}

export async function markUserDatasetsSent(userKeys, sent) {
  markStoredUserDatasetsSent(userKeys, sent);
  cachedDatasets = null;
  return loadDatasets();
}

export async function removeUserDataset(userKey) {
  removeStoredUserDataset(userKey);
  cachedDatasets = null;
  cachedProjectedSpace = null;
  cachedSelectionView = null;
  return loadDatasets();
}

export async function loadConfig() {
  if (cachedConfig) return cachedConfig;
  const config = await fetchJson('site.config.json');
  const overrides = Object.fromEntries(
    [
      ['submitUrl', import.meta.env.VITE_SUBMIT_URL],
      ['githubRepo', import.meta.env.VITE_GITHUB_REPO],
    ].filter(([, value]) => value)
  );
  cachedConfig = { ...config, contribute: { ...config.contribute, ...overrides } };
  return cachedConfig;
}

export async function getFeatureSet() {
  return normalizeFeatureSet((await loadConfig()).featureSet);
}

export function projectFeatures(space, features) {
  const values = space.feature_order.map((name, i) => {
    const v = features?.[name];
    const x = v === null || v === undefined || Number.isNaN(v) ? space.imputer_mean[i] : v;
    return x * space.scaler_scale[i] + space.scaler_min[i];
  });
  const norm = Math.hypot(...values) || 1;
  const centered = values.map((v, i) => v / norm - space.pca_mean[i]);
  const dot = (loadings) => space.feature_order.reduce((s, name, i) => s + centered[i] * loadings[name], 0);
  return { PC1: dot(space.loadings_pc1), PC2: dot(space.loadings_pc2) };
}

function userPoint(d, coords) {
  return {
    id: d._id,
    log: null,
    event_log_name: d.basic_info.event_log_name,
    collection: null,
    ...coords,
    domain_application: d.domain_context?.domain_application || null,
    event_log_type: d.domain_context?.event_log_type || null,
    academic_context_year: d.academic_context?.year || null,
    number_of_cases: d.basic_info.number_of_cases,
    number_of_events: d.basic_info.number_of_events,
    number_of_activities: d.basic_info.number_of_activities,
    userAdded: true,
  };
}

export async function loadFeatureSpace() {
  if (cachedProjectedSpace) return cachedProjectedSpace;
  if (!cachedFeatureSpace) cachedFeatureSpace = await fetchJson(dataFile('feature_space', await getFeatureSet()));
  const datasets = await loadDatasets();
  const added = datasets.filter((d) => d._userAdded && d.feeed_features);
  const recomputed = added.length ? recomputeFeatureSpace(cachedFeatureSpace, datasets) : null;
  if (recomputed) {
    const coords = new Map(recomputed.userCoords.map(({ id, ...c }) => [id, c]));
    cachedProjectedSpace = {
      ...recomputed,
      n_user_points: added.length,
      points: [...recomputed.basePoints, ...added.map((d) => userPoint(d, coords.get(d._id)))],
    };
  } else {
    const userPoints = added.map((d) => userPoint(d, projectFeatures(cachedFeatureSpace, d.feeed_features)));
    cachedProjectedSpace = { ...cachedFeatureSpace, n_user_points: 0, points: [...cachedFeatureSpace.points, ...userPoints] };
  }
  return cachedProjectedSpace;
}

export async function loadFeatureSelection() {
  if (cachedSelectionView) return cachedSelectionView;
  if (!cachedFeatureSelection) cachedFeatureSelection = await fetchJson(dataFile('feature_selection', await getFeatureSet()));
  const datasets = await loadDatasets();
  cachedSelectionView = datasets.some((d) => d._userAdded && d.feeed_features)
    ? recomputeFeatureSelection(cachedFeatureSelection, datasets)
    : cachedFeatureSelection;
  return cachedSelectionView;
}

export function getDatasetById(datasets, id) {
  return datasets.find((d) => d._id === id) || null;
}
