export const ACCEPTED_EXTENSIONS = ['.xes', '.xes.gz', '.csv', '.csv.gz'];

const MB = 1024 * 1024;

export function isAcceptedFile(file) {
  const name = file.name.toLowerCase();
  return ACCEPTED_EXTENSIONS.some((ext) => name.endsWith(ext));
}

export function isCsvFile(file) {
  return /\.csv(\.gz)?$/i.test(file.name);
}

function isGzip(file) {
  return file.name.toLowerCase().endsWith('.gz');
}

export function formatMB(bytes) {
  return `${Math.round(bytes / MB).toLocaleString()} MB`;
}

export async function estimatedSize(file) {
  if (!isGzip(file) || file.size < 18) return file.size;
  const tail = new DataView(await file.slice(-4).arrayBuffer());
  return Math.max(tail.getUint32(0, true), file.size);
}

function tooLarge(maxBytes) {
  return new Error(
    `the unpacked event log is larger than ${formatMB(maxBytes)}, the most this page can process in your browser`
  );
}

export async function readXesFile(file, maxBytes = Infinity) {
  if (!isGzip(file)) {
    if (file.size > maxBytes) throw tooLarge(maxBytes);
    return file.text();
  }
  if (typeof DecompressionStream === 'undefined') {
    throw new Error('This browser cannot unpack .gz files. Please unpack the file and choose the .xes file.');
  }
  let total = 0;
  const limit = new TransformStream({
    transform(chunk, controller) {
      total += chunk.byteLength;
      if (total > maxBytes) controller.error(tooLarge(maxBytes));
      else controller.enqueue(chunk);
    },
  });
  const stream = file.stream().pipeThrough(new DecompressionStream('gzip')).pipeThrough(limit);
  return new Response(stream).text();
}
