import EntryPreview from '@/components/EntryPreview';
import { SHAREABLE_FIELDS, withholdFields } from '@/lib/entries';

export default function SubmissionPreview({ datasets, contributor, withEmail, withheld = [], onWithheldChange }) {
  const who = [contributor.name.trim(), contributor.institution.trim()].filter(Boolean).join(', ');
  const groups = [...SHAREABLE_FIELDS.reduce((m, f) => m.set(f.group, [...(m.get(f.group) || []), f]), new Map())];
  const toggle = (id) => onWithheldChange?.(withheld.includes(id) ? withheld.filter((w) => w !== id) : [...withheld, id]);
  return (
    <div className="add-log__field submission-preview">
      <label className="filters-panel__label">What will be sent</label>
      <p className="add-log__hint">
        {datasets.length === 1 ? 'One metadata entry' : `${datasets.length} metadata entries`}, with your name and institution
        {who ? ` (${who})` : ''}.{withEmail ? ' By email, your address is added but never published.' : ''} The event log files
        are not included.{datasets.length > 1 ? ' Open an entry to see its values.' : ''}
      </p>
      {datasets.map((d) => (
        <details key={d._userKey} className="submission-preview__entry" open={datasets.length === 1}>
          <summary>
            <strong>{d.basic_info.event_log_name}</strong>{' '}
            <span className="submission-preview__counts">
              {(d.basic_info.number_of_cases ?? 0).toLocaleString()} cases ·{' '}
              {(d.basic_info.additional_attributes || []).length} additional attributes
            </span>
          </summary>
          <EntryPreview dataset={withholdFields(d, withheld)} />
        </details>
      ))}
      {onWithheldChange && (
        <div className="submission-preview__withhold">
          <label className="filters-panel__label" htmlFor="withhold-field">
            Fields not to share
          </label>
          <select
            id="withhold-field"
            className="concept-select__input submission-preview__select"
            value=""
            onChange={(e) => e.target.value && toggle(e.target.value)}
          >
            <option value="">Choose a field you do not want to share…</option>
            {groups.map(([group, fields]) => (
              <optgroup key={group} label={group}>
                {fields.map((f) => (
                  <option key={f.id} value={f.id} disabled={withheld.includes(f.id)}>
                    {f.label}
                  </option>
                ))}
              </optgroup>
            ))}
          </select>
          {withheld.length > 0 && (
            <div className="filters-panel__chips submission-preview__withheld">
              {SHAREABLE_FIELDS.filter((f) => withheld.includes(f.id)).map((f) => (
                <button
                  key={f.id}
                  type="button"
                  className="filter-chip filter-chip--active"
                  onClick={() => toggle(f.id)}
                  aria-label={`Share ${f.label} again`}
                >
                  {f.label} ✕
                </button>
              ))}
            </div>
          )}
          <p className="add-log__hint">
            {withheld.length
              ? 'These fields are left out of every entry sent and no longer appear in the preview. Click a field to share it again.'
              : 'Fields you choose are left out of every entry sent and disappear from the preview.'}
          </p>
        </div>
      )}
    </div>
  );
}
