import Field from '@/components/Field';
import { humanize } from '@/lib/humanize';
import {
  FEATURE_GROUP_LABELS,
  METADATA_FEEED_OVERLAP,
  formatFeatureValue,
  groupFeatures,
} from '@/lib/featureGroups';

export default function EventLogDetailContent({ dataset, domainColor, compact = false }) {
  const {
    basic_info: basicInfo,
    domain_context: domainContext,
    academic_context: academicContext,
    data_characteristics: dataCharacteristics,
    resource_context: resourceContext,
    path_observation: pathObservation,
    feeed_features: feeedFeatures,
  } = dataset;

  const featureGroups = feeedFeatures ? groupFeatures(Object.keys(feeedFeatures)) : null;

  // A metadata field is only hidden once its FEEED equivalent is actually
  // shown in "Computed Features (FEEED)" — records without FEEED features
  // keep showing the metadata value.
  const showMetadataField = (metadataKey) => {
    if (compact) return true;
    const feeedKey = METADATA_FEEED_OVERLAP[metadataKey];
    if (!feeedKey || !feeedFeatures) return true;
    return feeedFeatures[feeedKey] === undefined;
  };

  const featureGrid = featureGroups && <FeatureGrid featureGroups={featureGroups} feeedFeatures={feeedFeatures} />;

  const showResourceContext = resourceContext.number_of_resources !== 0;

  return (
    <div>
      <div className="log-detail__badges">
        {domainContext.domain_application && (
          <span className="log-card__badge" style={{ '--domain-color': domainColor }}>
            {domainContext.domain_application}
          </span>
        )}
        {domainContext.event_log_type && <span className="chip">{domainContext.event_log_type}</span>}
        {domainContext.process_type && <span className="chip">{domainContext.process_type}</span>}
      </div>
      {compact ? (
        <h4 className="entry-preview__title">{basicInfo.event_log_name}</h4>
      ) : (
        <h1 className="log-detail__title">{basicInfo.event_log_name}</h1>
      )}
      <p className="log-detail__meta">
        {academicContext.year ? `Academic Context Year: ${academicContext.year}` : 'No academic context year on file'}
        {academicContext.publication_type ? ` · ${academicContext.publication_type}` : ''}
      </p>
      {academicContext.reference && <p className="field__text">{academicContext.reference}</p>}
      {compact && <Field label="Source" value={dataset.source_url || basicInfo.notes} />}
      {academicContext.doi && (
        <p className="field__text">
          <a href={`https://doi.org/${academicContext.doi.replace(/^https?:\/\/doi\.org\//, '')}`} target="_blank" rel="noopener noreferrer">
            {academicContext.doi}
          </a>
        </p>
      )}

      <section className="detail-section">
        <h2 className="detail-section__title">Domain Context</h2>
        <div className="artifact-grid">
          <Field label="Domain Application" value={domainContext.domain_application} />
          <Field label="Event Log Type" value={domainContext.event_log_type} />
          <Field label="Process Type" value={domainContext.process_type} />
        </div>
        <Field label="Process Information" value={domainContext.process_information} />
      </section>

      <section className="detail-section">
        <h2 className="detail-section__title">Data Characteristics</h2>
        <div className="artifact-grid">
          <Field label="Activity Label" value={dataCharacteristics.activity_label} />
          {showMetadataField('variant_proportion_ratio') && (
            <Field label="Variant Proportion Ratio" value={dataCharacteristics.variant_proportion_ratio} />
          )}
          <Field label="Case Coverage (Top 5 Variants)" value={dataCharacteristics.case_coverage_top5} />
          <Field label="% Case Coverage (Top 5 Variants)" value={dataCharacteristics.pct_case_coverage_top5} />
          <Field label="Mean Duration (Top 5 Variants)" value={dataCharacteristics.mean_duration_top5} />
          <Field label="Prominent Exhibited Behavior" value={dataCharacteristics.prominent_exhibited_behavior} />
          <Field label="% Primary Dependency Case Coverage" value={dataCharacteristics.pct_primary_dependency_case_coverage} />
        </div>
        <Field label="Activity Label Description" value={dataCharacteristics.activity_label_description} />
        <Field label="Potential Performance Issues" value={dataCharacteristics.potential_performance_issues} />
        <Field label="Performance Issues Notes" value={dataCharacteristics.performance_issues_notes} />
        <Field label="Primary Dependency" value={dataCharacteristics.primary_dependency} />
      </section>

      {(!compact || Object.values(pathObservation || {}).some((v) => v !== null && v !== undefined && v !== '')) && (
      <section className="detail-section">
        <h2 className="detail-section__title">Path Observation</h2>
        <div className="artifact-grid">
          <Field label="Consistency" value={pathObservation.consistency} />
          <Field label="Observed Path" value={pathObservation.observed_path} />
        </div>
        <Field label="Notes for the Path Reduction" value={pathObservation.notes_for_path_reduction} />
      </section>
      )}

      <section className="detail-section">
        <h2 className="detail-section__title">Basic Process Analytics</h2>
        <div className="artifact-grid">
          <Field label="Dataset Size" value={basicInfo.dataset_size} />
          <Field label="Dataset Format" value={basicInfo.dataset_format} />
          {showMetadataField('number_of_cases') && <Field label="Number of Cases" value={basicInfo.number_of_cases} />}
          {showMetadataField('number_of_variants') && <Field label="Number of Variants" value={basicInfo.number_of_variants} />}
          <Field label="Number of Unique Variants" value={basicInfo.number_of_unique_variants} />
          {showMetadataField('number_of_events') && <Field label="Number of Events" value={basicInfo.number_of_events} />}
          {showMetadataField('number_of_activities') && <Field label="Number of Activities" value={basicInfo.number_of_activities} />}
          <Field label="Number of Additional Attributes" value={basicInfo.number_of_additional_attributes} />
          <Field label="Additional Attributes" value={basicInfo.additional_attributes} chips={false} />
          <Field label="Resource Availability" value={basicInfo.resource_availability} />
          <Field label="Median Case Duration" value={basicInfo.median_case_duration} />
          <Field label="Mean Case Duration" value={basicInfo.mean_case_duration} />
          <Field label="Start Date" value={basicInfo.start_date} />
          <Field label="End Date" value={basicInfo.end_date} />
        </div>
        <Field label="Notes" value={basicInfo.notes} />
      </section>

      {showResourceContext && (
        <section className="detail-section">
          <h2 className="detail-section__title">Resource Context</h2>
          <div className="artifact-grid">
            <Field label="Number of Resources" value={resourceContext.number_of_resources} />
            <Field label="Number of Unique Resources" value={resourceContext.number_of_unique_resources} />
            <Field label="Resource Type" value={resourceContext.resource_type} />
            <Field label="Type Indication" value={resourceContext.type_indication} />
          </div>
        </section>
      )}

      <section className="detail-section">
        <h2 className="detail-section__title">Computed Features (FEEED)</h2>
        {!feeedFeatures ? (
          <p className="field__text">
            {compact && dataset.feeed_available
              ? 'The feature values are not shared.'
              : 'FEEED features have not been computed for this event log.'}
          </p>
        ) : compact ? (
          <details className="entry-preview__features">
            <summary>
              Feature values ({Object.values(feeedFeatures).filter((v) => v !== null && v !== undefined).length} of{' '}
              {Object.keys(feeedFeatures).length} computed)
            </summary>
            {featureGrid}
          </details>
        ) : (
          featureGrid
        )}
      </section>
    </div>
  );
}

function FeatureGrid({ featureGroups, feeedFeatures }) {
  return (
    <div className="feature-groups">
      {Object.entries(featureGroups).map(([group, names]) => (
        <div className="feature-group" key={group}>
          <h3 className="feature-group__title">{FEATURE_GROUP_LABELS[group] || humanize(group)}</h3>
          <div className="feature-group__grid">
            {names.map((name) => (
              <div className="feature-group__item" key={name}>
                <span className="feature-group__name">{humanize(name)}</span>
                <span className="feature-group__value">{formatFeatureValue(feeedFeatures[name])}</span>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}
