const OVERRIDES = {
  id: 'ID',
  doi: 'DOI',
};

const ACRONYMS = new Set(['epa', 'iqr', 'knn', 'pc1', 'pc2', 'feeed']);
const LOWERCASE_WORDS = new Set(['of', 'the', 'and', 'in', 'to', 'a', 'or']);

/**
 * Turns a snake_case schema key or enum value into human-readable words,
 * without changing its meaning (no renaming/repurposing).
 */
export function humanize(key) {
  if (key === undefined || key === null) return '';
  const raw = String(key);
  if (OVERRIDES[raw]) return OVERRIDES[raw];

  const words = raw.split('_').filter(Boolean);
  return words
    .map((w, i) => {
      if (ACRONYMS.has(w.toLowerCase())) return w.toUpperCase();
      if (i > 0 && LOWERCASE_WORDS.has(w)) return w;
      return w.charAt(0).toUpperCase() + w.slice(1);
    })
    .join(' ');
}

export function escapeHtml(text) {
  return String(text ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}
