import { useCallback, useEffect, useMemo, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import Header from '@/components/Header';
import DomainApplicationsOverview from '@/components/DomainApplicationsOverview';
import EventLogCard from '@/components/EventLogCard';
import FiltersPanel from '@/components/FiltersPanel';
import StatsBar from '@/components/StatsBar';
import LandscapeVisualization from '@/components/LandscapeVisualization';
import AddEventLogModal from '@/components/AddEventLogModal';
import SendEntriesModal from '@/components/SendEntriesModal';
import ConceptSelect from '@/components/ConceptSelect';
import { loadDatasets, loadConfig } from '@/lib/data';
import { matchesFacetFilters, isHidden } from '@/lib/filters';
import { conceptByKey, conceptColors, conceptValue, conceptValues } from '@/lib/concepts';

export default function EventDatasetsPage() {
  const [datasets, setDatasets] = useState(null);
  const [config, setConfig] = useState(null);
  const [selectedValues, setSelectedValues] = useState([]);
  const [facetFilters, setFacetFilters] = useState({});
  const [query, setQuery] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [searchParams, setSearchParams] = useSearchParams();
  const [showAddLog, setShowAddLog] = useState(() => searchParams.has('add'));
  const [sendKeys, setSendKeys] = useState(null);
  const [landscapeConcept, setLandscapeConcept] = useState('domain_application');

  useEffect(() => {
    if (!searchParams.has('add')) return;
    const next = new URLSearchParams(searchParams);
    next.delete('add');
    setSearchParams(next, { replace: true });
  }, [searchParams, setSearchParams]);

  useEffect(() => {
    Promise.all([loadDatasets(), loadConfig()]).then(([d, c]) => {
      setDatasets(d);
      setConfig(c);
    });
  }, []);

  const domainColors = useMemo(() => {
    const map = {};
    (config?.domainApplications || []).forEach((d) => {
      map[d.id] = d.color;
    });
    return map;
  }, [config]);

  const concept = conceptByKey(landscapeConcept);
  const valueOf = useCallback((d) => conceptValue(concept, d), [concept]);
  const conceptItems = useMemo(() => {
    const values = conceptValues(concept, datasets || []);
    const colors = conceptColors(concept, values, config);
    const items = values.map((v) => ({ id: v, label: v, color: colors[v] }));
    return { colors, items };
  }, [concept, datasets, config]);

  const chooseConcept = (key) => {
    setLandscapeConcept(key);
    setSelectedValues([]);
  };

  const filtered = useMemo(() => {
    if (!datasets) return [];
    const q = query.trim().toLowerCase();
    return datasets.filter((d) => {
      if (selectedValues.length > 0 && !selectedValues.includes(valueOf(d))) return false;
      if (!matchesFacetFilters(d, facetFilters)) return false;
      if (!q) return true;
      const haystack = [
        d.basic_info.event_log_name,
        d.domain_context.domain_application,
        d.domain_context.process_information,
        d.academic_context.reference,
      ]
        .filter(Boolean)
        .join(' ')
        .toLowerCase();
      return haystack.includes(q);
    });
  }, [datasets, selectedValues, valueOf, facetFilters, query]);

  const listed = useMemo(() => {
    const list = filtered.filter((d) => !isHidden(d));
    return [...list].sort((a, b) => {
      if (Boolean(a._userAdded) !== Boolean(b._userAdded)) return a._userAdded ? -1 : 1;
      if (a._userAdded && b._userAdded) return (b._addedAt || '').localeCompare(a._addedAt || '');
      return 0;
    });
  }, [filtered]);

  const handleLogAdded = () => {
    loadDatasets().then(setDatasets);
  };

  const userEntries = datasets ? datasets.filter((d) => d._userAdded) : [];

  const toggleValue = (id) => {
    setSelectedValues((prev) => (prev.includes(id) ? prev.filter((t) => t !== id) : [...prev, id]));
  };

  const toggleFacet = (facetKey, value) => {
    setFacetFilters((prev) => {
      const current = prev[facetKey] || [];
      const next = current.includes(value) ? current.filter((v) => v !== value) : [...current, value];
      return { ...prev, [facetKey]: next };
    });
  };

  const clearAllFilters = () => {
    setSelectedValues([]);
    setFacetFilters({});
    setQuery('');
  };

  const hasActiveFilters =
    selectedValues.length > 0 || query || Object.values(facetFilters).some((v) => v && v.length > 0);

  if (!datasets || !config) {
    return (
      <div className="main-layout">
        <div className="loading">
          <div className="loading__spinner" />
          <p>Loading...</p>
        </div>
      </div>
    );
  }

  const labels = config.visualization?.labels || {};

  return (
    <div className="main-layout">
      <Header config={config} />
      <main className="main-content">
        <div className="papers-layout">
          <div className="papers-layout__main">
            <section className="contribute-cta">
              <div className="contribute-cta__text">
                <h2 className="contribute-cta__title">{labels.contributeTitle || 'Add your event logs to the landscape'}</h2>
                <p>
                  {labels.contributeText ||
                    'Every event log you add widens what we know about event data. Load XES or CSV files: the features are computed in your browser, and only the metadata is sent if you choose to.'}
                </p>
              </div>
              <div className="contribute-cta__actions">
                <button type="button" className="btn btn--primary btn--lg" onClick={() => setShowAddLog(true)}>
                  + Add Event Log
                </button>
                {userEntries.length > 0 && (
                  <button type="button" className="btn btn--secondary" onClick={() => setSendKeys([])}>
                    Send your entries ({userEntries.length})
                  </button>
                )}
              </div>
            </section>

            {config.features?.stats !== false && <StatsBar datasets={datasets} />}

            <DomainApplicationsOverview
              items={conceptItems.items}
              valueOf={valueOf}
              datasets={datasets}
              selected={selectedValues}
              onToggle={toggleValue}
              title={concept.key === 'domain_application' ? labels.domainsTitle || 'Domain Applications' : concept.label}
              hint={labels.domainsHint}
              control={<ConceptSelect id="landscape-concept" label="Concept" value={landscapeConcept} onChange={chooseConcept} />}
            />

            {config.features?.landscape !== false && (
              <section className="landscape-section">
                <h2 className="detail-section__title">{labels.landscapeTitle || 'Event Log Landscape'}</h2>
                {labels.landscapeDescription && <p className="graph-page__description">{labels.landscapeDescription}</p>}
                <LandscapeVisualization datasets={filtered} concept={concept} colors={conceptItems.colors} />
              </section>
            )}

            <div className="toolbar">
              {config.features?.search !== false && (
                <input
                  type="search"
                  placeholder="Search event logs by name, domain, or reference…"
                  value={query}
                  onChange={(e) => setQuery(e.target.value)}
                  className="toolbar__search"
                />
              )}
              {config.features?.filters !== false && (
                <button
                  type="button"
                  className={`btn ${showFilters ? 'btn--primary' : 'btn--secondary'}`}
                  onClick={() => setShowFilters((v) => !v)}
                >
                  Filters
                </button>
              )}
              {hasActiveFilters && (
                <button type="button" className="btn btn--ghost" onClick={clearAllFilters}>
                  Clear filters
                </button>
              )}
            </div>

            {showFilters && config.features?.filters !== false && (
              <FiltersPanel datasets={datasets} filters={facetFilters} onToggle={toggleFacet} onClear={() => setFacetFilters({})} />
            )}
          </div>

          <div className="papers-layout__sidebar">
            <p className="results-count">
              {listed.length} {listed.length === 1 ? labels.entrySingular || 'event log' : labels.entryPlural || 'event logs'}
            </p>

            {listed.length === 0 ? (
              <div className="empty-state">
                <p>No event logs match the current filters.</p>
              </div>
            ) : (
              <div className="log-list">
                {listed.map((dataset) => (
                  <EventLogCard key={dataset._id} dataset={dataset} domainColors={domainColors} />
                ))}
              </div>
            )}
          </div>
        </div>
      </main>

      {showAddLog && (
        <AddEventLogModal
          config={config}
          datasets={datasets}
          onClose={() => setShowAddLog(false)}
          onAdded={handleLogAdded}
        />
      )}

      {sendKeys && (
        <SendEntriesModal
          config={config}
          datasets={datasets}
          initialKeys={sendKeys}
          onClose={() => setSendKeys(null)}
          onSent={setDatasets}
        />
      )}
    </div>
  );
}
