export default function StatsBar({ datasets }) {
  const total = datasets.length;
  const pctOf = (predicate) => (total ? Math.round((datasets.filter(predicate).length / total) * 100) : 0);

  const pctRealLife = pctOf((d) => d.domain_context?.event_log_type === 'Real-life');
  const pctFeeed = pctOf((d) => d.feeed_available);
  const pctResources = pctOf((d) => d.basic_info?.resource_availability);

  const years = datasets.map((d) => d.academic_context?.year).filter((y) => y !== null && y !== undefined);
  const yearRange = years.length ? `${Math.min(...years)}–${Math.max(...years)}` : '—';

  const domains = new Set(datasets.map((d) => d.domain_context?.domain_application).filter(Boolean));

  const stats = [
    { label: 'Event Log Datasets', value: total },
    { label: 'Domain Applications', value: domains.size },
    { label: '% Real-life Logs', value: `${pctRealLife}%` },
    { label: '% With FEEED Features', value: `${pctFeeed}%` },
    { label: '% With Resource Info', value: `${pctResources}%` },
    { label: 'Academic Context Years', value: yearRange },
  ];

  return (
    <div className="stats-bar">
      {stats.map((s) => (
        <div className="stats-bar__tile" key={s.label}>
          <span className="stats-bar__value">{s.value}</span>
          <span className="stats-bar__label">{s.label}</span>
        </div>
      ))}
    </div>
  );
}
