import { CONCEPTS } from '@/lib/concepts';

export default function ConceptSelect({ id, label, value, onChange }) {
  return (
    <label className="concept-select" htmlFor={id}>
      <span className="concept-select__label">{label}</span>
      <select id={id} className="concept-select__input" value={value} onChange={(e) => onChange(e.target.value)}>
        {CONCEPTS.map((c) => (
          <option key={c.key} value={c.key}>
            {c.label}
          </option>
        ))}
      </select>
    </label>
  );
}
