/**
 * Client-side port of FEEED 2.2.0 (https://pypi.org/project/feeed/): the base groups here, the
 * remaining 132 features in feeedExtraFeatures.js. Checked against FEEED 2.2.0 on the
 * collection's logs; the default feature set (featureSets.json) needs only part of the extras.
 */
import * as m from './statsMath.js';
import { computeExtraFeatures } from './feeedExtraFeatures.js';
import { featureSetNames, isExcludedFeature } from '../featureSets.js';

// Cost guard for the kNN eventropy features (see eventropies() below): their
// pairwise Levenshtein matrix is O(V^2), so logs with more distinct variants
// than this degrade to `null` for those features instead of hanging the tab.
const KNN_VARIANT_LIMIT = 400;

// ---------------------------------------------------------------------------
// Shared trace/log views
// ---------------------------------------------------------------------------

/** Array of activity-name arrays, one per trace, in file order (feeed/pm4py
 * do not reorder events within a trace). */
function activitySequences(traces) {
  return traces.map((t) => t.events.map((e) => e.activity));
}

// A rare separator keeps this a cheap O(length) join instead of JSON.stringify's
// heavier per-element quoting/escaping — matters since this runs per
// trace/substring/prefix across potentially large logs.
function variantKey(seq) {
  return seq.join('');
}

// ---------------------------------------------------------------------------
// simple_stats
// ---------------------------------------------------------------------------

/** Map of variantKey -> { seq, count }, so downstream consumers (KNN
 * eventropy needs the actual activity-name arrays back) never have to
 * reconstruct a sequence by parsing its key. */
function buildVariantIndex(seqs) {
  const index = new Map();
  seqs.forEach((seq) => {
    const key = variantKey(seq);
    const entry = index.get(key);
    if (entry) entry.count += 1;
    else index.set(key, { seq, count: 1 });
  });
  return index;
}

function simpleStats(seqs, variantIndex) {
  const nTraces = seqs.length;
  const nVariants = variantIndex.size;
  return {
    n_traces: nTraces,
    n_variants: nVariants,
    ratio_variants_per_number_of_traces: nVariants / nTraces,
  };
}

// ---------------------------------------------------------------------------
// trace_length
// ---------------------------------------------------------------------------

function traceLength(seqs) {
  const lengths = seqs.map((s) => s.length);
  const hist = m.histogramDensity10(lengths);
  return {
    trace_len_min: m.min(lengths),
    trace_len_max: m.max(lengths),
    trace_len_mean: m.mean(lengths),
    trace_len_median: m.median(lengths),
    trace_len_mode: m.mode(lengths),
    trace_len_std: m.std(lengths),
    trace_len_variance: m.variance(lengths),
    trace_len_q1: m.percentile(lengths, 25),
    trace_len_q3: m.percentile(lengths, 75),
    trace_len_iqr: m.iqr(lengths),
    trace_len_geometric_mean: m.gmean(lengths),
    trace_len_geometric_std: m.gstd(lengths),
    trace_len_harmonic_mean: m.hmean(lengths),
    trace_len_skewness: m.skew(lengths),
    trace_len_kurtosis: m.kurtosis(lengths),
    trace_len_coefficient_variation: m.variation(lengths),
    trace_len_entropy: m.entropyOfWeights(lengths),
    trace_len_skewness_hist: m.skew(hist),
    trace_len_kurtosis_hist: m.kurtosis(hist),
  };
}

// ---------------------------------------------------------------------------
// trace_variant
// ---------------------------------------------------------------------------

function traceVariant(seqs, variantIndex) {
  const nTraces = seqs.length;
  const occurrences = [...variantIndex.values()].map((v) => v.count).sort((a, b) => b - a);
  const topRatio = (fraction) => {
    const k = Math.floor(occurrences.length * fraction);
    return m.sum(occurrences.slice(0, k)) / nTraces;
  };
  return {
    ratio_most_common_variant: m.sum(occurrences.slice(0, 1)) / nTraces,
    ratio_top_1_variants: topRatio(0.01),
    ratio_top_5_variants: topRatio(0.05),
    ratio_top_10_variants: topRatio(0.1),
    ratio_top_20_variants: topRatio(0.2),
    ratio_top_50_variants: topRatio(0.5),
    ratio_top_75_variants: topRatio(0.75),
    mean_variant_occurrence: m.mean(occurrences),
    std_variant_occurrence: m.std(occurrences),
    skewness_variant_occurrence: m.skew(occurrences),
    kurtosis_variant_occurrence: m.kurtosis(occurrences),
  };
}

// ---------------------------------------------------------------------------
// activities / start_activities / end_activities
// ---------------------------------------------------------------------------

function frequencyStats(prefix, values, nUniqueKey) {
  return {
    [nUniqueKey]: values.length,
    [`${prefix}_min`]: m.min(values),
    [`${prefix}_max`]: m.max(values),
    [`${prefix}_mean`]: m.mean(values),
    [`${prefix}_median`]: m.median(values),
    [`${prefix}_std`]: m.std(values),
    [`${prefix}_variance`]: m.variance(values),
    [`${prefix}_q1`]: m.percentile(values, 25),
    [`${prefix}_q3`]: m.percentile(values, 75),
    [`${prefix}_iqr`]: m.iqr(values),
    [`${prefix}_skewness`]: m.skew(values),
    [`${prefix}_kurtosis`]: m.kurtosis(values),
  };
}

function activityStats(seqs) {
  const counts = new Map();
  seqs.forEach((seq) => seq.forEach((a) => counts.set(a, (counts.get(a) || 0) + 1)));
  return frequencyStats('activities', [...counts.values()], 'n_unique_activities');
}

/** pm4py's get_start_activities/get_end_activities first drop any event
 * literally named "START"/"END" (feeed's start_activities.py / end_activities.py). */
function boundaryActivityStats(seqs, { end, marker, prefix, nUniqueKey }) {
  const counts = new Map();
  seqs.forEach((seq) => {
    const filtered = seq.filter((a) => a !== marker);
    if (filtered.length === 0) return;
    const activity = end ? filtered[filtered.length - 1] : filtered[0];
    counts.set(activity, (counts.get(activity) || 0) + 1);
  });
  return frequencyStats(prefix, [...counts.values()], nUniqueKey);
}

// ---------------------------------------------------------------------------
// eventropies (feeed/complexity/eventropies.py)
// ---------------------------------------------------------------------------

function eventropyKBlock(seqs, k) {
  const counts = new Map();
  let total = 0;
  seqs.forEach((seq) => {
    for (let i = 0; i <= seq.length - k; i += 1) {
      const key = variantKey(seq.slice(i, i + k));
      counts.set(key, (counts.get(key) || 0) + 1);
      total += 1;
    }
  });
  return round3(m.shannonEntropyBase2([...counts.values()], total));
}

function round3(x) {
  return Math.round(x * 1000) / 1000;
}

const KNN_GAMMA_1_5 = Math.sqrt(Math.PI) / 2; // math.gamma(1.5), d=1 fixed in feeed

function findNearestNeighborDistances(variantList, k) {
  const n = variantList.length;
  const dist = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let i = 0; i < n; i += 1) {
    for (let j = i + 1; j < n; j += 1) {
      const d = m.levenshteinDistance(variantList[i], variantList[j]);
      dist[i][j] = d;
      dist[j][i] = d;
    }
  }
  const neighbours = [];
  for (let i = 0; i < n; i += 1) {
    const normalized = [];
    for (let j = 0; j < n; j += 1) {
      if (i === j) continue;
      normalized.push(dist[i][j] / Math.max(variantList[i].length, variantList[j].length));
    }
    normalized.sort((a, b) => a - b);
    const filtered = normalized.filter((d) => d !== 0);
    neighbours.push(filtered[k - 1]);
  }
  return neighbours;
}

function eventropyFlattenedKnn(variantList, k) {
  const d = 1;
  const n = variantList.length;
  const neighbours = findNearestNeighborDistances(variantList, k);
  let knnEntropy = 0;
  neighbours.forEach((normalizedLev) => {
    const part2 = Math.log(normalizedLev);
    const part3 = Math.log(KNN_GAMMA_1_5 === 0 ? 0 : Math.pow(Math.PI, d / 2) / KNN_GAMMA_1_5);
    const part4 = 0.5772;
    const part5 = m.harmonicSum(k - 1);
    const part6 = Math.log(n);
    knnEntropy += (d / n) * (part2 + part3 + part4 - part5 + part6);
  });
  return round3(knnEntropy);
}

/** Counts occurrences of every PREFIX of every trace in O(sum(L_i)) time via
 * a trie, instead of re-serializing the growing prefix array at each step
 * (which is O(sum(L_i^2)) and can exhaust memory on long traces). */
function countAllPrefixes(seqs) {
  const root = new Map();
  let total = 0;
  seqs.forEach((seq) => {
    let node = root;
    seq.forEach((activity) => {
      let entry = node.get(activity);
      if (!entry) {
        entry = { count: 0, children: new Map() };
        node.set(activity, entry);
      }
      entry.count += 1;
      total += 1;
      node = entry.children;
    });
  });
  // Iterative traversal — a recursive walk would blow the call stack on
  // traces with hundreds/thousands of events (stack depth == trace length).
  const counts = [];
  const stack = [root];
  while (stack.length > 0) {
    const node = stack.pop();
    node.forEach((entry) => {
      counts.push(entry.count);
      stack.push(entry.children);
    });
  }
  return { counts, total };
}

/** Shannon entropy (base 2) of the occurrence counts of every contiguous
 * substring of every trace — feeed's eventropy_global_block — without listing
 * the O(sum(L_i^2)) substrings: a generalized suffix automaton over all traces
 * groups substrings that occur at the same end positions (hence share one
 * count), in O(sum(L_i)) states, so long traces need no size limit. */
function globalBlockEntropy(seqs) {
  const length = [0];
  const link = [-1];
  const next = [new Map()];
  const count = [0];
  const addState = (len, transitions = new Map(), suffixLink = -1) => {
    length.push(len);
    link.push(suffixLink);
    next.push(transitions);
    count.push(0);
    return length.length - 1;
  };
  const splitState = (p, q, activity) => {
    const clone = addState(length[p] + 1, new Map(next[q]), link[q]);
    let s = p;
    while (s !== -1 && next[s].get(activity) === q) {
      next[s].set(activity, clone);
      s = link[s];
    }
    link[q] = clone;
    return clone;
  };

  let total = 0;
  seqs.forEach((seq) => {
    let last = 0;
    seq.forEach((activity) => {
      if (next[last].has(activity)) {
        const q = next[last].get(activity);
        last = length[q] === length[last] + 1 ? q : splitState(last, q, activity);
        count[last] += 1;
        return;
      }
      const cur = addState(length[last] + 1);
      count[cur] = 1;
      let p = last;
      while (p !== -1 && !next[p].has(activity)) {
        next[p].set(activity, cur);
        p = link[p];
      }
      if (p === -1) link[cur] = 0;
      else {
        const q = next[p].get(activity);
        link[cur] = length[q] === length[p] + 1 ? q : splitState(p, q, activity);
      }
      last = cur;
    });
    total += (seq.length * (seq.length + 1)) / 2;
  });

  // occurrences of a state's substrings = its own end positions + those of its suffix-link subtree
  const byLength = [...length.keys()].sort((a, b) => length[b] - length[a]);
  byLength.forEach((v) => {
    if (v !== 0) count[link[v]] += count[v];
  });

  let entropy = 0;
  byLength.forEach((v) => {
    if (v === 0) return;
    const p = count[v] / total;
    entropy -= (length[v] - length[link[v]]) * p * Math.log2(p);
  });
  return entropy;
}

function eventropies(seqs, variantIndex) {
  const nTraces = seqs.length;

  const traceCounts = new Map();
  seqs.forEach((seq) => {
    const key = variantKey(seq);
    traceCounts.set(key, (traceCounts.get(key) || 0) + 1);
  });
  const eventropy_trace = round3(m.shannonEntropyBase2([...traceCounts.values()], nTraces));

  const { counts: prefixCounts, total: totalPrefixes } = countAllPrefixes(seqs);
  const eventropy_prefix = round3(m.shannonEntropyBase2(prefixCounts, totalPrefixes));

  const eventropy_global_block = round3(globalBlockEntropy(seqs));

  // Lempel-Ziv: token-level LZ76 parse (words built by string-concatenating
  // raw activity names with no separator, exactly as feeed does), over
  // distinct (exact-duplicate-deduped) traces only, but N counts every trace.
  let N = 0;
  const words = new Set();
  const seen = new Set();
  seqs.forEach((seq) => {
    const key = variantKey(seq);
    if (!seen.has(key)) {
      seen.add(key);
      let word = '';
      seq.forEach((activity) => {
        word += activity;
        if (!words.has(word)) {
          words.add(word);
          word = '';
        }
      });
    }
    N += seq.length;
  });
  const eventropy_lempel_ziv = round3((words.size * Math.log2(N)) / N);

  const kBlock = (k) => eventropyKBlock(seqs, k);
  const eventropy_k_block_diff_1 = round3(kBlock(1) - kBlock(0));
  const eventropy_k_block_diff_3 = round3(kBlock(3) - kBlock(2));
  const eventropy_k_block_diff_5 = round3(kBlock(5) - kBlock(4));
  const eventropy_k_block_ratio_1 = round3(kBlock(1) / 1);
  const eventropy_k_block_ratio_3 = round3(kBlock(3) / 3);
  const eventropy_k_block_ratio_5 = round3(kBlock(5) / 5);

  // KNN eventropy needs a full pairwise Levenshtein distance matrix over
  // variants (O(V^2), each cell O(len1*len2)) — skip for logs with too many
  // distinct variants rather than risk hanging/crashing the browser tab.
  const variantList = [...variantIndex.values()].map((v) => v.seq);
  const knn = (k) => (variantList.length > k && variantList.length <= KNN_VARIANT_LIMIT ? eventropyFlattenedKnn(variantList, k) : null);

  return {
    eventropy_trace,
    eventropy_prefix,
    eventropy_global_block,
    eventropy_lempel_ziv,
    eventropy_k_block_diff_1,
    eventropy_k_block_diff_3,
    eventropy_k_block_diff_5,
    eventropy_k_block_ratio_1,
    eventropy_k_block_ratio_3,
    eventropy_k_block_ratio_5,
    eventropy_knn_3: knn(3),
    eventropy_knn_5: knn(5),
    eventropy_knn_7: knn(7),
  };
}

// ---------------------------------------------------------------------------
// epa_based (feeed/complexity/epa_based.py) — Entropic Prefix Automaton
// ---------------------------------------------------------------------------

/** Builds the prefix automaton over the whole log's events in GLOBAL
 * chronological order (across all cases), exactly as feeed's generate_log +
 * build_graph do: each case's consecutive events extend a "chain" of nodes
 * rooted at a shared root; a node's `c` ("cluster") id is inherited from its
 * predecessor's first-ever successor, or freshly allocated when the
 * predecessor already branches elsewhere. */
function buildEpa(traces) {
  const events = [];
  traces.forEach((trace) => {
    trace.events.forEach((e) => {
      events.push({
        caseId: trace.caseId,
        activity: e.activity,
        // microseconds, as feeed/pandas keep them (epaBased only calls this when all are present)
        timestamp: e.timeMicros,
      });
    });
  });

  // Stable sort by timestamp, matching feeed's `log.sort(key=...timestamp)`.
  events.sort((a, b) => a.timestamp - b.timestamp);

  const root = { name: 'root', successors: new Map(), c: 0, j: 0, sequence: [] };
  const nodes = [root];
  // Grouped by activity name, in first-occurrence order, mirroring Python's
  // `pa.activity_types: {activity: [nodes...]}` dict exactly — logComplexity
  // sums per-event floating-point weights over this flattened order, and
  // floating-point addition isn't associative, so matching Python's grouping
  // (not just the same *set* of nodes) is required for bit-identical sums.
  const activityTypesByName = new Map();
  const lastNodeForCase = new Map();
  let c = 1;

  events.forEach((event) => {
    const predNode = lastNodeForCase.has(event.caseId) ? lastNodeForCase.get(event.caseId) : root;

    let node = predNode.successors.get(event.activity);
    if (!node) {
      let currC;
      if (predNode.successors.size > 0) {
        c += 1;
        currC = c;
      } else {
        currC = predNode !== root ? predNode.c : c;
      }
      node = { name: `${event.activity}#${nodes.length}`, successors: new Map(), c: currC, j: predNode.j + 1, sequence: [] };
      predNode.successors.set(event.activity, node);
      nodes.push(node);
      if (!activityTypesByName.has(event.activity)) activityTypesByName.set(event.activity, []);
      activityTypesByName.get(event.activity).push(node);
    }
    node.sequence.push(event);
    lastNodeForCase.set(event.caseId, node);
  });

  const activityTypeNodes = [...activityTypesByName.values()].flat();

  nodes.sort((a, b) => (a.c - b.c) || (a.j - b.j));

  const cIndex = new Map();
  nodes.forEach((node) => {
    if (!cIndex.has(node.c)) cIndex.set(node.c, []);
    cIndex.get(node.c).push(node);
  });
  cIndex.forEach((list) => list.sort((a, b) => a.j - b.j));

  // `events` is sorted by timestamp, so its ends are the min/max (avoids
  // Math.max(...bigArray), which overflows the stack on large logs).
  const firstTimestamp = events[0].timestamp;
  const lastTimestamp = events[events.length - 1].timestamp;
  const timespanSeconds = Math.max((lastTimestamp - firstTimestamp) / 1e6, 1e-6);

  return { nodes, activityTypeNodes, cIndex, lastTimestamp, timespanSeconds };
}

function clusterKeysExceptFirst(cIndex) {
  return [...cIndex.keys()].sort((a, b) => a - b).slice(1);
}

function safeLogTimesX(x) {
  if (x <= 0) return Math.log(1e-6) * 1e-6;
  return Math.log(x) * x;
}

function graphComplexity(epa) {
  const nReal = epa.nodes.length - 1;
  let complexity = Math.log(nReal) * nReal;
  const normalize = complexity;
  clusterKeysExceptFirst(epa.cIndex).forEach((c) => {
    const e = epa.cIndex.get(c).length;
    complexity -= Math.log(e) * e;
  });
  return [complexity, complexity / normalize];
}

function logComplexity(epa, forgetting) {
  const totalEvents = m.sum(epa.activityTypeNodes.map((n) => n.sequence.length));
  const normalize = totalEvents * Math.log(totalEvents);

  if (!forgetting) {
    let complexity = Math.log(totalEvents) * totalEvents;
    clusterKeysExceptFirst(epa.cIndex).forEach((c) => {
      const e = m.sum(epa.cIndex.get(c).map((n) => n.sequence.length));
      complexity -= Math.log(e) * e;
    });
    return [complexity, complexity / normalize];
  }

  const weight = (event) => {
    const elapsed = (epa.lastTimestamp - event.timestamp) / 1e6;
    if (forgetting === 'linear') return 1 - elapsed / epa.timespanSeconds;
    return Math.exp((-elapsed / epa.timespanSeconds) * 1); // k=1, exponential forgetting
  };

  let complexity = safeLogTimesX(m.sum(epa.activityTypeNodes.flatMap((n) => n.sequence.map(weight))));
  clusterKeysExceptFirst(epa.cIndex).forEach((c) => {
    const e = m.sum(epa.cIndex.get(c).flatMap((n) => n.sequence.map(weight)));
    complexity -= safeLogTimesX(e);
  });
  return [complexity, complexity / normalize];
}

/** Number of events without a (parseable) timestamp. */
export function countMissingTimestamps(traces) {
  return m.sum(traces.map((t) => t.events.filter((e) => e.timeMicros == null).length));
}

function epaBased(traces) {
  // The EPA orders events by time; with any timestamp missing that order (and
  // hence every EPA value) is undefined, so report none rather than an artifact
  // of how missing values happen to sort.
  if (traces.length === 0 || traces.every((t) => t.events.length === 0) || countMissingTimestamps(traces) > 0) {
    return {
      epa_variant_entropy: null, epa_normalized_variant_entropy: null,
      epa_sequence_entropy: null, epa_normalized_sequence_entropy: null,
      epa_sequence_entropy_linear_forgetting: null, epa_normalized_sequence_entropy_linear_forgetting: null,
      epa_sequence_entropy_exponential_forgetting: null, epa_normalized_sequence_entropy_exponential_forgetting: null,
    };
  }
  const epa = buildEpa(traces);
  const [gV, gVn] = graphComplexity(epa);
  const [sV, sVn] = logComplexity(epa, null);
  const [lV, lVn] = logComplexity(epa, 'linear');
  const [eV, eVn] = logComplexity(epa, 'exp');
  return {
    epa_variant_entropy: gV,
    epa_normalized_variant_entropy: gVn,
    epa_sequence_entropy: sV,
    epa_normalized_sequence_entropy: sVn,
    epa_sequence_entropy_linear_forgetting: lV,
    epa_normalized_sequence_entropy_linear_forgetting: lVn,
    epa_sequence_entropy_exponential_forgetting: eV,
    epa_normalized_sequence_entropy_exponential_forgetting: eVn,
  };
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

function flattenedEventropies(seqs) {
  const variants = [];
  const seen = new Set();
  seqs.forEach((seq) => {
    const key = variantKey(seq);
    if (!seen.has(key)) {
      seen.add(key);
      variants.push(seq);
    }
  });
  const { counts, total } = countAllPrefixes(variants);
  let N = 0;
  const words = new Set();
  variants.forEach((seq) => {
    let word = '';
    seq.forEach((activity) => {
      word += activity;
      if (!words.has(word)) {
        words.add(word);
        word = '';
      }
    });
    N += seq.length;
  });
  return {
    prefixFlattened: round3(m.shannonEntropyBase2(counts, total)),
    lempelZivFlattened: round3((words.size * Math.log2(N)) / N),
    globalBlockFlattened: round3(globalBlockEntropy(variants)),
  };
}

export function computeAllFeeedFeatures(traces, featureSet = 'all') {
  const base = computeFeeedFeatures(traces);
  const subset = featureSetNames(featureSet);
  const extra = computeExtraFeatures(traces, {
    ...flattenedEventropies(activitySequences(traces)),
    nUniqueActivities: base.n_unique_activities,
    nUniqueStartActivities: base.n_unique_start_activities,
    nUniqueEndActivities: base.n_unique_end_activities,
    defaultOnly: Boolean(subset),
  });
  const all = Object.fromEntries(Object.entries({ ...base, ...extra }).filter(([name]) => !isExcludedFeature(name)));
  return subset ? Object.fromEntries(subset.map((name) => [name, all[name] ?? null])) : all;
}

/** FEEED features of the given feature set (see featureSets.json) plus warnings
 * to show the contributor about values that could not be computed. */
export function analyzeTraces(traces, featureSet = 'all') {
  const features = computeAllFeeedFeatures(traces, featureSet);
  const warnings = [];
  const missing = countMissingTimestamps(traces);
  if (missing > 0) {
    const total = m.sum(traces.map((t) => t.events.length));
    warnings.push(
      missing === total
        ? 'No event has a timestamp, so the EPA-based and time-based features cannot be computed.'
        : `${missing} of ${total} events have no timestamp: the EPA-based features cannot be computed, and the time-based features use only the ${total - missing} events with a timestamp.`
    );
  }
  return { features, warnings };
}

/** Computes the 90 base-group FEEED 2.2.0 features for a parsed XES
 * log's `traces` (see parseXes.js). Requires every trace to have at least one
 * event, and at least 2 traces for several statistics to be meaningful. */
export function computeFeeedFeatures(traces) {
  const seqs = activitySequences(traces);
  const variantIndex = buildVariantIndex(seqs);

  return {
    ...simpleStats(seqs, variantIndex),
    ...traceLength(seqs),
    ...traceVariant(seqs, variantIndex),
    ...activityStats(seqs),
    ...boundaryActivityStats(seqs, { end: false, marker: 'START', prefix: 'start_activities', nUniqueKey: 'n_unique_start_activities' }),
    ...boundaryActivityStats(seqs, { end: true, marker: 'END', prefix: 'end_activities', nUniqueKey: 'n_unique_end_activities' }),
    ...eventropies(seqs, variantIndex),
    ...epaBased(traces),
  };
}
