import { useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { createLandscape } from '@/viz/landscape';

export default function LandscapeVisualization({ datasets, concept, colors }) {
  const containerRef = useRef(null);
  const navigate = useNavigate();

  useEffect(() => {
    if (!containerRef.current || datasets.length === 0) return undefined;

    const opts = { concept, colors, onDatasetClick: (id) => navigate(`/datasets/${id}`) };
    let instance = createLandscape(containerRef.current, datasets, opts);

    const handleResize = () => {
      instance.destroy();
      instance = createLandscape(containerRef.current, datasets, opts);
    };
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      instance.destroy();
    };
  }, [datasets, concept, colors, navigate]);

  return <div className="landscape-viz" ref={containerRef} />;
}
