import { analyzeTraces } from './feeedFeatures.js';

function runInWorker(traces, featureSet) {
  return new Promise((resolve, reject) => {
    let worker;
    try {
      worker = new Worker(new URL('./featuresWorker.js', import.meta.url), { type: 'module' });
    } catch (e) {
      reject(Object.assign(new Error(e.message || 'The feature worker could not start.'), { workerFailed: true }));
      return;
    }
    worker.onmessage = ({ data }) => {
      worker.terminate();
      if (data.error) reject(new Error(data.error));
      else resolve(data);
    };
    worker.onerror = (event) => {
      worker.terminate();
      event.preventDefault?.();
      reject(Object.assign(new Error(event.message || 'The feature worker could not start.'), { workerFailed: true }));
    };
    worker.postMessage({ traces, featureSet });
  });
}

export async function analyzeInWorker(traces, featureSet = 'default') {
  try {
    return await runInWorker(traces, featureSet);
  } catch (e) {
    if (!e.workerFailed) throw e;
    await new Promise((resolve) => setTimeout(resolve, 0));
    return analyzeTraces(traces, featureSet);
  }
}
