const STORAGE_KEY = 'xespresso:user-logs';

export function getStoredUserDatasets() {
  if (typeof localStorage === 'undefined') return [];
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function persist(records) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
  } catch {
    return false;
  }
  return true;
}

export function addStoredUserDataset(record) {
  return persist([...getStoredUserDatasets(), record]);
}

export function markStoredUserDatasetsSent(userKeys, sent) {
  const keys = new Set(userKeys);
  return persist(getStoredUserDatasets().map((r) => (keys.has(r._userKey) ? { ...r, _sent: sent } : r)));
}

export function removeStoredUserDataset(userKey) {
  persist(getStoredUserDatasets().filter((r) => r._userKey !== userKey));
}
