export function isHidden(record) {
  return Boolean(record.hidden);
}

export function getDomainApplication(record) {
  return record.domain_context?.domain_application || null;
}

export const FACETS = [
  {
    key: 'domain_application',
    label: 'Domain Application',
    getValues: (r) => (r.domain_context?.domain_application ? [r.domain_context.domain_application] : []),
  },
  {
    key: 'event_log_type',
    label: 'Event Log Type',
    getValues: (r) => (r.domain_context?.event_log_type ? [r.domain_context.event_log_type] : []),
  },
  {
    key: 'process_type',
    label: 'Process Type',
    getValues: (r) => (r.domain_context?.process_type ? [r.domain_context.process_type] : []),
  },
  {
    key: 'publication_type',
    label: 'Publication Type',
    getValues: (r) => (r.academic_context?.publication_type ? [r.academic_context.publication_type] : []),
  },
  {
    key: 'dataset_format',
    label: 'Dataset Format',
    getValues: (r) => (r.basic_info?.dataset_format ? [r.basic_info.dataset_format] : []),
  },
  {
    key: 'resource_availability',
    label: 'Resource Availability',
    getValues: (r) => [r.basic_info?.resource_availability ? 'Yes' : 'No'],
  },
  {
    key: 'feeed_available',
    label: 'FEEED Features',
    getValues: (r) => [r.feeed_available ? 'Computed' : 'Not computed'],
  },
];

export function getFacetOptions(records, facet) {
  const counts = {};
  records.forEach((r) => {
    facet.getValues(r).forEach((v) => {
      counts[v] = (counts[v] || 0) + 1;
    });
  });
  return Object.entries(counts)
    .sort((a, b) => b[1] - a[1])
    .map(([value, count]) => ({ value, count }));
}

export function matchesFacetFilters(record, facetFilters) {
  return FACETS.every((facet) => {
    const selected = facetFilters[facet.key];
    if (!selected || selected.length === 0) return true;
    const values = facet.getValues(record);
    return selected.some((v) => values.includes(v));
  });
}
