import { useNavigate } from 'react-router-dom';
import { getDomainApplication } from '@/lib/filters';

function formatNumber(n) {
  if (n === null || n === undefined) return '—';
  return n.toLocaleString();
}

export default function EventLogCard({ dataset, domainColors }) {
  const navigate = useNavigate();
  const { basic_info: basicInfo, domain_context: domainContext, academic_context: academicContext } = dataset;
  const domain = getDomainApplication(dataset);
  const color = domainColors[domain];

  return (
    <article
      className={`log-card ${dataset._userAdded ? 'log-card--user-added' : ''}`}
      onClick={() => navigate(`/datasets/${dataset._id}`)}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          navigate(`/datasets/${dataset._id}`);
        }
      }}
      tabIndex={0}
      role="button"
    >
      {dataset._userAdded && <span className="user-added-badge">+ Added by you</span>}
      <div className="log-card__badges">
        {domain && (
          <span className="log-card__badge" style={{ '--domain-color': color }}>
            {domain}
          </span>
        )}
        {domainContext?.event_log_type && <span className="chip chip--sm">{domainContext.event_log_type}</span>}
        {dataset.feeed_available && <span className="chip chip--sm">FEEED features</span>}
      </div>
      <h3 className="log-card__title">{basicInfo.event_log_name}</h3>
      <p className="log-card__meta">
        {academicContext?.year ? `${academicContext.year} · ` : ''}
        {academicContext?.reference || domainContext?.process_information || 'No reference on file'}
      </p>
      <p className="log-card__goal">
        {formatNumber(basicInfo.number_of_cases)} cases · {formatNumber(basicInfo.number_of_events)} events ·{' '}
        {formatNumber(basicInfo.number_of_activities)} activities
      </p>
    </article>
  );
}
