const RIDGE = 1e-4;
const EPS = 1e-6;

export function selectionCurves(order, matrix, featureIndex, minK = 2) {
  const all = Object.keys(featureIndex);
  const n = all.length;
  const r = (a, b) => {
    const v = matrix[featureIndex[a]][featureIndex[b]];
    return Number.isFinite(v) ? v : 0;
  };
  const basis = [];
  let inv = [];
  const r2 = new Array(n).fill(0);
  const selected = new Set();
  const curve = [];
  let sum = 0;
  let pairs = 0;

  order.forEach((name, idx) => {
    for (let j = 0; j < idx; j += 1) {
      const v = matrix[featureIndex[name]][featureIndex[order[j]]];
      if (Number.isFinite(v)) {
        sum += Math.abs(v);
        pairs += 1;
      }
    }
    selected.add(name);

    const b = basis.map((s) => r(s, name));
    const w = inv.map((row) => row.reduce((acc, v, i) => acc + v * b[i], 0));
    const s = 1 + RIDGE - b.reduce((acc, v, i) => acc + v * w[i], 0);
    if (s > EPS) {
      all.forEach((f, j) => {
        const g = r(f, name) - basis.reduce((acc, bf, i) => acc + r(f, bf) * w[i], 0);
        r2[j] += (g * g) / s;
      });
      inv = [...inv.map((row, i) => [...row.map((v, c) => v + (w[i] * w[c]) / s), -w[i] / s]), [...w.map((v) => -v / s), 1 / s]];
      basis.push(name);
    }

    const k = idx + 1;
    if (k < minK || !pairs) return;
    const explained = all.reduce((acc, f, j) => acc + (selected.has(f) ? 1 : Math.min(1, r2[j])), 0) / n;
    curve.push({ k, mean: sum / pairs, explained });
  });
  return curve;
}
