import { useEffect, useMemo, useRef, useState } from 'react';

const BASE_WIDTH = 120;
const GAP = 12;

function layoutOneRow(domains, counts, width) {
  const logs = domains.reduce((s, d) => s + Math.max(counts[d.id] || 0, 1), 0);
  const pxPerLog = (width - domains.length * BASE_WIDTH - (domains.length - 1) * GAP) / logs;
  if (pxPerLog <= 0) return null;
  return { rows: [[...domains].sort((a, b) => (counts[b.id] || 0) - (counts[a.id] || 0))], pxPerLog };
}

function layoutTwoRows(domains, counts, width) {
  const n = domains.length;
  if (!width || n === 0) return null;
  if (n <= 6) {
    const single = layoutOneRow(domains, counts, width);
    if (single) return single;
  }
  if (n < 2) return null;
  let best = null;
  for (let mask = 1; mask < (1 << n) - 1; mask++) {
    if (mask & 1) continue;
    const rows = [[], []];
    domains.forEach((d, i) => rows[(mask >> i) & 1].push(d));
    const pxPerLog = Math.min(
      ...rows.map((row) => {
        const logs = row.reduce((s, d) => s + Math.max(counts[d.id] || 0, 1), 0);
        return (width - row.length * BASE_WIDTH - (row.length - 1) * GAP) / logs;
      })
    );
    if (!best || pxPerLog > best.pxPerLog) best = { rows, pxPerLog };
  }
  if (!best || best.pxPerLog <= 0) return null;
  const byCount = (a, b) => (counts[b.id] || 0) - (counts[a.id] || 0);
  const rows = best.rows.map((row) => [...row].sort(byCount));
  rows.sort((a, b) => b.reduce((s, d) => s + (counts[d.id] || 0), 0) - a.reduce((s, d) => s + (counts[d.id] || 0), 0));
  return { rows, pxPerLog: best.pxPerLog };
}

function useElementWidth(ref) {
  const [width, setWidth] = useState(0);
  useEffect(() => {
    if (!ref.current) return undefined;
    const observer = new ResizeObserver(([entry]) => setWidth(entry.contentRect.width));
    observer.observe(ref.current);
    return () => observer.disconnect();
  }, [ref]);
  return width;
}

export default function DomainApplicationsOverview({ items: domainApplications, valueOf, datasets, selected, onToggle, title, hint, control }) {
  const gridRef = useRef(null);
  const width = useElementWidth(gridRef);

  const counts = useMemo(() => {
    const c = {};
    datasets.forEach((d) => {
      const value = valueOf(d);
      c[value] = (c[value] || 0) + 1;
    });
    return c;
  }, [datasets, valueOf]);

  const layout = useMemo(() => layoutTwoRows(domainApplications, counts, width), [domainApplications, counts, width]);
  const rows = layout
    ? layout.rows
    : [[...domainApplications].sort((a, b) => (counts[b.id] || 0) - (counts[a.id] || 0))];

  return (
    <section className="domain-overview">
      <div className="domain-overview__header">
        <div className="section-head">
          <h2 className="domain-overview__title">{title}</h2>
          {control}
        </div>
        {hint && <p className="domain-overview__hint">{hint}</p>}
      </div>
      <div className={`domain-overview__grid ${layout ? '' : 'domain-overview__grid--wrap'}`} ref={gridRef}>
        {rows.map((row, i) => (
          <div className="domain-overview__row" key={i}>
            {row.map((domain) => {
              const isActive = selected.includes(domain.id);
              const count = counts[domain.id] || 0;
              const cardWidth = layout ? BASE_WIDTH + Math.max(count, 1) * layout.pxPerLog : undefined;
              return (
                <button
                  key={domain.id}
                  type="button"
                  className={`domain-card ${isActive ? 'domain-card--active' : ''}`}
                  style={{ '--domain-color': domain.color, ...(cardWidth && { width: cardWidth }) }}
                  onClick={() => onToggle(domain.id)}
                  aria-pressed={isActive}
                >
                  <span className="domain-card__swatch" />
                  <span className="domain-card__label">{domain.label}</span>
                  <span className="domain-card__count">{count}</span>
                </button>
              );
            })}
          </div>
        ))}
      </div>
    </section>
  );
}
