/**
 * Statistics primitives matching numpy/scipy's exact conventions, since
 * every FEEED feature (see feeedFeatures.js) is defined in terms of them.
 * Reference: numpy.mean/std/var/percentile, scipy.stats.{mode,iqr,gmean,
 * gstd,hmean,skew,kurtosis,variation,entropy}. All are population
 * (bias=True / ddof=0) statistics except gstd (ddof=1), matching scipy's
 * defaults exactly — this file exists specifically to avoid silently
 * drifting from those defaults.
 */

export function sum(arr) {
  return arr.reduce((a, b) => a + b, 0);
}

export function mean(arr) {
  return sum(arr) / arr.length;
}

/** numpy.var: population variance (ddof=0). */
export function variance(arr) {
  const m = mean(arr);
  return sum(arr.map((x) => (x - m) ** 2)) / arr.length;
}

/** numpy.std: population std (ddof=0). */
export function std(arr) {
  return Math.sqrt(variance(arr));
}

// Manual reduce instead of Math.min/max(...arr): spreading a large array as
// call arguments stack-overflows past a few tens of thousands of elements.
export function min(arr) {
  return arr.reduce((a, b) => (b < a ? b : a), arr[0]);
}

export function max(arr) {
  return arr.reduce((a, b) => (b > a ? b : a), arr[0]);
}

export function median(arr) {
  return percentile(arr, 50);
}

/** scipy.stats.mode(..., keepdims=False): smallest most-frequent value. */
export function mode(arr) {
  const counts = new Map();
  arr.forEach((v) => counts.set(v, (counts.get(v) || 0) + 1));
  let best = null;
  let bestCount = -1;
  [...counts.keys()].sort((a, b) => a - b).forEach((v) => {
    const c = counts.get(v);
    if (c > bestCount) {
      bestCount = c;
      best = v;
    }
  });
  return best;
}

/** numpy.percentile default (linear interpolation between order statistics). */
export function percentile(arr, p) {
  const sorted = [...arr].sort((a, b) => a - b);
  const n = sorted.length;
  if (n === 1) return sorted[0];
  const rank = (p / 100) * (n - 1);
  const lo = Math.floor(rank);
  const hi = Math.ceil(rank);
  if (lo === hi) return sorted[lo];
  return sorted[lo] + (sorted[hi] - sorted[lo]) * (rank - lo);
}

/** scipy.stats.iqr default: Q3 - Q1. */
export function iqr(arr) {
  return percentile(arr, 75) - percentile(arr, 25);
}

/** scipy.stats.gmean: exp(mean(log(x))). */
export function gmean(arr) {
  return Math.exp(mean(arr.map((x) => Math.log(x))));
}

/** scipy.stats.gstd: exp(std(log(x), ddof=1)) — SAMPLE std of the logs. */
export function gstd(arr) {
  const logs = arr.map((x) => Math.log(x));
  const m = mean(logs);
  const sampleVar = sum(logs.map((x) => (x - m) ** 2)) / (logs.length - 1);
  return Math.exp(Math.sqrt(sampleVar));
}

/** scipy.stats.hmean: n / sum(1/x). */
export function hmean(arr) {
  return arr.length / sum(arr.map((x) => 1 / x));
}

/** scipy.stats.skew default (bias=True): population (Fisher-Pearson) skewness. */
export function skew(arr) {
  const m = mean(arr);
  const s = std(arr);
  if (s === 0) return NaN;
  const m3 = mean(arr.map((x) => (x - m) ** 3));
  return m3 / s ** 3;
}

/** scipy.stats.kurtosis default (fisher=True, bias=True): excess kurtosis. */
export function kurtosis(arr) {
  const m = mean(arr);
  const v = variance(arr);
  if (v === 0) return NaN;
  const m4 = mean(arr.map((x) => (x - m) ** 4));
  return m4 / v ** 2 - 3;
}

/** scipy.stats.variation default (ddof=0): std/mean (coefficient of variation). */
export function variation(arr) {
  return std(arr) / mean(arr);
}

/** scipy.stats.entropy(arr): normalizes arr to a distribution (pk = arr/sum(arr))
 * then computes Shannon entropy in NATS (natural log) — not a distribution
 * over distinct values, the raw array itself is treated as unnormalized weights. */
export function entropyOfWeights(arr) {
  const total = sum(arr);
  return -sum(arr.map((x) => {
    const p = x / total;
    return p === 0 ? 0 : p * Math.log(p);
  }));
}

/** Shannon entropy (base 2) of a frequency Counter's values — used by every
 * FEEED eventropy_* feature (feeed/complexity/eventropies.py), NOT the same
 * as entropyOfWeights (base e, no distinct-value counting). */
export function shannonEntropyBase2(counts, total) {
  return -sum(counts.map((count) => {
    const p = count / total;
    return p * Math.log2(p);
  }));
}

/** numpy.histogram(arr, bins=10, density=True): 10 equal-width bins over
 * [min(arr), max(arr)], heights normalized so the total area is 1. */
export function histogramDensity10(arr) {
  let lo = min(arr);
  let hi = max(arr);
  if (lo === hi) {
    lo -= 0.5;
    hi += 0.5;
  }
  const bins = new Array(10).fill(0);
  const width = (hi - lo) / 10;
  arr.forEach((x) => {
    let idx = Math.floor((x - lo) / width);
    if (idx === 10) idx = 9; // right edge inclusive, like numpy
    bins[idx] += 1;
  });
  const n = arr.length;
  return bins.map((count) => count / (n * width));
}

/** Levenshtein distance over a SEQUENCE of tokens (e.g. activity names), not
 * characters — matches Python's Levenshtein.distance(tuple_of_strings, ...)
 * semantics used in feeed's kNN eventropy, where each token is one unit. */
export function levenshteinDistance(a, b) {
  const m = a.length;
  const n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  let prev = new Array(n + 1);
  let curr = new Array(n + 1);
  for (let j = 0; j <= n; j += 1) prev[j] = j;
  for (let i = 1; i <= m; i += 1) {
    curr[0] = i;
    for (let j = 1; j <= n; j += 1) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      curr[j] = Math.min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost);
    }
    [prev, curr] = [curr, prev];
  }
  return prev[n];
}

/** Harmonic sum L_j = sum_{i=1}^{j} 1/i (feeed's kNN entropy uses this for the
 * Kozachenko-Leonenko bias correction term). */
export function harmonicSum(j) {
  if (j < 0) return null;
  if (j === 0) return 0;
  let total = 0;
  for (let i = 1; i <= j; i += 1) total += 1 / i;
  return total;
}
