import { useMemo, useRef, useState } from 'react';
import { addUserDataset } from '@/lib/data';
import { isHidden } from '@/lib/filters';
import { parseXesText } from '@/lib/xes/parseXes';
import { computeLogStats } from '@/lib/xes/xesLogStats';
import { analyzeInWorker } from '@/lib/xes/analyzeInWorker';
import { estimatedSize, formatMB, isAcceptedFile, isCsvFile, readXesFile } from '@/lib/xes/readXesFile';
import { csvToTraces, detectDateOrder, guessMapping, parseCsvText, parseCsvTimestamp } from '@/lib/xes/parseCsv';
import { lookupDoi } from '@/lib/doiLookup';
import { normalizeFeatureSet } from '@/lib/featureSets';
import { SendEntriesPanel } from '@/components/SendEntriesModal';
import InfoTip from '@/components/InfoTip';
import { COSTA_SOURCE, FIELD_INFO } from '@/lib/fieldDefinitions';

const CSV_ROLES = [
  { role: 'caseId', label: 'Case ID', required: true },
  { role: 'activity', label: 'Activity', required: true },
  { role: 'timestamp', label: 'Timestamp', required: true },
  { role: 'resource', label: 'Resource', required: false },
];

const EMPTY_FORM = {
  name: '',
  source: '',
  year: '',
  reference: '',
  processInformation: '',
  domainApplication: '',
  eventLogType: '',
  processType: '',
  publicationType: '',
  domainApplicationOther: '',
  publicationTypeOther: '',
  publicRecord: false,
  website: '',
  resourceType: '',
  notes: '',
  eventLogYear: '',
  activityLabel: 'yes',
  performanceIssues: '',
  performanceNotes: '',
  prominentBehavior: '',
  prominentBehaviorOther: '',
  primaryDependency: '',
  primaryDependencyCoverage: '',
  consistency: '',
  observedPath: '',
  pathNotes: '',
};

const NOT_PUBLISHED = 'Not Published';

function suggestedEventLogYear(analysis) {
  const end = analysis?.stats.basic_info.end_date;
  return end ? end.slice(0, 4) : '';
}

function newForm(analysis, extra = {}) {
  return { ...EMPTY_FORM, ...extra, name: baseName(analysis.fileName), eventLogYear: suggestedEventLogYear(analysis) };
}

const text = (v) => String(v ?? '').trim() || null;
const number = (v) => (String(v ?? '').trim() === '' || !Number.isFinite(Number(v)) ? null : Number(v));

const DEFAULT_FILE_SIZE_MB = { warn: 100, max: 300 };
const MB = 1024 * 1024;

const DEFAULT_REQUIRED = ['name', 'source', 'description', 'domainApplication', 'eventLogType', 'resourceType', 'year'];

const FIELD_LABELS = {
  name: 'Name',
  source: 'Source (URL or DOI)',
  year: 'Year',
  reference: 'Reference',
  description: 'Process description',
  domainApplication: 'Domain Application',
  eventLogType: 'Event Log Type',
  processType: 'Process Type',
  publicationType: 'Publication Type',
  resourceType: 'Resource type',
};

function fieldValue(form, analysis, id) {
  switch (id) {
    case 'source':
      return form.publicRecord ? form.source.trim() : 'not public';
    case 'description':
      return form.processInformation.trim();
    case 'domainApplication':
    case 'publicationType':
      return choice(form, id);
    case 'resourceType':
      return analysis?.stats.basic_info.resource_availability ? form.resourceType.trim() : 'no resources';
    default:
      return String(form[id] ?? '').trim();
  }
}

const OTHER = '__other';

function choice(form, key) {
  return form[key] === OTHER ? form[`${key}Other`].trim() : form[key];
}

function distinctValues(datasets, get) {
  return [...new Set(datasets.map(get).filter(Boolean))].sort();
}

function formatNumber(n) {
  return n === null || n === undefined ? '—' : n.toLocaleString();
}

function count(n, singular, plural = `${singular}s`) {
  return `${formatNumber(n)} ${n === 1 ? singular : plural}`;
}

function baseName(fileName) {
  return fileName.replace(/\.(xes|csv)(\.gz)?$/i, '');
}

function extractDoi(source) {
  const match = /(10\.\d{4,9}\/[^\s"'<>]+)/.exec(source || '');
  return match ? match[1].replace(/[.)]+$/, '') : null;
}

function findDuplicates(datasets, basicInfo) {
  const same = (d) =>
    d.basic_info?.number_of_cases === basicInfo.number_of_cases &&
    d.basic_info?.number_of_events === basicInfo.number_of_events &&
    d.basic_info?.number_of_activities === basicInfo.number_of_activities;
  const matches = datasets.filter(same);
  return {
    named: matches.filter((d) => !isHidden(d)).map((d) => d.basic_info.event_log_name),
    hidden: matches.filter(isHidden).length,
  };
}

function buildRecord(form, analysis, featureSet) {
  const { stats, features, warnings } = analysis;
  const source = form.publicRecord ? form.source.trim() : '';
  const website = form.publicRecord ? '' : form.website.trim();
  const hasFeatures = Object.values(features).some((v) => v !== null && v !== undefined);
  return {
    _userAdded: true,
    _userKey: `user-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    _addedAt: new Date().toISOString(),
    _warnings: warnings,
    _featureSet: featureSet,
    event_log_id: null,
    basic_info: {
      event_log_name: form.name.trim(),
      ...stats.basic_info,
      event_log_year: number(form.eventLogYear),
      notes:
        [text(form.notes), form.publicRecord ? null : `Not publicly available${website ? `. Associated website: ${website}` : ''}.`]
          .filter(Boolean)
          .join(' ') || null,
    },
    domain_context: {
      domain_application: choice(form, 'domainApplication') || null,
      event_log_type: form.eventLogType || null,
      process_type: form.processType || null,
      process_information: form.processInformation.trim() || null,
    },
    academic_context: {
      doi: extractDoi(source),
      year: Number(form.year) || null,
      publication_type: choice(form, 'publicationType') || null,
      reference: form.reference.trim() || null,
    },
    data_characteristics: {
      ...stats.data_characteristics,
      activity_label: form.activityLabel !== 'no',
      potential_performance_issues: text(form.performanceIssues),
      performance_issues_notes: text(form.performanceNotes),
      prominent_exhibited_behavior: choice(form, 'prominentBehavior') || null,
      primary_dependency: text(form.primaryDependency),
      pct_primary_dependency_case_coverage: number(form.primaryDependencyCoverage),
    },
    resource_context: { ...stats.resource_context, resource_type: form.resourceType.trim() || null },
    path_observation: {
      consistency: form.consistency || null,
      observed_path: number(form.observedPath),
      notes_for_path_reduction: text(form.pathNotes),
    },
    collection: null,
    source_url: source || null,
    feeed_available: hasFeatures,
    feeed_log_key: null,
    feeed_features: hasFeatures ? features : null,
  };
}

const CARRIED_FIELDS = ['domainApplication', 'domainApplicationOther', 'eventLogType', 'publicationType', 'publicationTypeOther', 'year'];

function FieldInfo({ id, title }) {
  const info = FIELD_INFO[id];
  if (!info) return null;
  return (
    <InfoTip label={`About ${title}`}>
      {info.costa && (
        <span>
          <q>{info.costa}</q> <span className="info-tip__source">{COSTA_SOURCE}</span>
        </span>
      )}
      {info.note && <span>{info.note}</span>}
    </InfoTip>
  );
}

function FieldLabel({ id, title, star = '', htmlFor }) {
  return (
    <label className="filters-panel__label add-log__label" htmlFor={htmlFor}>
      {title}
      {star}
      <FieldInfo id={id} title={title} />
    </label>
  );
}

function ChipSelect({ label, info, options, selected, onToggle, colorOf, other }) {
  const allOptions = other ? [...options, { id: OTHER, label: 'Other' }] : options;
  return (
    <div className="add-log__field">
      <label className="filters-panel__label add-log__label">
        {label}
        {info && <FieldInfo id={info.id} title={info.title} />}
      </label>
      <div className="filters-panel__chips">
        {allOptions.map((opt) => {
          const id = typeof opt === 'string' ? opt : opt.id;
          const text = typeof opt === 'string' ? opt : opt.label;
          const active = selected === id;
          const color = colorOf?.(id);
          return (
            <button
              key={id}
              type="button"
              className={`filter-chip ${active ? 'filter-chip--active' : ''}`}
              style={active && color ? { borderColor: color, background: `color-mix(in srgb, ${color} 15%, transparent)`, color } : undefined}
              onClick={() => onToggle(active ? '' : id)}
              aria-pressed={active}
            >
              {text}
            </button>
          );
        })}
      </div>
      {other && selected === OTHER && (
        <input
          className="toolbar__search add-log__other"
          placeholder={other.placeholder}
          value={other.value}
          onChange={(e) => other.onChange(e.target.value)}
          autoFocus
        />
      )}
    </div>
  );
}

export default function AddEventLogModal({ config, datasets, onClose, onAdded }) {
  const [step, setStep] = useState('file');
  const [status, setStatus] = useState(null);
  const [error, setError] = useState(null);
  const [dragging, setDragging] = useState(false);
  const [items, setItems] = useState([]);
  const [current, setCurrent] = useState(0);
  const [submitting, setSubmitting] = useState(false);
  const [lookup, setLookup] = useState({ state: 'idle', message: null });
  const [largeFile, setLargeFile] = useState(null);
  const [addedList, setAddedList] = useState([]);
  const [skipped, setSkipped] = useState([]);
  const [csvPrompt, setCsvPrompt] = useState(null);
  const lastMappingRef = useRef(null);
  const inputRef = useRef(null);
  const totalRef = useRef(0);
  const collectedRef = useRef([]);

  const item = items[current] || null;
  const analysis = item?.analysis || null;
  const form = item?.form || EMPTY_FORM;
  const prefilled = Boolean(item?.prefilled);
  const setForm = (next) =>
    setItems((list) => list.map((it, i) => (i === current ? { ...it, form: typeof next === 'function' ? next(it.form) : next } : it)));
  const setField = (key, value) => setForm((f) => ({ ...f, [key]: value }));
  const featureSet = normalizeFeatureSet(config.featureSet);
  const required = new Set(config.contribute?.requiredFields || DEFAULT_REQUIRED);
  const star = (id) => (required.has(id) ? ' *' : '');
  const sizeLimits = { ...DEFAULT_FILE_SIZE_MB, ...config.contribute?.fileSizeMB };
  const warnBytes = sizeLimits.warn * MB;
  const maxBytes = sizeLimits.max * MB;

  const handleLookup = async () => {
    setLookup({ state: 'loading', message: null });
    try {
      const found = await lookupDoi(form.source);
      const filled = [];
      const f = form;
      const next = { ...f, source: `https://doi.org/${found.doi}` };
      const fill = (key, value, label, replace = false) => {
        if (!value) return;
        if (replace || !String(f[key] || '').trim()) {
          next[key] = String(value);
          filled.push(label);
        }
      };
      fill('name', found.name, 'name');
      fill('year', found.year, 'year');
      fill('reference', found.reference, 'reference');
      fill('processInformation', found.description, 'description');
      if (found.publicationType && !f.publicationType) {
        next.publicationType = found.publicationType;
        filled.push('publication type');
      }
      setForm(next);
      setLookup({
        state: 'done',
        message: `Found in ${found.registry}${filled.length ? `; filled in ${filled.join(', ')}` : ''}.${found.license ? ` License: ${found.license}.` : ''} Please check the values.`,
      });
    } catch (e) {
      setLookup({ state: 'error', message: e.message });
    }
  };

  const options = useMemo(
    () => ({
      eventLogTypes: distinctValues(datasets, (d) => d.domain_context?.event_log_type),
      processTypes: distinctValues(datasets, (d) => d.domain_context?.process_type),
      publicationTypes: [...new Set([...distinctValues(datasets, (d) => d.academic_context?.publication_type), NOT_PUBLISHED])],
      behaviors: distinctValues(datasets, (d) => d.data_characteristics?.prominent_exhibited_behavior),
      consistencies: distinctValues(datasets, (d) => d.path_observation?.consistency),
    }),
    [datasets]
  );

  const inBatch = () => totalRef.current > 1;
  const batchLabel = (rest) => (inBatch() ? ` (${totalRef.current - rest.length} of ${totalRef.current})` : '');
  const skip = (name, reason) => setSkipped((s) => [...s, { name, reason }]);

  const finishReading = () => {
    const list = collectedRef.current;
    if (!list.length) {
      setStep('file');
      return;
    }
    setItems(list.map((a, i) => ({ analysis: a, form: i === 0 ? newForm(a) : null, prefilled: false })));
    setCurrent(0);
    setLookup({ state: 'idle', message: null });
    setStep('review');
  };

  const advance = (rest) => {
    if (rest.length) handleFile(rest[0], { rest: rest.slice(1) });
    else finishReading();
  };

  const startFiles = (list) => {
    const files = [...(list || [])];
    if (!files.length) return;
    const accepted = files.filter(isAcceptedFile);
    totalRef.current = accepted.length;
    collectedRef.current = [];
    setItems([]);
    setAddedList([]);
    setSkipped(files.filter((f) => !isAcceptedFile(f)).map((f) => ({ name: f.name, reason: 'not an XES or CSV file' })));
    setLargeFile(null);
    setCsvPrompt(null);
    if (!accepted.length) {
      setError(
        files.length > 1
          ? 'Please choose XES or CSV files (.xes, .xes.gz, .csv or .csv.gz).'
          : 'Please choose an XES or CSV file (.xes, .xes.gz, .csv or .csv.gz).'
      );
      return;
    }
    handleFile(accepted[0], { rest: accepted.slice(1) });
  };

  const fail = (file, rest, e) => {
    const reason = e?.message || (e ? String(e) : '');
    if (inBatch()) {
      skip(file.name, reason || 'could not be processed');
      advance(rest);
    } else {
      setError(`This file could not be processed${reason ? `: ${reason}` : '.'}`);
    }
  };

  const analyzeTraces = async (file, traces, rest, extra = {}) => {
    try {
      if (traces.every((t) => t.events.length === 0)) throw new Error('This event log has no events.');
      const stats = computeLogStats(traces, file);
      setStatus(`Computing features for ${traces.length.toLocaleString()} traces${batchLabel(rest)}…`);
      const result = await analyzeInWorker(traces, featureSet);
      const features = Object.fromEntries(
        Object.entries(result.features).map(([k, v]) => [k, Number.isFinite(v) ? v : null])
      );
      const caseOrder =
        extra.columns && Object.keys(features).some((k) => k.startsWith('eventropy_lempel_ziv'))
          ? [
              'In a CSV file the cases are ordered by their first timestamp. The two Lempel-Ziv entropy features depend on the order of the cases, so they can differ from the same log as an XES file whose cases are not in time order.',
            ]
          : [];
      const warnings = [...(extra.warnings || []), ...caseOrder, ...result.warnings];
      const duplicates = findDuplicates(datasets, stats.basic_info);
      collectedRef.current = [
        ...collectedRef.current,
        { fileName: file.name, stats, features, warnings, duplicates, columns: extra.columns || null },
      ];
      advance(rest);
    } catch (e) {
      fail(file, rest, e);
    } finally {
      setStatus(null);
    }
  };

  const handleFile = async (file, { confirmed = false, rest = [] } = {}) => {
    setStep('file');
    setError(null);
    setLargeFile(null);
    setCsvPrompt(null);
    try {
      const size = await estimatedSize(file);
      if (size > maxBytes) {
        if (inBatch()) {
          skip(file.name, `about ${formatMB(size)} unpacked, more than the ${formatMB(maxBytes)} this page can process`);
          advance(rest);
        } else {
          setError(`This event log is about ${formatMB(size)} unpacked. This page can process at most ${formatMB(maxBytes)} in your browser.`);
        }
        return;
      }
      if (size > warnBytes && !confirmed) {
        setLargeFile({ file, size, rest });
        return;
      }
      setStatus(`Reading ${file.name}${batchLabel(rest)}…`);
      const text = await readXesFile(file, maxBytes);
      if (isCsvFile(file)) {
        setStatus(`Reading the columns of ${file.name}${batchLabel(rest)}…`);
        await new Promise((resolve) => setTimeout(resolve, 0));
        const parsed = parseCsvText(text);
        const last = lastMappingRef.current;
        const fits =
          last &&
          [last.caseId, last.activity, last.timestamp].every((c) => parsed.header.includes(c)) &&
          (!last.resource || parsed.header.includes(last.resource));
        setCsvPrompt({ file, parsed, rest, mapping: fits ? last : guessMapping(parsed.header), dateOrder: 'dmy', error: null });
        setStatus(null);
        return;
      }
      setStatus(`Parsing the event log${batchLabel(rest)}…`);
      await new Promise((resolve) => setTimeout(resolve, 0));
      const { traces } = parseXesText(text);
      await analyzeTraces(file, traces, rest);
    } catch (e) {
      fail(file, rest, e);
    } finally {
      setStatus(null);
    }
  };

  const csvDetected = useMemo(() => {
    if (!csvPrompt?.mapping.timestamp) return null;
    const idx = csvPrompt.parsed.header.indexOf(csvPrompt.mapping.timestamp);
    return detectDateOrder(csvPrompt.parsed.rows.slice(0, 2000).map((r) => r[idx]));
  }, [csvPrompt]);

  const csvDateOrder =
    csvDetected === 'mdy' || (csvDetected === 'ambiguous' && csvPrompt?.dateOrder === 'mdy') ? 'mdy' : 'dmy';

  const csvExample = useMemo(() => {
    if (!csvPrompt?.mapping.timestamp) return null;
    const idx = csvPrompt.parsed.header.indexOf(csvPrompt.mapping.timestamp);
    const raw = csvPrompt.parsed.rows.find((r) => String(r[idx] ?? '').trim())?.[idx];
    if (raw === undefined) return null;
    const micros = parseCsvTimestamp(raw, csvDateOrder);
    return { raw: String(raw).trim(), read: micros === null ? null : new Date(micros / 1000).toISOString().replace('T', ' ').replace(/\.000Z$|Z$/, '') };
  }, [csvPrompt, csvDateOrder]);

  const setCsvRole = (role, column) => setCsvPrompt((p) => ({ ...p, mapping: { ...p.mapping, [role]: column }, error: null }));

  const skipCsv = () => {
    const { file, rest } = csvPrompt;
    setCsvPrompt(null);
    if (inBatch()) {
      skip(file.name, 'skipped');
      advance(rest);
    }
  };

  const confirmCsv = async () => {
    const { file, parsed, rest, mapping } = csvPrompt;
    const missing = CSV_ROLES.filter((r) => r.required && !mapping[r.role]).map((r) => r.label.toLowerCase());
    if (missing.length) {
      setCsvPrompt((p) => ({ ...p, error: `Please choose the column for the ${missing.join(', the ')}.` }));
      return;
    }
    const chosen = CSV_ROLES.map((r) => mapping[r.role]).filter(Boolean);
    if (new Set(chosen).size !== chosen.length) {
      setCsvPrompt((p) => ({ ...p, error: 'Please choose a different column for each role.' }));
      return;
    }
    const dateOrder = csvDateOrder;
    let converted;
    try {
      converted = csvToTraces(parsed, mapping, { dateOrder });
    } catch (e) {
      setCsvPrompt((p) => ({ ...p, error: e.message }));
      return;
    }
    lastMappingRef.current = mapping;
    setCsvPrompt(null);
    setStatus(`Reading the cases of ${file.name}${batchLabel(rest)}…`);
    await new Promise((resolve) => setTimeout(resolve, 0));
    await analyzeTraces(file, converted.traces, rest, { warnings: converted.warnings, columns: mapping });
  };

  const goTo = (index) => {
    setError(null);
    setLookup({ state: 'idle', message: null });
    setItems((list) => {
      if (list[index].form) return list;
      const previous = list.slice(0, index).reverse().find((it) => it.form)?.form;
      const carried = previous ? Object.fromEntries(CARRIED_FIELDS.map((key) => [key, previous[key]])) : {};
      return list.map((it, i) =>
        i === index
          ? { ...it, form: newForm(it.analysis, carried), prefilled: Boolean(previous) }
          : it
      );
    });
    setCurrent(index);
  };

  const missingOf = (it) =>
    [...required].filter((id) => FIELD_LABELS[id] && !fieldValue(it.form, it.analysis, id)).map((id) => FIELD_LABELS[id]);

  const itemState = (it) => {
    if (!it.form) return 'new';
    return missingOf(it).length ? 'incomplete' : 'ready';
  };

  const handleSubmit = async () => {
    const order = [current, ...items.keys()];
    const unchecked = order.find((i) => !items[i].form);
    if (unchecked !== undefined) {
      goTo(unchecked);
      setError(`Please check this event log before adding: ${items[unchecked].analysis.fileName}.`);
      return;
    }
    const incomplete = order.find((i) => missingOf(items[i]).length);
    if (incomplete !== undefined) {
      goTo(incomplete);
      setError(`Please fill in the required fields: ${missingOf(items[incomplete]).join(', ')}.`);
      return;
    }
    setError(null);
    setSubmitting(true);
    try {
      const added = [];
      for (const it of items) {
        const { dataset, stored } = await addUserDataset(buildRecord(it.form, it.analysis, featureSet));
        added.push({ dataset, stored });
        onAdded(dataset);
      }
      setAddedList(added);
      setStep('success');
    } finally {
      setSubmitting(false);
    }
  };

  const addedDatasets = addedList.map((a) => a.dataset).filter(Boolean);
  const addedKeys = new Set(addedDatasets.map((d) => d._userKey));
  const skippedNote = skipped.length > 0 && (
    <p className="add-log__warning">
      Not added: {skipped.map((s) => `${s.name} (${s.reason})`).join('; ')}.
    </p>
  );

  const basic = analysis?.stats.basic_info;
  const nFeatures = analysis ? Object.values(analysis.features).filter((v) => v !== null && v !== undefined).length : 0;
  const totalFeatures = analysis ? Object.keys(analysis.features).length : 0;

  return (
    <>
      <div className="modal__backdrop" onClick={onClose} />
      <div className="modal" role="dialog" aria-labelledby="add-log-title">
        <div className="modal__header">
          <h2 id="add-log-title">Add an Event Log</h2>
          <button className="modal__close" onClick={onClose} aria-label="Close">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M18 6L6 18M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="modal__body">
          {step === 'file' && (
            <>
              <p className="add-log__hint">
                Choose one or more event logs as XES or CSV files. Their statistics and FEEED features are computed here, in
                your browser. The files themselves are never uploaded. Added event logs live only in your browser and show up in the list, the
                landscape and the feature space, marked as yours.
              </p>
              {!csvPrompt && (
              <div
                className={`add-log__dropzone ${dragging ? 'add-log__dropzone--active' : ''}`}
                onClick={() => !status && inputRef.current?.click()}
                onKeyDown={(e) => {
                  if (!status && (e.key === 'Enter' || e.key === ' ')) {
                    e.preventDefault();
                    inputRef.current?.click();
                  }
                }}
                onDragOver={(e) => {
                  e.preventDefault();
                  setDragging(true);
                }}
                onDragLeave={() => setDragging(false)}
                onDrop={(e) => {
                  e.preventDefault();
                  setDragging(false);
                  if (!status) startFiles(e.dataTransfer.files);
                }}
                role="button"
                tabIndex={0}
              >
                {status ? (
                  <>
                    <div className="loading__spinner" />
                    <span>{status}</span>
                  </>
                ) : (
                  <>
                    <strong>Drop XES or CSV files here</strong>
                    <span>or click to choose one or more (.xes, .xes.gz, .csv or .csv.gz)</span>
                  </>
                )}
              </div>
              )}
              <input
                ref={inputRef}
                type="file"
                accept=".xes,.csv,.gz"
                multiple
                hidden
                onChange={(e) => {
                  startFiles(e.target.files);
                  e.target.value = '';
                }}
              />
              {error && <p className="add-log__error">{error}</p>}
              {!status && skippedNote}
              {csvPrompt && !status && (
                <div className="csv-map">
                  <p className="add-log__hint">
                    <strong>{csvPrompt.file.name}</strong>
                    {inBatch() ? batchLabel(csvPrompt.rest) : ''} is a CSV file with {csvPrompt.parsed.header.length} columns
                    and {csvPrompt.parsed.rows.length.toLocaleString()} rows. Choose the columns that hold the case ID, the
                    activity and the timestamp. The resource is optional. All other columns are kept as additional attributes.
                  </p>
                  <div className="add-log__grid csv-map__roles">
                    {CSV_ROLES.map(({ role, label, required: req }) => (
                      <div className="add-log__field" key={role}>
                        <label className="filters-panel__label" htmlFor={`csv-${role}`}>
                          {label}
                          {req ? ' *' : ''}
                        </label>
                        <select
                          id={`csv-${role}`}
                          className="concept-select__input csv-map__select"
                          value={csvPrompt.mapping[role]}
                          onChange={(e) => setCsvRole(role, e.target.value)}
                        >
                          <option value="">{req ? 'Choose a column' : 'None'}</option>
                          {csvPrompt.parsed.header.map((h) => (
                            <option key={h} value={h}>
                              {h}
                            </option>
                          ))}
                        </select>
                      </div>
                    ))}
                  </div>
                  {csvExample && (
                    <p className={csvExample.read ? 'add-log__hint' : 'add-log__error'}>
                      {csvExample.read
                        ? `The first timestamp, "${csvExample.raw}", is read as ${csvExample.read} UTC. Timestamps without a time zone are read as UTC.`
                        : `The first timestamp, "${csvExample.raw}", cannot be read. Please check the timestamp column.`}
                    </p>
                  )}
                  {csvDetected === 'ambiguous' && (
                    <div className="add-log__field">
                      <label className="filters-panel__label" htmlFor="csv-date-order">
                        Date order
                      </label>
                      <select
                        id="csv-date-order"
                        className="concept-select__input csv-map__select"
                        value={csvPrompt.dateOrder}
                        onChange={(e) => setCsvPrompt((p) => ({ ...p, dateOrder: e.target.value, error: null }))}
                      >
                        <option value="dmy">Day first (31.12.2024 or 31/12/2024)</option>
                        <option value="mdy">Month first (12/31/2024)</option>
                      </select>
                      <p className="add-log__hint">The dates in this column could be read either way.</p>
                    </div>
                  )}
                  <div className="csv-map__table">
                    <table>
                      <thead>
                        <tr>
                          {csvPrompt.parsed.header.map((h) => {
                            const role = CSV_ROLES.find((r) => csvPrompt.mapping[r.role] === h);
                            return (
                              <th key={h} className={role ? 'csv-map__col--used' : ''}>
                                {h}
                                {role && <span className="csv-map__role">{role.label}</span>}
                              </th>
                            );
                          })}
                        </tr>
                      </thead>
                      <tbody>
                        {csvPrompt.parsed.rows.slice(0, 5).map((row, i) => (
                          <tr key={i}>
                            {csvPrompt.parsed.header.map((h, j) => (
                              <td key={h}>{row[j]}</td>
                            ))}
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                  {csvPrompt.error && <p className="add-log__error">{csvPrompt.error}</p>}
                  <div className="modal__actions">
                    <button className="btn btn--ghost" onClick={skipCsv}>
                      {inBatch() ? 'Skip this file' : 'Choose another file'}
                    </button>
                    <button className="btn btn--primary" onClick={confirmCsv}>
                      Continue
                    </button>
                  </div>
                </div>
              )}
              {largeFile && !status && (
                <>
                  <p className="add-log__warning">
                    {largeFile.file.name} is about {formatMB(largeFile.size)} unpacked. Processing it in your browser can take
                    several minutes and needs a lot of memory; on a phone or an older computer the tab may crash.
                  </p>
                  <div className="modal__actions">
                    {inBatch() ? (
                      <button
                        className="btn btn--ghost"
                        onClick={() => {
                          skip(largeFile.file.name, 'skipped');
                          advance(largeFile.rest);
                        }}
                      >
                        Skip this file
                      </button>
                    ) : (
                      <button className="btn btn--ghost" onClick={() => setLargeFile(null)}>Choose another file</button>
                    )}
                    <button
                      className="btn btn--primary"
                      onClick={() => handleFile(largeFile.file, { confirmed: true, rest: largeFile.rest })}
                    >
                      Continue anyway
                    </button>
                  </div>
                </>
              )}
            </>
          )}

          {step === 'review' && analysis && (
            <>
              {items.length > 1 && (
                <>
                  <p className="add-log__batch">
                    Event log {current + 1} of {items.length}
                  </p>
                  <div className="add-log__steps" role="tablist">
                    {items.map((it, i) => (
                      <button
                        key={it.analysis.fileName + i}
                        type="button"
                        role="tab"
                        aria-selected={i === current}
                        className={`add-log__step add-log__step--${itemState(it)}${i === current ? ' add-log__step--current' : ''}`}
                        title={`${it.form?.name || baseName(it.analysis.fileName)}: ${{ new: 'not checked yet', incomplete: 'required fields missing', ready: 'ready' }[itemState(it)]}`}
                        onClick={() => goTo(i)}
                      >
                        {i + 1}. {it.form?.name || baseName(it.analysis.fileName)}
                      </button>
                    ))}
                  </div>
                </>
              )}
              <p className="add-log__hint">Computed from {analysis.fileName}. Check the values and describe the event log.</p>
              {prefilled && (
                <p className="add-log__hint">
                  The domain application, event log type, publication type and year were filled in from the previous event
                  log when you opened this one. Please check them.
                </p>
              )}

              <div className="add-log__summary">
                <span>{count(basic.number_of_cases, 'case')}</span>
                <span>{count(basic.number_of_events, 'event')}</span>
                <span>{count(basic.number_of_activities, 'activity', 'activities')}</span>
                <span>{count(basic.number_of_variants, 'variant')}</span>
                <span>
                  {nFeatures} of {totalFeatures} FEEED features
                </span>
              </div>
              <p className="add-log__hint">
                {featureSet === 'all'
                  ? `All ${totalFeatures} FEEED 2.2.0 features are computed and kept with the entry.`
                  : `The ${totalFeatures} FEEED 2.2.0 features of the default feature set are computed and kept with the entry.`}{' '}
                They place it in the feature space.
              </p>

              {analysis.warnings.map((w) => (
                <p key={w} className="add-log__warning">{w}</p>
              ))}
              {nFeatures < totalFeatures && (
                <p className="add-log__warning">
                  {totalFeatures - nFeatures} features are undefined for this log (for example the skewness of start activities when every trace starts with the same activity) and stay empty.
                </p>
              )}
              {(analysis.duplicates.named.length > 0 || analysis.duplicates.hidden > 0) && (
                <p className="add-log__warning">
                  Possibly already in the collection:{' '}
                  {[
                    ...analysis.duplicates.named,
                    ...(analysis.duplicates.hidden ? [`${analysis.duplicates.hidden} hidden log${analysis.duplicates.hidden > 1 ? 's' : ''}`] : []),
                  ].join(', ')}{' '}
                  {analysis.duplicates.named.length + analysis.duplicates.hidden > 1 ? 'have' : 'has'} the same numbers of cases, events and activities.
                </p>
              )}

              {error && <p className="add-log__error">{error}</p>}

              <div className="add-log__field">
                <label className="add-log__check add-log__check--first">
                  <input type="checkbox" checked={form.publicRecord} onChange={(e) => setField('publicRecord', e.target.checked)} />
                  <span>There is a public record of this event log, e.g. a DOI or a download page</span>
                  <FieldInfo id="publicRecord" title="public records" />
                </label>
                {form.publicRecord ? (
                  <>
                    <FieldLabel id="source" title="Source (DOI or URL)" star={star('source')} htmlFor="add-log-source" />
                    <div className="add-log__source">
                      <input
                        id="add-log-source"
                        className="toolbar__search"
                        placeholder="10.5281/zenodo.… or https://zenodo.org/records/…"
                        value={form.source}
                        onChange={(e) => setField('source', e.target.value)}
                        onKeyDown={(e) => {
                          if (e.key === 'Enter' && form.source.trim()) handleLookup();
                        }}
                      />
                      <button
                        type="button"
                        className="btn btn--secondary"
                        onClick={handleLookup}
                        disabled={!form.source.trim() || lookup.state === 'loading'}
                      >
                        {lookup.state === 'loading' ? 'Looking up…' : 'Look up'}
                      </button>
                    </div>
                    {lookup.message && (
                      <p className={lookup.state === 'error' ? 'add-log__error' : 'add-log__hint add-log__lookup'}>{lookup.message}</p>
                    )}
                  </>
                ) : (
                  <>
                    <FieldLabel id="website" title="Associated website" htmlFor="add-log-website" />
                    <input
                      id="add-log-website"
                      className="toolbar__search add-log__wide"
                      type="url"
                      placeholder="e.g. the project, company or paper page (optional)"
                      value={form.website}
                      onChange={(e) => setField('website', e.target.value)}
                    />
                  </>
                )}
              </div>

              <div className="add-log__grid">
                <div className="add-log__field">
                  <FieldLabel id="name" title="Name" star={star('name')} htmlFor="add-log-name" />
                  <input id="add-log-name" className="toolbar__search" value={form.name} onChange={(e) => setField('name', e.target.value)} />
                </div>
                <div className="add-log__field">
                  <FieldLabel id="year" title="Year" star={star('year')} htmlFor="add-log-year" />
                  <input id="add-log-year" className="toolbar__search" type="number" value={form.year} onChange={(e) => setField('year', e.target.value)} />
                </div>
              </div>
              <div className="add-log__field">
                <FieldLabel id="reference" title="Reference (citation)" star={star('reference')} htmlFor="add-log-reference" />
                <textarea
                  id="add-log-reference"
                  className="add-log__textarea"
                  rows={2}
                  value={form.reference}
                  onChange={(e) => setField('reference', e.target.value)}
                />
              </div>
              <div className="add-log__field">
                <FieldLabel id="description" title="Process description" star={star('description')} htmlFor="add-log-description" />
                <textarea
                  id="add-log-description"
                  className="add-log__textarea"
                  rows={2}
                  value={form.processInformation}
                  onChange={(e) => setField('processInformation', e.target.value)}
                />
              </div>

              <ChipSelect
                label={`Domain Application${star('domainApplication')}`}
                info={{ id: 'domainApplication', title: 'Domain Application' }}
                options={config.domainApplications || []}
                selected={form.domainApplication}
                onToggle={(id) => setField('domainApplication', id)}
                colorOf={(id) => config.domainApplications?.find((d) => d.id === id)?.color}
                other={{
                  value: form.domainApplicationOther,
                  onChange: (v) => setField('domainApplicationOther', v),
                  placeholder: 'Name the domain application',
                }}
              />
              <ChipSelect
                label={`Event Log Type${star('eventLogType')}`}
                info={{ id: 'eventLogType', title: 'Event Log Type' }}
                options={options.eventLogTypes}
                selected={form.eventLogType}
                onToggle={(id) => setField('eventLogType', id)}
              />
              <ChipSelect
                label={`Process Type${star('processType')}`}
                info={{ id: 'processType', title: 'Process Type' }}
                options={options.processTypes}
                selected={form.processType}
                onToggle={(id) => setField('processType', id)}
              />
              <ChipSelect
                label={`Publication Type${star('publicationType')}`}
                info={{ id: 'publicationType', title: 'Publication Type' }}
                options={options.publicationTypes}
                selected={form.publicationType}
                onToggle={(id) => setField('publicationType', id)}
                other={{
                  value: form.publicationTypeOther,
                  onChange: (v) => setField('publicationTypeOther', v),
                  placeholder: 'Name the publication type, e.g. Dataset or Thesis',
                }}
              />

              {basic.resource_availability ? (
                <div className="add-log__field">
                  <FieldLabel id="resourceType" title="Resource type" star={star('resourceType')} htmlFor="add-log-resource-type" />
                  <input
                    id="add-log-resource-type"
                    className="toolbar__search"
                    placeholder="What the resources are, e.g. employee, department or machine"
                    value={form.resourceType}
                    onChange={(e) => setField('resourceType', e.target.value)}
                  />
                  <p className="add-log__hint">
                    {count(analysis.stats.resource_context.number_of_resources, 'resource')} found in the file
                    {analysis.stats.resource_context.type_indication ? `, e.g. ${analysis.stats.resource_context.type_indication}` : ''}.
                  </p>
                </div>
              ) : (
                <p className="add-log__hint">No resources (org:resource) in the file.</p>
              )}

              <div className="add-log__field">
                <FieldLabel id="notes" title="Notes (optional)" htmlFor="add-log-notes" />
                <textarea
                  id="add-log-notes"
                  className="add-log__textarea"
                  rows={2}
                  placeholder="Anything else worth knowing, e.g. how the log was recorded or cleaned"
                  value={form.notes}
                  onChange={(e) => setField('notes', e.target.value)}
                />
              </div>

              <details className="add-log__more">
                <summary>More details (optional)</summary>
                <p className="add-log__hint">
                  Further attributes of the metadata structure by Costa et al. (2025). They need a closer look at the process,
                  e.g. in a process mining tool. Fill in what you know.
                </p>
                <div className="add-log__grid">
                  <div className="add-log__field">
                    <FieldLabel id="eventLogYear" title="Event log year" htmlFor="add-log-event-log-year" />
                    <input
                      id="add-log-event-log-year"
                      className="toolbar__search"
                      type="number"
                      value={form.eventLogYear}
                      onChange={(e) => setField('eventLogYear', e.target.value)}
                    />
                    {suggestedEventLogYear(analysis) && (
                      <p className="add-log__hint add-log__lookup">
                        Suggested from the last timestamp in the file ({analysis.stats.basic_info.end_date}).
                      </p>
                    )}
                  </div>
                  <ChipSelect
                    label="Descriptive activity labels"
                    info={{ id: 'activityLabel', title: 'Activity Label' }}
                    options={[
                      { id: 'yes', label: 'Yes' },
                      { id: 'no', label: 'No' },
                    ]}
                    selected={form.activityLabel}
                    onToggle={(id) => setField('activityLabel', id || 'yes')}
                  />
                </div>
                <div className="add-log__field">
                  <FieldLabel id="performanceIssues" title="Potential performance issues" htmlFor="add-log-performance" />
                  <input
                    id="add-log-performance"
                    className="toolbar__search add-log__wide"
                    placeholder="Activities that may cause delays, e.g. Status Change, Closed"
                    value={form.performanceIssues}
                    onChange={(e) => setField('performanceIssues', e.target.value)}
                  />
                </div>
                <div className="add-log__field">
                  <FieldLabel id="performanceNotes" title="Performance issues notes" htmlFor="add-log-performance-notes" />
                  <textarea
                    id="add-log-performance-notes"
                    className="add-log__textarea"
                    rows={2}
                    value={form.performanceNotes}
                    onChange={(e) => setField('performanceNotes', e.target.value)}
                  />
                </div>
                <ChipSelect
                  label="Prominent exhibited behavior"
                  info={{ id: 'prominentBehavior', title: 'Prominent Exhibited Behavior' }}
                  options={options.behaviors}
                  selected={form.prominentBehavior}
                  onToggle={(id) => setField('prominentBehavior', id)}
                  other={{
                    value: form.prominentBehaviorOther,
                    onChange: (v) => setField('prominentBehaviorOther', v),
                    placeholder: 'Describe the behavior',
                  }}
                />
                <div className="add-log__grid">
                  <div className="add-log__field">
                    <FieldLabel id="primaryDependency" title="Primary dependency" htmlFor="add-log-dependency" />
                    <input
                      id="add-log-dependency"
                      className="toolbar__search"
                      placeholder="e.g. Closed, Caused By CI"
                      value={form.primaryDependency}
                      onChange={(e) => setField('primaryDependency', e.target.value)}
                    />
                  </div>
                  <div className="add-log__field">
                    <FieldLabel id="primaryDependencyCoverage" title="% of cases with it" htmlFor="add-log-dependency-coverage" />
                    <input
                      id="add-log-dependency-coverage"
                      className="toolbar__search"
                      type="number"
                      min="0"
                      max="100"
                      step="0.1"
                      value={form.primaryDependencyCoverage}
                      onChange={(e) => setField('primaryDependencyCoverage', e.target.value)}
                    />
                  </div>
                </div>
                <ChipSelect
                  label="Path consistency"
                  info={{ id: 'consistency', title: 'Path Observation' }}
                  options={options.consistencies}
                  selected={form.consistency}
                  onToggle={(id) => setField('consistency', id)}
                />
                <div className="add-log__grid">
                  <div className="add-log__field">
                    <FieldLabel id="observedPath" title="Observed path (0–1)" htmlFor="add-log-observed-path" />
                    <input
                      id="add-log-observed-path"
                      className="toolbar__search"
                      type="number"
                      min="0"
                      max="1"
                      step="0.05"
                      value={form.observedPath}
                      onChange={(e) => setField('observedPath', e.target.value)}
                    />
                  </div>
                </div>
                <div className="add-log__field">
                  <FieldLabel id="pathNotes" title="Notes for the path reduction" htmlFor="add-log-path-notes" />
                  <textarea
                    id="add-log-path-notes"
                    className="add-log__textarea"
                    rows={2}
                    value={form.pathNotes}
                    onChange={(e) => setField('pathNotes', e.target.value)}
                  />
                </div>
              </details>

              <div className="modal__actions">
                {current === 0 ? (
                  <button className="btn btn--ghost" onClick={() => setStep('file')} disabled={submitting}>
                    ← Back
                  </button>
                ) : (
                  <button className="btn btn--ghost" onClick={() => goTo(current - 1)} disabled={submitting}>
                    ← Previous
                  </button>
                )}
                {current < items.length - 1 && (
                  <button className="btn btn--secondary" onClick={() => goTo(current + 1)} disabled={submitting}>
                    Next →
                  </button>
                )}
                <button className="btn btn--primary" onClick={handleSubmit} disabled={submitting}>
                  {submitting
                    ? 'Adding…'
                    : items.length === 1
                      ? 'Add Event Log'
                      : `Add ${items.length} event logs`}
                </button>
              </div>
            </>
          )}

          {step === 'success' && addedDatasets.length > 0 && (
            <>
              {addedDatasets.length === 1 ? (
                <p className="add-log__hint">
                  Added to your browser. You'll find it pinned at the top of the event log list, and marked with a dashed
                  ring in the landscape and the feature space.
                </p>
              ) : (
                <p className="add-log__hint">
                  Added {addedDatasets.length} event logs to your browser. You'll find them pinned at the top of the event
                  log list, and marked with a dashed ring in the landscape and the feature space.
                </p>
              )}
              {skippedNote}
              {addedList.some((a) => !a.stored) && (
                <p className="add-log__warning">
                  Your browser does not allow storing {addedDatasets.length === 1 ? 'it' : 'them'}, so{' '}
                  {addedDatasets.length === 1 ? 'it' : 'they'} will disappear when you reload the page. Download{' '}
                  {addedDatasets.length === 1 ? 'the entry' : 'the entries'} to keep {addedDatasets.length === 1 ? 'it' : 'them'}.
                </p>
              )}
              <div className="add-log__send">
                <SendEntriesPanel
                  intro={
                    <p className="add-log__hint">
                      {addedDatasets.length === 1
                        ? "It's only in your browser, though. To propose it for the shared collection, send it in one of these ways."
                        : "They're only in your browser, though. To propose them for the shared collection, send them in one of these ways."}{' '}
                      Only the computed values and your descriptions are sent, never the event logs.
                    </p>
                  }
                  config={config}
                  datasets={[...datasets.filter((d) => !addedKeys.has(d._userKey)), ...addedDatasets]}
                  initialKeys={[...addedKeys]}
                  single={addedDatasets.length === 1}
                  onDone={onClose}
                  onSent={() => onAdded?.(addedDatasets[addedDatasets.length - 1])}
                  cancelLabel="Close"
                />
              </div>
            </>
          )}
        </div>
      </div>
    </>
  );
}
