import { useEffect, useMemo, useState } from 'react';
import { markUserDatasetsSent } from '@/lib/data';
import { getReferral } from '@/lib/referral';
import {
  LICENSE,
  buildSubmission,
  copyText,
  downloadSubmission,
  githubIssueUrl,
  lookupReferral,
  mailtoLink,
  sendSubmission,
} from '@/lib/entries';
import SubmissionPreview from '@/components/SubmissionPreview';

const CONTRIBUTOR_KEY = 'xespresso:contributor';
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

function loadContributor() {
  try {
    return { name: '', institution: '', email: '', ...JSON.parse(localStorage.getItem(CONTRIBUTOR_KEY) || '{}') };
  } catch {
    return { name: '', institution: '', email: '' };
  }
}

function saveContributor(contributor) {
  try {
    localStorage.setItem(CONTRIBUTOR_KEY, JSON.stringify(contributor));
  } catch {
    return;
  }
}

function sentLabel(sent) {
  if (!sent) return null;
  const date = new Date(sent.at).toLocaleDateString();
  return { submit: `sent by email ${date}`, github: `GitHub issue opened ${date}`, download: `downloaded ${date}` }[sent.method] || null;
}

export function SendEntriesPanel({ config, datasets, initialKeys, single = false, intro = null, onDone, onSent, cancelLabel = 'Cancel' }) {
  const contribute = config.contribute || {};
  const submitUrl = contribute.submitUrl;
  const githubRepo = contribute.githubRepo;
  const contactEmail = contribute.email;
  const ttl = contribute.confirmationHours || 48;

  const entries = useMemo(() => datasets.filter((d) => d._userAdded), [datasets]);
  const [selected, setSelected] = useState(() => new Set(initialKeys?.length ? initialKeys : entries.filter((d) => !d._sent).map((d) => d._userKey)));
  const [contributor, setContributor] = useState(loadContributor);
  const [website, setWebsite] = useState('');
  const [consent, setConsent] = useState(false);
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(false);
  const [step, setStep] = useState('form');
  const [result, setResult] = useState(null);
  const [invitedBy, setInvitedBy] = useState(null);
  const [copied, setCopied] = useState(null);
  const [withheld, setWithheld] = useState([]);
  const [opened, setOpened] = useState([]);
  const referral = getReferral();

  useEffect(() => {
    lookupReferral(submitUrl, referral).then((r) => setInvitedBy(r?.status === 'valid' ? r.collaborator || r.tag : null));
  }, [submitUrl, referral]);

  const chosen = entries.filter((d) => selected.has(d._userKey));
  const setField = (key, value) => {
    setError(null);
    setContributor((c) => ({ ...c, [key]: value }));
  };
  const toggle = (key) => {
    setError(null);
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  };

  const problems = (method) => {
    const list = [];
    if (!chosen.length) list.push('choose at least one event log');
    if (method === 'download') return list;
    if (!contributor.name.trim()) list.push('give your name');
    if (method === 'submit' && !EMAIL.test(contributor.email.trim())) list.push('give a valid email address');
    if (!consent) list.push(`accept the ${LICENSE} license terms`);
    return list;
  };

  const submission = (list = chosen) =>
    buildSubmission({
      datasets: list,
      contributor: {
        name: contributor.name.trim(),
        institution: contributor.institution.trim() || null,
        email: contributor.email.trim(),
      },
      referral,
      website,
      consent,
      withheld,
    });

  const finish = async (method, nextStep, extra = {}) => {
    saveContributor(contributor);
    const updated = await markUserDatasetsSent(chosen.map((d) => d._userKey), { method, at: new Date().toISOString() });
    onSent?.(updated);
    setResult({ count: chosen.length, ...extra });
    setStep(nextStep);
  };

  const run = async (method) => {
    const list = problems(method);
    if (list.length) {
      setError(`Please ${list.join(', ')}.`);
      return;
    }
    setError(null);
    if (method === 'github') {
      setOpened([]);
      setStep(chosen.length > 1 ? 'github-batch' : 'github-confirm');
      return;
    }
    if (method === 'download') {
      const s = submission();
      downloadSubmission(s);
      await finish('download', 'downloaded', { mailto: mailtoLink(contactEmail, s) });
      return;
    }
    setBusy(true);
    try {
      const s = submission();
      await sendSubmission(submitUrl, s);
      await finish('submit', 'pending', { email: s.contributor.email });
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const openGitHub = async () => {
    const s = submission();
    const plan = githubIssueUrl(githubRepo, s);
    const copying = plan.mode === 'paste' ? copyText(plan.paste) : null;
    if (plan.mode === 'upload') downloadSubmission(s);
    window.open(plan.url, '_blank', 'noopener');
    let mode = plan.mode;
    if (copying && !(await copying)) {
      downloadSubmission(s);
      mode = 'paste-failed';
    }
    await finish('github', 'github-done', { mode, paste: plan.paste });
  };

  const batchPlan = (d, i) =>
    githubIssueUrl(githubRepo, submission([d]), {
      index: i + 1,
      total: chosen.length,
      others: chosen.filter((x) => x !== d).map((x) => x.basic_info.event_log_name),
    });

  const openOne = async (d, i) => {
    const s = submission([d]);
    const plan = batchPlan(d, i);
    const copying = plan.mode === 'paste' ? copyText(plan.paste) : null;
    if (plan.mode === 'upload') downloadSubmission(s);
    window.open(plan.url, '_blank', 'noopener');
    if (copying && !(await copying)) downloadSubmission(s);
    saveContributor(contributor);
    const updated = await markUserDatasetsSent([d._userKey], { method: 'github', at: new Date().toISOString() });
    onSent?.(updated);
    setOpened((list) => (list.includes(d._userKey) ? list : [...list, d._userKey]));
  };

  const copy = async (what, text) => {
    setCopied((await copyText(text)) ? what : `${what}-failed`);
  };

  const githubPlan = step === 'github-confirm' ? githubIssueUrl(githubRepo, submission()) : null;

  const mailto = contactEmail
    ? `mailto:${contactEmail}?subject=${encodeURIComponent('XESpresso event log submission')}&body=${encodeURIComponent('Please find the XESpresso submission file attached.')}`
    : null;
  const what = result?.count === 1 ? 'entry' : `${result?.count} entries`;

  if (step === 'github-batch') {
    const plans = chosen.map(batchPlan);
    return (
      <>
        <p className="add-log__warning">
          GitHub issues are public: anyone can see the entries, their features and your name. Your email address is not
          included. You need a GitHub account. A GitHub issue can only be prefilled with one entry, so each event log gets
          its own issue with its entry filled in. Open each one and click &quot;Create&quot; on GitHub.
        </p>
        <ul className="send__issues">
          {chosen.map((d, i) => {
            const done = opened.includes(d._userKey);
            return (
              <li key={d._userKey}>
                <span>
                  {i + 1}. {d.basic_info.event_log_name}
                  {plans[i].mode !== 'inline' && (
                    <em className="send__sent">
                      {plans[i].mode === 'paste' ? ' (too long for the link: the entry is copied, paste it into the issue)' : ' (too long: the file is downloaded, attach it)'}
                    </em>
                  )}
                </span>
                <button className={`btn ${done ? 'btn--ghost' : 'btn--primary'}`} onClick={() => openOne(d, i)}>
                  {done ? 'Opened ✓ Open again' : 'Open issue'}
                </button>
              </li>
            );
          })}
        </ul>
        <div className="modal__actions">
          <button className="btn btn--ghost" onClick={() => setStep('form')}>← Back</button>
          <button className="btn btn--primary" onClick={onDone} disabled={opened.length === 0}>
            {opened.length === chosen.length ? 'Done' : `Done (${opened.length} of ${chosen.length} opened)`}
          </button>
        </div>
      </>
    );
  }

  if (step === 'github-confirm') {
    return (
      <>
        <p className="add-log__warning">
          GitHub issues are public: anyone can see the {chosen.length === 1 ? 'entry, its' : `${chosen.length} entries, their`}{' '}
          features and your name. Your email address is not included. You need a GitHub account.{' '}
          {
            {
              inline: 'GitHub opens a new issue with the submission filled in. You check it and submit it.',
              paste:
                'GitHub opens a new issue with a summary filled in, and the full submission is copied to your clipboard. You paste it into the issue and submit it.',
              upload:
                'The submission is too long for the issue text, so GitHub opens a new issue with a summary filled in and the submission file is downloaded. You attach the file and submit the issue.',
            }[githubPlan.mode]
          }
        </p>
        <div className="modal__actions">
          <button className="btn btn--ghost" onClick={() => setStep('form')}>← Back</button>
          <button className="btn btn--primary" onClick={openGitHub}>Continue on GitHub</button>
        </div>
      </>
    );
  }

  if (step !== 'form') {
    return (
      <>
        {step === 'pending' && (
          <>
            <p className="add-log__hint">
              Check your email. We sent a confirmation link to <strong>{result.email}</strong>. The {what}{' '}
              {result.count === 1 ? 'is' : 'are'} sent once you open it. The link is valid for {ttl} hours.
            </p>
            <p className="add-log__note">
              No email after a few minutes? Check your spam folder.
              {mailto ? (
                <>
                  {' '}Or download the {what} and send {result.count === 1 ? 'it' : 'them'} to <a href={mailto}>{contactEmail}</a>.
                </>
              ) : null}
            </p>
          </>
        )}
        {step === 'github-done' && (
          <>
            <p className="add-log__hint">
              {
                {
                  inline: 'GitHub opened a new issue in another tab with everything filled in. Check it and click "Submit new issue".',
                  paste:
                    'GitHub opened a new issue in another tab with a summary filled in, and the full submission was copied to your clipboard. Click at the end of the issue text, paste it (Cmd+V or Ctrl+V), then click "Submit new issue".',
                  'paste-failed':
                    'GitHub opened a new issue in another tab with a summary filled in. Your browser did not allow copying the submission, so the submission file was downloaded instead. Drag the file into the issue text, then click "Submit new issue".',
                  upload:
                    'GitHub opened a new issue in another tab with a summary filled in, and the submission file was downloaded. Drag the file into the issue\'s text field, then click "Submit new issue". If GitHub does not accept it there, submit the issue and attach the file in a comment.',
                }[result.mode]
              }
            </p>
            {result.mode === 'paste' && (
              <div className="send__copy">
                <button className="btn btn--secondary" onClick={() => copy('json', result.paste)}>
                  Copy the submission again
                </button>
                {copied === 'json' && <span className="send__copied">Copied</span>}
                {copied === 'json-failed' && <span className="add-log__error">Copying is not allowed in this browser.</span>}
              </div>
            )}
          </>
        )}
        {step === 'downloaded' && (
          <>
            <p className="add-log__hint">
              The file was downloaded.{' '}
              {contactEmail
                ? 'To propose it for the collection, attach it to an email to this address. "Write the email" opens a draft in your email program with the address, subject and text filled in.'
                : 'To propose it for the collection, send it to the maintainers.'}
            </p>
            {contactEmail && (
              <div className="send__mail">
                <code className="send__address">{contactEmail}</code>
                <div className="send__copy">
                  <a className="btn btn--primary" href={result.mailto || mailto}>
                    Write the email
                  </a>
                  <button className="btn btn--secondary" onClick={() => copy('address', contactEmail)}>
                    Copy address
                  </button>
                  {copied === 'address' && <span className="send__copied">Copied</span>}
                  {copied === 'address-failed' && <span className="add-log__error">Copying is not allowed in this browser.</span>}
                </div>
                <p className="add-log__note">The email program cannot attach the file by itself. Attach the downloaded file before sending.</p>
              </div>
            )}
          </>
        )}
        <div className="modal__actions">
          <button
            className="btn btn--ghost"
            onClick={() => {
              setCopied(null);
              setStep('form');
            }}
          >
            ← Other ways
          </button>
          <button className="btn btn--primary" onClick={onDone}>Done</button>
        </div>
      </>
    );
  }

  return (
    <>
      {intro}
      {invitedBy && <p className="send__invited">Invited by {invitedBy}</p>}

      {!single &&
        (entries.length === 0 ? (
          <p className="add-log__warning">You have not added any event logs yet.</p>
        ) : (
          <div className="add-log__field">
            <label className="filters-panel__label">Event logs</label>
            <ul className="send__entries">
              {entries.map((d) => (
                <li key={d._userKey}>
                  <label className="add-log__check">
                    <input type="checkbox" checked={selected.has(d._userKey)} onChange={() => toggle(d._userKey)} />
                    <span>
                      {d.basic_info.event_log_name}
                      {d._sent && <em className="send__sent"> ({sentLabel(d._sent)})</em>}
                    </span>
                  </label>
                </li>
              ))}
            </ul>
          </div>
        ))}

      <div className="add-log__grid">
        <div className="add-log__field">
          <label className="filters-panel__label">Your name</label>
          <input className="toolbar__search" autoComplete="name" value={contributor.name} onChange={(e) => setField('name', e.target.value)} />
        </div>
        <div className="add-log__field">
          <label className="filters-panel__label">Institution</label>
          <input className="toolbar__search" autoComplete="organization" value={contributor.institution} onChange={(e) => setField('institution', e.target.value)} />
        </div>
      </div>
      {submitUrl && (
        <div className="add-log__field">
          <label className="filters-panel__label">Email</label>
          <input className="toolbar__search" type="email" autoComplete="email" value={contributor.email} onChange={(e) => setField('email', e.target.value)} />
        </div>
      )}
      {chosen.length > 0 && (
        <SubmissionPreview
          datasets={chosen}
          contributor={contributor}
          withEmail={Boolean(submitUrl)}
          withheld={withheld}
          onWithheldChange={setWithheld}
        />
      )}
      <input
        className="send__honeypot"
        tabIndex={-1}
        autoComplete="off"
        aria-hidden="true"
        name="website"
        value={website}
        onChange={(e) => setWebsite(e.target.value)}
      />
      <label className="add-log__check">
        <input
          type="checkbox"
          checked={consent}
          onChange={(e) => {
            setError(null);
            setConsent(e.target.checked);
          }}
        />
        <span>I may share {single ? 'this metadata entry' : 'these metadata entries'}, and {single ? 'it' : 'they'} may be published in XESpresso under {LICENSE}.</span>
      </label>

      {error && <p className="add-log__error">{error}</p>}

      <div className="send__ways">
        <button className="btn btn--secondary" onClick={() => run('download')} disabled={busy}>
          Download
        </button>
        {submitUrl && (
          <button className="btn btn--primary" onClick={() => run('submit')} disabled={busy}>
            {busy ? 'Sending…' : 'Send by email'}
          </button>
        )}
        {githubRepo && (
          <button className="btn btn--primary" onClick={() => run('github')} disabled={busy}>
            Open a GitHub issue
          </button>
        )}
      </div>
      <ul className="send__explain">
        <li><strong>Download</strong> saves the entry as a file, which you can email to {mailto ? <a href={mailto}>us</a> : 'us'}. After the download, you can open an email draft or copy our address.</li>
        {submitUrl && (
          <li>
            <strong>Send by email</strong> needs your name and email: you get a link to confirm, then the maintainers receive it for
            review. Your address is stored in the EU and never published.
          </li>
        )}
        {githubRepo && (
          <li><strong>Open a GitHub issue</strong> needs your name and a GitHub account. The issue is public.</li>
        )}
      </ul>

      {onDone && (
        <div className="modal__actions">
          <button className="btn btn--ghost" onClick={onDone}>{cancelLabel}</button>
        </div>
      )}
    </>
  );
}

export default function SendEntriesModal({ config, datasets, initialKeys, onClose, onSent }) {
  return (
    <>
      <div className="modal__backdrop" onClick={onClose} />
      <div className="modal" role="dialog" aria-labelledby="send-title">
        <div className="modal__header">
          <h2 id="send-title">Send event logs to the collection</h2>
          <button className="modal__close" onClick={onClose} aria-label="Close">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M18 6L6 18M6 6l12 12" />
            </svg>
          </button>
        </div>
        <div className="modal__body">
          <SendEntriesPanel
            config={config}
            datasets={datasets}
            initialKeys={initialKeys}
            onDone={onClose}
            onSent={onSent}
            intro={
              <p className="add-log__hint">
                Only the computed values and your descriptions are sent, never the event log files. The maintainers review
                every submission before it is added to the collection.
              </p>
            }
          />
        </div>
      </div>
    </>
  );
}
