import * as d3 from 'd3';

/**
 * Grouped correlation heatmap. `orderedFeatures` is the full feature list in
 * display order (grouped by semantic feature family); `matrix`/`featureIndex`
 * let us look up any pair's
 * correlation regardless of the original (alphabetical) matrix order.
 */
export function createCorrelationHeatmap(
  container,
  { orderedFeatures, matrix, featureIndex, groupBoundaries, highlighted } = {}
) {
  const n = orderedFeatures.length;
  const layout = container.closest('.feature-selection__layout') || container.parentElement;
  const sideBySide = layout && getComputedStyle(layout).gridTemplateColumns.split(' ').length > 1;
  const availableWidth = Math.max(
    240,
    (sideBySide ? layout.clientWidth - 340 - 24 : layout?.clientWidth || container.clientWidth || 900) - 34
  );
  // Cap the cell size so the whole matrix fits within the remaining viewport
  // height too — the heatmap shouldn't push the page below the fold.
  const top = container.getBoundingClientRect().top;
  const availableHeight = Math.max(240, window.innerHeight - top - 64);
  const cell = Math.max(6, Math.min(24, Math.floor(availableWidth / n), Math.floor(availableHeight / n)));
  const margin = { top: 4, right: 4, bottom: 4, left: 4 };
  const size = n * cell;
  const width = size + margin.left + margin.right;
  const height = size + margin.top + margin.bottom;

  const color = d3.scaleSequential(d3.interpolateRdBu).domain([1, -1]);

  const svg = d3
    .select(container)
    .append('svg')
    .attr('width', width)
    .attr('height', height)
    .attr('viewBox', [0, 0, width, height]);

  const g = svg.append('g').attr('transform', `translate(${margin.left},${margin.top})`);

  const tooltip = d3.select(container).append('div').attr('class', 'landscape-tooltip').style('opacity', 0);

  const cells = [];
  for (let i = 0; i < n; i += 1) {
    for (let j = 0; j < n; j += 1) {
      const fi = featureIndex[orderedFeatures[i]];
      const fj = featureIndex[orderedFeatures[j]];
      cells.push({ i, j, value: matrix[fi][fj], a: orderedFeatures[i], b: orderedFeatures[j] });
    }
  }

  const highlightedSet = highlighted || new Set();

  g.selectAll('rect.heatmap-cell')
    .data(cells)
    .join('rect')
    .attr('class', 'heatmap-cell')
    .attr('x', (d) => d.j * cell)
    .attr('y', (d) => d.i * cell)
    .attr('width', cell)
    .attr('height', cell)
    .attr('fill', (d) => color(d.value))
    .attr('opacity', (d) => (highlightedSet.size === 0 || (highlightedSet.has(d.a) && highlightedSet.has(d.b)) ? 1 : 0.4))
    .attr('stroke', (d) => (highlightedSet.has(d.a) && highlightedSet.has(d.b) ? 'var(--text)' : 'none'))
    .attr('stroke-width', 0.75)
    .on('mouseenter', (event, d) => {
      tooltip.style('opacity', 1).html(`${d.a}<br/>× ${d.b}<br/><strong>${d.value.toFixed(3)}</strong>`);
    })
    .on('mousemove', (event) => {
      const [mx, my] = d3.pointer(event, container);
      const tooltipWidth = tooltip.node().offsetWidth;
      const overflowsRight = mx + 12 + tooltipWidth > container.clientWidth;
      const left = overflowsRight ? mx - 12 - tooltipWidth : mx + 12;
      tooltip.style('left', `${left}px`).style('top', `${my + 12}px`);
    })
    .on('mouseleave', () => tooltip.style('opacity', 0));

  (groupBoundaries || []).forEach((b) => {
    if (b === 0 || b === n) return;
    g.append('line')
      .attr('x1', b * cell).attr('x2', b * cell)
      .attr('y1', 0).attr('y2', size)
      .attr('stroke', 'var(--bg)').attr('stroke-width', 2);
    g.append('line')
      .attr('y1', b * cell).attr('y2', b * cell)
      .attr('x1', 0).attr('x2', size)
      .attr('stroke', 'var(--bg)').attr('stroke-width', 2);
  });

  return {
    destroy: () => {
      tooltip.remove();
      svg.remove();
    },
  };
}
