import { useCallback, useEffect, useMemo, useState } from 'react';
import Header from '@/components/Header';
import CorrelationHeatmap from '@/components/CorrelationHeatmap';
import CorrelationCurve from '@/components/CorrelationCurve';
import { loadConfig, loadFeatureSelection } from '@/lib/data';
import { humanize } from '@/lib/humanize';
import { FEATURE_GROUP_LABELS } from '@/lib/featureGroups';
import { selectionCurves } from '@/lib/featureSelectionScores';
import { CORRELATION_COLOR, EXPLAINED_COLOR } from '@/viz/correlationCurve';
import InfoTip from '@/components/InfoTip';

const GROUP_PREFIXES = {
  trace_length: 'trace_len_',
  activities: 'activities_',
  start_activities: 'start_activities_',
  end_activities: 'end_activities_',
  eventropies: 'eventropy_',
  epa_based: 'epa_',
};

function shortName(name, group) {
  const prefix = GROUP_PREFIXES[group];
  return humanize(prefix && name.startsWith(prefix) ? name.slice(prefix.length) : name);
}

const MIN_FEATURES = 2;
const DEFAULT_FEATURES = 9;

export default function FeatureSelectionPage() {
  const [config, setConfig] = useState(null);
  const [data, setData] = useState(null);
  const [numFeatures, setNumFeatures] = useState(DEFAULT_FEATURES);

  useEffect(() => {
    Promise.all([loadConfig(), loadFeatureSelection()]).then(([c, d]) => {
      setConfig(c);
      setData(d);
    });
  }, []);

  const derived = useMemo(() => {
    if (!data) return null;
    const featureIndex = {};
    data.features.forEach((f, i) => {
      featureIndex[f] = i;
    });

    const orderedFeatures = [];
    const groupBoundaries = [];
    Object.values(data.groups).forEach((names) => {
      orderedFeatures.push(...names);
      groupBoundaries.push(orderedFeatures.length);
    });

    const curve = selectionCurves(data.greedy_order, data.correlation_matrix, featureIndex, MIN_FEATURES);
    return { featureIndex, orderedFeatures, groupBoundaries, curve };
  }, [data]);

  const maxFeatures = data ? data.greedy_order.length : MIN_FEATURES;
  const selectK = useCallback((k) => setNumFeatures(Math.max(MIN_FEATURES, Math.min(maxFeatures, k))), [maxFeatures]);

  const selected = useMemo(() => {
    if (!data) return [];
    return data.greedy_order.slice(0, numFeatures);
  }, [data, numFeatures]);

  const highlighted = useMemo(() => new Set(selected), [selected]);
  const rank = useMemo(() => new Map(selected.map((n, i) => [n, i + 1])), [selected]);

  const point = derived?.curve.find((d) => d.k === numFeatures) || null;

  if (!config || !data || !derived) {
    return (
      <div className="main-layout">
        <div className="loading">
          <div className="loading__spinner" />
          <p>Loading...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="main-layout">
      <Header config={config} />
      <main className="main-content">
        <h1 className="t-page-title feature-selection__title">
          Feature Correlations
          <InfoTip label="How the correlations and the selection are computed">
            <span>
              The {data.features.length} FEEED features are correlated pairwise (Pearson r) across {data.n_logs} event
              logs, each pair over the logs that have both values. The heatmap groups the features by family.
            </span>
            <span>
              The selection is greedy. It starts with the feature that has the lowest mean correlation to all others, then
              repeatedly adds the remaining feature with the smallest maximum correlation to the features already picked.
              The slider takes the first k features of this order.
            </span>
          </InfoTip>
        </h1>
        <p className="graph-page__description">
          How the {data.features.length} FEEED features correlate across {data.n_logs} event logs, and how many of the
          least correlated features describe the event logs well without repeating each other.
          {data.recomputed
            ? ` The correlations and the selection include the ${data.n_user_logs} event ${data.n_user_logs === 1 ? 'log' : 'logs'} you added and were recomputed in your browser.`
            : ''}
        </p>

        <section className="landscape-section">
          <div className="feature-selection__controls">
            <label htmlFor="num-features">Least-correlated features: {numFeatures}</label>
            <input
              id="num-features"
              type="range"
              min={MIN_FEATURES}
              max={maxFeatures}
              value={numFeatures}
              onChange={(e) => selectK(Number(e.target.value))}
            />
            {point && (
              <>
                <span className="feature-selection__mean" style={{ '--score-color': CORRELATION_COLOR }}>
                  Average pairwise correlation: <strong>{point.mean.toFixed(3)}</strong>
                </span>
                <span className="feature-selection__mean" style={{ '--score-color': EXPLAINED_COLOR }}>
                  Variance Explained: <strong>{(point.explained * 100).toFixed(1)}%</strong>
                </span>
              </>
            )}
          </div>

          <div className="feature-selection__layout">
            <div className="feature-selection__heatmap">
              <CorrelationHeatmap
                orderedFeatures={derived.orderedFeatures}
                matrix={data.correlation_matrix}
                featureIndex={derived.featureIndex}
                groupBoundaries={derived.groupBoundaries}
                highlighted={highlighted}
              />
              <div className="heatmap-legend">
                <span>−1</span>
                <span className="heatmap-legend__bar" />
                <span>+1</span>
                <span className="heatmap-legend__label">Pearson r. Outlined cells: pairs of selected features.</span>
              </div>
            </div>

            <div className="feature-selection__sidebar">
              <div>
                <h3 className="feature-group__title feature-selection__title">
                  Trade-off by number of features
                  <InfoTip label="What the two curves show">
                    <span>
                      <strong>Average pairwise correlation</strong>: the mean absolute Pearson r over all pairs of the k
                      features. Lower means the features repeat each other less.
                    </span>
                    <span>
                      <strong>Variance Explained</strong>: the share of the variance of all {data.features.length} features
                      that the k features explain together. It is the average R² of each feature predicted from them,
                      computed from the correlation matrix. Higher means the k features stand in better for all of them.
                    </span>
                    <span>
                      Few features correlate little but leave variance unexplained. More features explain more but repeat
                      each other. Click a curve to choose k.
                    </span>
                  </InfoTip>
                </h3>
                <CorrelationCurve curve={derived.curve} selected={numFeatures} onSelect={selectK} />
              </div>

              <div>
                <h3 className="feature-group__title feature-selection__title">
                  Selected features by group
                  <InfoTip label="How to read the groups">
                    <span>
                      Each row is a feature group with the number of its features that are selected. The chips are the
                      selected features, numbered in the order the selection picked them. Hover a chip for its full name.
                    </span>
                  </InfoTip>
                </h3>
                <ul className="feature-groups-compact">
                  {Object.entries(data.groups).map(([group, names]) => {
                    const picked = selected.filter((n) => data.feature_to_group[n] === group);
                    return (
                      <li key={group} className={picked.length ? '' : 'feature-groups-compact__row--empty'}>
                        <span className="feature-groups-compact__name">
                          {FEATURE_GROUP_LABELS[group] || humanize(group)}
                          <span className="filter-chip__count">
                            {' '}
                            {picked.length}/{names.length}
                          </span>
                        </span>
                        <span className="feature-groups-compact__chips">
                          {picked.map((name) => (
                            <span className="feature-chip" key={name} title={humanize(name)}>
                              <span className="feature-chip__rank">{rank.get(name)}</span>
                              {shortName(name, group)}
                            </span>
                          ))}
                        </span>
                      </li>
                    );
                  })}
                </ul>
              </div>
            </div>
          </div>
        </section>
      </main>
    </div>
  );
}
