import { useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { createFeatureSpaceScatter } from '@/viz/featureSpace';

export default function FeatureSpaceScatter({ points, colorBy, colors, hullBy, hullColors, explainedVariance }) {
  const containerRef = useRef(null);
  const navigate = useNavigate();

  useEffect(() => {
    if (!containerRef.current || points.length === 0) return undefined;

    const opts = {
      colorBy,
      colors,
      hullBy,
      hullColors,
      explainedVariance,
      onPointClick: (id) => navigate(`/datasets/${id}`),
    };

    let instance = createFeatureSpaceScatter(containerRef.current, points, opts);

    const handleResize = () => {
      instance.destroy();
      instance = createFeatureSpaceScatter(containerRef.current, points, opts);
    };
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      instance.destroy();
    };
  }, [points, colorBy, colors, hullBy, hullColors, explainedVariance, navigate]);

  return <div className="landscape-viz" ref={containerRef} />;
}
