const DATACITE = 'https://api.datacite.org/dois/';
const CROSSREF = 'https://api.crossref.org/works/';

const CROSSREF_PUBLICATION_TYPES = {
  'journal-article': 'Journal Article',
  'proceedings-article': 'Conference Paper',
  'book-chapter': 'Conference Paper',
};

export function findDoi(input) {
  const text = String(input || '').trim();
  const doi = /10\.\d{4,9}\/[^\s"'<>?#]+/.exec(text);
  if (doi) return doi[0].replace(/[.,;)\]]+$/, '');
  const zenodo = /zenodo\.org\/(?:records?|deposit)\/(\d+)/i.exec(text);
  if (zenodo) return `10.5281/zenodo.${zenodo[1]}`;
  const figshare = /figshare\.com\/articles\/(?:[^/]+\/)*(\d+)(?:\/\d+)?\/?$/i.exec(text.split(/[?#]/)[0]);
  if (figshare) return `10.6084/m9.figshare.${figshare[1]}`;
  return null;
}

function initials(given) {
  return String(given || '')
    .split(/[\s-]+/)
    .filter(Boolean)
    .map((part) => `${part[0].toUpperCase()}.`)
    .join(' ');
}

function formatAuthors(people) {
  const names = people
    .map(({ family, given, name }) => (family ? [family, initials(given)].filter(Boolean).join(', ') : name))
    .filter(Boolean);
  if (names.length <= 1) return names.join('');
  return `${names.slice(0, -1).join(', ')}, & ${names[names.length - 1]}`;
}

function citation({ people, year, title, kind, publisher, doi }) {
  const authors = formatAuthors(people);
  return [
    authors && `${authors}${authors.endsWith('.') ? '' : '.'}`,
    year && `(${year}).`,
    title && `${title}${kind ? ` [${kind}]` : ''}.`,
    publisher && `${publisher}.`,
    `https://doi.org/${doi}`,
  ]
    .filter(Boolean)
    .join(' ');
}

function plainText(html, max = 600) {
  const text = String(html || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
  return text.length > max ? `${text.slice(0, max - 1).trimEnd()}…` : text;
}

async function fromDataCite(doi) {
  const res = await fetch(`${DATACITE}${encodeURIComponent(doi)}`);
  if (res.status === 404) return null;
  if (!res.ok) throw new Error(`DataCite answered ${res.status}.`);
  const a = (await res.json()).data.attributes;
  const title = (a.titles?.[0]?.title || '').replace(/\s+/g, ' ').trim();
  const people = (a.creators || []).map((c) => ({ family: c.familyName, given: c.givenName, name: c.name }));
  const kind = a.types?.resourceTypeGeneral === 'Dataset' ? 'Data set' : a.types?.resourceTypeGeneral;
  const description = (a.descriptions || []).find((d) => d.descriptionType === 'Abstract') || a.descriptions?.[0];
  return {
    registry: 'DataCite',
    doi: a.doi || doi,
    name: title,
    year: a.publicationYear || null,
    reference: citation({ people, year: a.publicationYear, title, kind, publisher: a.publisher, doi: a.doi || doi }),
    description: plainText(description?.description),
    publicationType: null,
    license: a.rightsList?.[0]?.rights || null,
  };
}

async function fromCrossref(doi) {
  const res = await fetch(`${CROSSREF}${encodeURIComponent(doi)}`);
  if (res.status === 404) return null;
  if (!res.ok) throw new Error(`Crossref answered ${res.status}.`);
  const m = (await res.json()).message;
  const title = (m.title?.[0] || '').replace(/\s+/g, ' ').trim();
  const year = (m.published || m['published-print'] || m['published-online'])?.['date-parts']?.[0]?.[0] || null;
  const people = (m.author || []).map((p) => ({ family: p.family, given: p.given, name: p.name }));
  return {
    registry: 'Crossref',
    doi: m.DOI || doi,
    name: title,
    year,
    reference: citation({ people, year, title, publisher: m['container-title']?.[0] || m.publisher, doi: m.DOI || doi }),
    description: plainText(m.abstract),
    publicationType: CROSSREF_PUBLICATION_TYPES[m.type] || null,
    license: null,
  };
}

export async function lookupDoi(input) {
  const doi = findDoi(input);
  if (!doi) throw new Error('No DOI found. Enter a DOI, a doi.org link, or a Zenodo or figshare record link.');
  let result;
  try {
    result = (await fromDataCite(doi)) || (await fromCrossref(doi));
  } catch (e) {
    throw new Error(`The DOI lookup failed (${e.message || 'no connection'}). You can still fill in the fields by hand.`);
  }
  if (!result) throw new Error(`No record found for DOI ${doi}.`);
  return result;
}
