import { useEffect, useMemo, useState } from 'react';
import Header from '@/components/Header';
import FeatureSpaceScatter from '@/components/FeatureSpaceScatter';
import ConceptSelect from '@/components/ConceptSelect';
import InfoTip from '@/components/InfoTip';
import { loadConfig, loadDatasets, loadFeatureSpace } from '@/lib/data';
import { humanize } from '@/lib/humanize';
import { CONCEPTS, NOT_GIVEN, conceptByKey, conceptColors, conceptValue } from '@/lib/concepts';

function pointRecord(p) {
  return {
    domain_context: { domain_application: p.domain_application, event_log_type: p.event_log_type },
    academic_context: {},
    basic_info: {},
  };
}

function presentValues(points, key, minCount = 1) {
  const counts = new Map();
  points.forEach((p) => counts.set(p.concepts[key], (counts.get(p.concepts[key]) || 0) + 1));
  return [...counts.entries()]
    .filter(([, n]) => n >= minCount)
    .sort((a, b) => (a[0] === NOT_GIVEN) - (b[0] === NOT_GIVEN) || b[1] - a[1])
    .map(([v]) => v);
}

function Legend({ title, values, colors }) {
  if (!values.length) return null;
  return (
    <div className="graph-legend">
      <span className="graph-legend__title">{title}</span>
      <div className="graph-legend__items">
        {values.map((v) => (
          <span className="graph-legend__item" key={v}>
            <span className="graph-legend__swatch" style={{ background: colors[v] }} />
            {v}
          </span>
        ))}
      </div>
    </div>
  );
}

function LoadingsBar({ loadings }) {
  const entries = Object.entries(loadings)
    .sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]))
    .slice(0, 12);
  const maxAbs = Math.max(...entries.map(([, v]) => Math.abs(v)), 0.0001);

  return (
    <div className="loadings-bar">
      {entries.map(([name, value]) => (
        <div className="loadings-bar__row" key={name}>
          <span className="loadings-bar__label">{humanize(name)}</span>
          <div className="loadings-bar__track">
            <div
              className={`loadings-bar__fill ${value < 0 ? 'loadings-bar__fill--negative' : ''}`}
              style={{ width: `${(Math.abs(value) / maxAbs) * 100}%` }}
            />
          </div>
          <span className="loadings-bar__value">{value.toFixed(3)}</span>
        </div>
      ))}
    </div>
  );
}

export default function FeatureSpaceExplorationPage() {
  const [config, setConfig] = useState(null);
  const [featureSpace, setFeatureSpace] = useState(null);
  const [datasets, setDatasets] = useState(null);
  const [colorBy, setColorBy] = useState('domain_application');
  const [showHulls, setShowHulls] = useState(true);
  const hullBy = showHulls ? colorBy : '';

  useEffect(() => {
    Promise.all([loadConfig(), loadFeatureSpace(), loadDatasets()]).then(([c, fs, d]) => {
      setConfig(c);
      setFeatureSpace(fs);
      setDatasets(d);
    });
  }, []);

  const points = useMemo(() => {
    if (!featureSpace || !datasets) return [];
    const byId = new Map(datasets.map((d) => [d._id, d]));
    return featureSpace.points.map((p) => {
      const record = byId.get(p.id) || pointRecord(p);
      return { ...p, concepts: Object.fromEntries(CONCEPTS.map((c) => [c.key, conceptValue(c, record)])) };
    });
  }, [featureSpace, datasets]);

  const colorValues = useMemo(() => presentValues(points, colorBy), [points, colorBy]);
  const colors = useMemo(() => conceptColors(conceptByKey(colorBy), colorValues, config), [colorBy, colorValues, config]);

  if (!config || !featureSpace || !datasets) {
    return (
      <div className="main-layout">
        <div className="loading">
          <div className="loading__spinner" />
          <p>Loading...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="main-layout">
      <Header config={config} />
      <main className="main-content">
        <h1 className="t-page-title">Event Data Space</h1>
        <p className="graph-page__description">
          {featureSpace.n_points} event logs placed by their {featureSpace.n_features} FEEED features. The chosen concept
          colors the points and outlines each of its groups with at least 3 event logs. Click a point to open its event
          log.
        </p>

        <h2 className="detail-section__title feature-selection__title">
          Principal Component Analysis
          <InfoTip label="How the projection is computed">
            <span>
              Each event log is described by the {featureSpace.n_features} FEEED features computed for every collection.
              Missing values are replaced by the feature's mean (mean imputation), each feature is min-max scaled to 0–1 so
              that features with large raw values don't dominate, and each log's vector is scaled to length 1 (L2
              normalization).
            </span>
            <span>
              A principal component analysis (PCA) then projects the vectors onto the two directions with the most variance,
              PC1 and PC2. Their share of the variance is given on the axes.
            </span>
            <span>
              {featureSpace.n_user_points
                ? `The ${featureSpace.n_user_points} event ${featureSpace.n_user_points === 1 ? 'log' : 'logs'} you added ${featureSpace.n_user_points === 1 ? 'is' : 'are'} included: the imputation, scaling and components were recomputed in your browser, so positions and hulls can differ slightly from the published projection.`
                : 'When you add event logs, they are included and the projection is recomputed in your browser.'}{' '}
              Your event logs are marked with a dashed ring.
            </span>
          </InfoTip>
        </h2>
        <p className="graph-page__description">
          The two directions in which the event logs differ most, so that logs close to each other have similar features.
          {featureSpace.n_user_points
            ? ` Recomputed with your ${featureSpace.n_user_points} added event ${featureSpace.n_user_points === 1 ? 'log' : 'logs'}.`
            : ''}
        </p>

        <section className="landscape-section">
          <div className="concept-controls">
            <ConceptSelect id="fs-concept" label="Concept" value={colorBy} onChange={setColorBy} />
            <label className="add-log__check concept-controls__check">
              <input type="checkbox" checked={showHulls} onChange={(e) => setShowHulls(e.target.checked)} />
              <span>Convex hulls</span>
            </label>
          </div>
          <FeatureSpaceScatter
            points={points}
            colorBy={colorBy}
            colors={colors}
            hullBy={hullBy}
            hullColors={colors}
            explainedVariance={featureSpace.explained_variance_ratio}
          />
          <Legend title={conceptByKey(colorBy).label} values={colorValues} colors={colors} />
        </section>

        <div className="loadings-pair">
          <section className="detail-section">
            <h2 className="detail-section__title feature-selection__title">
              Top Features Driving PC1
              <InfoTip label="What the loadings show">
                <span>
                  The 12 features with the largest weights (loadings) in the component. A long bar means the feature moves
                  event logs strongly along the axis. Positive and negative weights push in opposite directions.
                </span>
              </InfoTip>
            </h2>
            <LoadingsBar loadings={featureSpace.loadings_pc1} />
          </section>
          <section className="detail-section">
            <h2 className="detail-section__title">Top Features Driving PC2</h2>
            <LoadingsBar loadings={featureSpace.loadings_pc2} />
          </section>
        </div>
      </main>
    </div>
  );
}
