import { featureSetNames } from './featureSets';

export const FEATURE_CODE = 'FEEED 2.2.0 (XESpresso in-browser port)';
export const APP_VERSION = typeof __APP_VERSION__ === 'string' ? __APP_VERSION__ : 'dev';
export const LICENSE = 'CC BY 4.0';

const GITHUB_URL_LIMIT = 6000;
export const GITHUB_BODY_LIMIT = 65536;

export function entryForDownload(dataset) {
  const { _id, _userAdded, _userKey, _addedAt, _warnings, _featureSet, _sent, ...entry } = dataset;
  return {
    format: 'xespresso-entry',
    version: 1,
    created: _addedAt || new Date().toISOString(),
    feature_code: FEATURE_CODE,
    feature_set: _featureSet || 'all',
    warnings: _warnings || [],
    entry,
  };
}

function saveJson(data, fileName) {
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

export function downloadEntry(dataset) {
  saveJson(entryForDownload(dataset), `${dataset._id || 'event-log'}.xespresso.json`);
}

