export function withholdFields(dataset, withheld = []) {
  if (!withheld.length) return dataset;
  const copy = JSON.parse(JSON.stringify(dataset));
  SHAREABLE_FIELDS.filter((f) => withheld.includes(f.id)).forEach((f) =>
    f.paths.forEach((path) => {
      const keys = path.split('.');
      const last = keys.pop();
      const parent = keys.reduce((o, k) => (o ? o[k] : undefined), copy);
      if (parent && last in parent) parent[last] = null;
    })
  );
  return copy;
}

export function buildSubmission({ datasets, contributor, referral, website = '', consent = true, withheld = [] }) {
  return {
    format: 'xespresso-submission',
    version: 1,
    created: new Date().toISOString(),
    app_version: APP_VERSION,
    feature_code: FEATURE_CODE,
    referral: referral || null,
    contributor,
    consent: { license: LICENSE, accepted: Boolean(consent) },
    withheld_fields: SHAREABLE_FIELDS.filter((f) => withheld.includes(f.id)).map((f) => f.label),
    entries: datasets.map((d) => entryForDownload(withholdFields(d, withheld))),
    website,
  };
}

export function downloadSubmission(submission) {
  const data = publicSubmission(submission);
  saveJson(data, submissionFileName(data));
}

export async function sendSubmission(url, submission) {
  let res;
  try {
    res = await fetch(url, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(submission) });
  } catch {
    throw new Error('The submission service could not be reached. Please check your connection, or download the entries and email them.');
  }
  const body = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(body.error || `The submission service answered with an error (${res.status}).`);
  return body;
}

export async function lookupReferral(url, tag) {
  if (!url || !tag) return null;
  try {
    const res = await fetch(`${url}${url.includes('?') ? '&' : '?'}action=referral&tag=${encodeURIComponent(tag)}`);
    return res.ok ? res.json() : null;
  } catch {
    return null;
  }
}

export function publicSubmission(submission) {
  const { website, contributor, ...rest } = submission;
  return { ...rest, contributor: { name: contributor.name, institution: contributor.institution || null } };
}

export function submissionFileName(submission) {
  return `xespresso-submission-${submission.created.slice(0, 10)}.json`;
}

function entrySummary({ entry }) {
  const info = entry.basic_info || {};
  const domain = entry.domain_context || {};
  const source = entry.source_url || info.notes || 'no source given';
  const details = [
    domain.domain_application,
    domain.event_log_type,
    entry.academic_context?.year,
    `${info.number_of_cases ?? '?'} cases, ${info.number_of_events ?? '?'} events, ${info.number_of_activities ?? '?'} activities`,
  ].filter(Boolean);
  return `- **${info.event_log_name || 'Unnamed event log'}**: ${source}. ${details.join(' · ')}`;
}

function withoutEmpty(value) {
  if (Array.isArray(value)) return value.map(withoutEmpty);
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(
    Object.entries(value)
      .map(([k, v]) => [k, withoutEmpty(v)])
      .filter(([, v]) => v !== null && v !== undefined && !(Array.isArray(v) && !v.length) && !(typeof v === 'object' && !Array.isArray(v) && !Object.keys(v).length))
  );
}

function packEntry(item) {
  const features = item.entry.feeed_features;
  const names = item.feature_set === 'default' ? featureSetNames('default') : null;
  if (!features || !names || !Object.keys(features).every((k) => names.includes(k))) return withoutEmpty(item);
  const { feeed_features: _features, ...entry } = item.entry;
  return { ...withoutEmpty({ ...item, entry }), feeed_feature_values: names.map((n) => (n in features ? features[n] : null)) };
}

export function packSubmission(data) {
  return {
    ...withoutEmpty({ ...data, entries: undefined }),
    packing:
      'Empty fields are left out. For feature_set "default", feeed_feature_values holds the feature values in the order of src/lib/featureSets.json (default), with null for undefined features.',
    entries: data.entries.map(packEntry),
  };
}

function jsonBlock(data) {
  return ['<details><summary>Submission (JSON)</summary>', '', '```json', JSON.stringify(data), '```', '</details>'].join('\n');
}

export function githubIssueUrl(repo, submission, batch = null) {
  const data = publicSubmission(submission);
  const names = data.entries.map((e) => e.entry.basic_info?.event_log_name || 'Unnamed event log');
  const title = `Event log submission: ${names[0]}${names.length > 1 ? ` and ${names.length - 1} more` : ''}`;
  const who = [data.contributor.name, data.contributor.institution].filter(Boolean).join(', ');
  const head = [
    `Submitted through XESpresso (${data.app_version}, ${data.feature_code}).`,
    '',
    `**Contributor**: ${who || 'not given'}`,
    `**Referral**: ${data.referral || 'none'}`,
    `**License**: the contributor may share these metadata entries, and they may be published under ${data.consent.license}.`,
    ...(data.withheld_fields?.length ? [`**Not shared by the contributor**: ${data.withheld_fields.join(', ')}`] : []),
    ...(batch ? [`**Part ${batch.index} of ${batch.total}**: submitted together with ${batch.others.join(', ')}, each in its own issue.`] : []),
    '',
    `**Event logs (${names.length})**`,
  ];
  const json = jsonBlock(data);
  const packed = jsonBlock(packSubmission(data));
  const summary = [...head, ...data.entries.map(entrySummary)];
  const make = (body) =>
    `https://github.com/${repo}/issues/new?${new URLSearchParams({ title, body: body.join('\n'), labels: 'event-log-submission' })}`;

  const inline = make([...summary, '', packed]);
  if (inline.length <= GITHUB_URL_LIMIT) return { url: inline, mode: 'inline', paste: null };

  const pasteBody = [...summary, '', '**Submission (JSON)**: paste it below this line.', '', ''];
  if (pasteBody.join('\n').length + json.length < GITHUB_BODY_LIMIT) {
    const url = make(pasteBody);
    if (url.length <= GITHUB_URL_LIMIT) return { url, mode: 'paste', paste: json };
    const short = make([...head, ...names.map((n) => `- ${n}`), '', '**Submission (JSON)**: paste it below this line.', '', '']);
    if (short.length <= GITHUB_URL_LIMIT) return { url: short, mode: 'paste', paste: json };
  }

  const attach = ['', `**Submission file**: ${submissionFileName(data)} is attached below.`];
  const withSummary = make([...summary, ...attach]);
  if (withSummary.length <= GITHUB_URL_LIMIT) return { url: withSummary, mode: 'upload', paste: null };
  return { url: make([...head, ...names.map((n) => `- ${n}`), ...attach]), mode: 'upload', paste: null };
}

export async function copyText(text) {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    try {
      const area = document.createElement('textarea');
      area.value = text;
      area.setAttribute('readonly', '');
      area.style.position = 'fixed';
      area.style.opacity = '0';
      document.body.appendChild(area);
      area.select();
      const ok = document.execCommand('copy');
      area.remove();
      return ok;
    } catch {
      return false;
    }
  }
}

export function mailtoLink(address, submission) {
  if (!address) return null;
  const data = publicSubmission(submission);
  const names = data.entries.map((e) => e.entry.basic_info?.event_log_name || 'Unnamed event log');
  const subject = `XESpresso event log submission: ${names[0]}${names.length > 1 ? ` and ${names.length - 1} more` : ''}`;
  const body = [
    'Hello,',
    '',
    `Please find attached the XESpresso submission file ${submissionFileName(data)} with ${names.length === 1 ? 'this event log' : `these ${names.length} event logs`}:`,
    ...names.map((n) => `- ${n}`),
    '',
    ...(data.consent?.accepted
      ? [`I may share these metadata entries, and they may be published in XESpresso under ${data.consent.license}.`, '']
      : []),
    [data.contributor.name, data.contributor.institution].filter(Boolean).join(', '),
  ].join('\n');
  return `mailto:${address}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
}
