import * as d3 from 'd3';
import { escapeHtml } from '@/lib/humanize';

import { NOT_GIVEN } from '@/lib/concepts';

export function createFeatureSpaceScatter(container, points, { colorBy, colors, hullBy, hullColors, explainedVariance, onPointClick } = {}) {
  const width = container.clientWidth || 900;
  const height = Math.max(480, Math.min(width * 0.6, 620));
  const margin = { top: 24, right: 16, bottom: 48, left: 48 };

  const xExtent = d3.extent(points, (p) => p.PC1);
  const yExtent = d3.extent(points, (p) => p.PC2);
  const xPad = ((xExtent[1] - xExtent[0]) || 1) * 0.02;
  const yPad = ((yExtent[1] - yExtent[0]) || 1) * 0.05;

  const x = d3
    .scaleLinear()
    .domain([xExtent[0] - xPad, xExtent[1] + xPad])
    .range([margin.left, width - margin.right]);

  const y = d3
    .scaleLinear()
    .domain([yExtent[0] - yPad, yExtent[1] + yPad])
    .range([height - margin.bottom, margin.top]);

  const svg = d3
    .select(container)
    .append('svg')
    .attr('width', width)
    .attr('height', height)
    .attr('viewBox', [0, 0, width, height]);

  svg
    .append('line')
    .attr('x1', margin.left)
    .attr('x2', width - margin.right)
    .attr('y1', y(0))
    .attr('y2', y(0))
    .attr('stroke', 'var(--border-subtle)')
    .attr('stroke-dasharray', '2,2');

  svg
    .append('line')
    .attr('y1', margin.top)
    .attr('y2', height - margin.bottom)
    .attr('x1', x(0))
    .attr('x2', x(0))
    .attr('stroke', 'var(--border-subtle)')
    .attr('stroke-dasharray', '2,2');

  const pc1Pct = explainedVariance?.[0] ? `${(explainedVariance[0] * 100).toFixed(1)}%` : '';
  const pc2Pct = explainedVariance?.[1] ? `${(explainedVariance[1] * 100).toFixed(1)}%` : '';

  svg
    .append('g')
    .attr('transform', `translate(0,${height - margin.bottom})`)
    .call(d3.axisBottom(x).ticks(6))
    .call((g) => g.selectAll('text').attr('fill', 'var(--text-muted)'))
    .call((g) => g.selectAll('line,path').attr('stroke', 'var(--border)'));

  svg
    .append('g')
    .attr('transform', `translate(${margin.left},0)`)
    .call(d3.axisLeft(y).ticks(6))
    .call((g) => g.selectAll('text').attr('fill', 'var(--text-muted)'))
    .call((g) => g.selectAll('line,path').attr('stroke', 'var(--border)'));

  svg
    .append('text')
    .attr('x', (margin.left + width - margin.right) / 2)
    .attr('y', height - 8)
    .attr('text-anchor', 'middle')
    .attr('fill', 'var(--text-muted)')
    .attr('font-size', 12)
    .text(`PC1${pc1Pct ? ` (${pc1Pct} explained variance)` : ''}`);

  svg
    .append('text')
    .attr('transform', `translate(14,${(margin.top + height - margin.bottom) / 2}) rotate(-90)`)
    .attr('text-anchor', 'middle')
    .attr('fill', 'var(--text-muted)')
    .attr('font-size', 12)
    .text(`PC2${pc2Pct ? ` (${pc2Pct} explained variance)` : ''}`);

  const hullGroups = hullBy ? d3.group(points, (p) => p.concepts[hullBy]) : new Map();
  const hullLayer = svg.append('g').attr('class', 'feature-space-hulls');
  hullGroups.forEach((groupPoints, value) => {
    if (value === NOT_GIVEN || groupPoints.length < 3) return;
    const hull = d3.polygonHull(groupPoints.map((p) => [x(p.PC1), y(p.PC2)]));
    if (!hull) return;
    const color = hullColors[value];
    hullLayer
      .append('path')
      .attr('d', `M${hull.map((pt) => pt.join(',')).join('L')}Z`)
      .attr('fill', color)
      .attr('fill-opacity', 0.1)
      .attr('stroke', color)
      .attr('stroke-width', 1.5)
      .style('pointer-events', 'none');
  });

  const tooltip = d3.select(container).append('div').attr('class', 'landscape-tooltip').style('opacity', 0);

  const pointsLayer = svg.append('g');

  pointsLayer
    .selectAll('circle.user-added-ring')
    .data(points.filter((d) => d.userAdded))
    .join('circle')
    .attr('class', 'user-added-ring')
    .attr('cx', (d) => x(d.PC1))
    .attr('cy', (d) => y(d.PC2))
    .attr('r', 10)
    .attr('fill', 'none')
    .attr('stroke', 'var(--accent)')
    .attr('stroke-width', 1.5)
    .attr('stroke-dasharray', '3,2')
    .style('pointer-events', 'none');

  const circles = pointsLayer
    .selectAll('circle.feature-space-point')
    .data([...points].sort((a, b) => Boolean(b.hidden) - Boolean(a.hidden)))
    .join('circle')
    .attr('class', 'feature-space-point')
    .attr('cx', (d) => x(d.PC1))
    .attr('cy', (d) => y(d.PC2))
    .attr('r', 6)
    .attr('fill', (d) => colors[d.concepts[colorBy]])
    .attr('fill-opacity', (d) => (d.hidden ? 0.28 : 0.8))
    .attr('stroke', (d) => (d.hidden ? 'var(--bg)' : 'var(--text)'))
    .attr('stroke-width', 1)
    .style('cursor', (d) => (d.hidden ? 'default' : 'pointer'))
    .on('mouseenter', (event, d) => {
      tooltip
        .style('opacity', 1)
        .html(
          `<strong>${escapeHtml(d.event_log_name || 'Hidden log')}</strong>` +
            (d.userAdded ? ' <span style="color:var(--accent-text)">· Added by you</span>' : '') +
            `<br/>${escapeHtml(d.concepts[colorBy])}` +
            (hullBy && hullBy !== colorBy ? ` · ${escapeHtml(d.concepts[hullBy])}` : '') +
            (d.academic_context_year ? ` · ${d.academic_context_year}` : '') +
            (d.number_of_cases ? `<br/>${d.number_of_cases.toLocaleString()} cases` : '')
        );
    })
    .on('mousemove', (event) => {
      const [mx, my] = d3.pointer(event, container);
      const tooltipWidth = tooltip.node().offsetWidth;
      const overflowsRight = mx + 12 + tooltipWidth > container.clientWidth;
      const left = overflowsRight ? mx - 12 - tooltipWidth : mx + 12;
      tooltip.style('left', `${left}px`).style('top', `${my + 12}px`);
    })
    .on('mouseleave', () => tooltip.style('opacity', 0))
    .on('click', (event, d) => {
      if (!d.hidden && onPointClick) onPointClick(d.id);
    });

  return {
    destroy: () => {
      circles.interrupt();
      tooltip.remove();
      svg.remove();
    },
  };
}
