import { useEffect, useRef } from 'react';
import { createCorrelationCurve } from '@/viz/correlationCurve';

export default function CorrelationCurve({ curve, selected, onSelect }) {
  const containerRef = useRef(null);

  useEffect(() => {
    if (!containerRef.current || curve.length === 0) return undefined;
    const opts = { selected, onSelect };
    let instance = createCorrelationCurve(containerRef.current, curve, opts);

    const handleResize = () => {
      instance.destroy();
      instance = createCorrelationCurve(containerRef.current, curve, opts);
    };
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      instance.destroy();
    };
  }, [curve, selected, onSelect]);

  return <div className="curve-viz" ref={containerRef} />;
}
