const isNum = (v) => typeof v === 'number' && Number.isFinite(v);

function topEigenvectors(cov, k, iterations = 500) {
  const n = cov.length;
  let basis = Array.from({ length: k }, (_, j) => Array.from({ length: n }, (_, i) => (i === j ? 1 : 0) + Math.sin(i + j + 1) * 1e-3));
  const multiply = (v) => cov.map((row) => row.reduce((s, c, i) => s + c * v[i], 0));
  const orthonormalize = (vectors) => {
    const out = [];
    vectors.forEach((v) => {
      let w = [...v];
      out.forEach((u) => {
        const d = w.reduce((s, x, i) => s + x * u[i], 0);
        w = w.map((x, i) => x - d * u[i]);
      });
      const norm = Math.hypot(...w) || 1;
      out.push(w.map((x) => x / norm));
    });
    return out;
  };
  basis = orthonormalize(basis);
  for (let it = 0; it < iterations; it += 1) {
    const next = orthonormalize(basis.map(multiply));
    const change = Math.max(...next.map((v, j) => 1 - Math.abs(v.reduce((s, x, i) => s + x * basis[j][i], 0))));
    basis = next;
    if (change < 1e-14) break;
  }
  return basis.map((v) => ({ vector: v, value: multiply(v).reduce((s, x, i) => s + x * v[i], 0) }));
}

export function recomputeFeatureSpace(space, datasets) {
  const byId = new Map(datasets.map((d) => [d._id, d]));
  const order = space.feature_order;
  const base = space.points.filter((p) => !p.userAdded);
  if (base.some((p) => !byId.get(p.id)?.feeed_features)) return null;
  const users = datasets.filter((d) => d._userAdded && d.feeed_features);
  const rows = [...base.map((p) => byId.get(p.id).feeed_features), ...users.map((d) => d.feeed_features)].map((f) =>
    order.map((name) => (isNum(f[name]) ? f[name] : NaN))
  );
  const n = order.length;
  const N = rows.length;

  const imputerMean = order.map((_, j) => {
    const vals = rows.map((r) => r[j]).filter((v) => !Number.isNaN(v));
    return vals.length ? vals.reduce((s, v) => s + v, 0) / vals.length : 0;
  });
  const imputed = rows.map((r) => r.map((v, j) => (Number.isNaN(v) ? imputerMean[j] : v)));
  const min = order.map((_, j) => Math.min(...imputed.map((r) => r[j])));
  const max = order.map((_, j) => Math.max(...imputed.map((r) => r[j])));
  const scale = order.map((_, j) => (max[j] - min[j] === 0 ? 1 : 1 / (max[j] - min[j])));
  const scalerMin = order.map((_, j) => -min[j] * scale[j]);
  const normed = imputed.map((r) => {
    const scaled = r.map((v, j) => v * scale[j] + scalerMin[j]);
    const norm = Math.hypot(...scaled) || 1;
    return scaled.map((v) => v / norm);
  });
  const mean = order.map((_, j) => normed.reduce((s, r) => s + r[j], 0) / N);
  const centered = normed.map((r) => r.map((v, j) => v - mean[j]));
  const cov = Array.from({ length: n }, () => new Array(n).fill(0));
  centered.forEach((r) => {
    for (let i = 0; i < n; i += 1) {
      const ri = r[i];
      if (!ri) continue;
      for (let j = i; j < n; j += 1) cov[i][j] += ri * r[j];
    }
  });
  for (let i = 0; i < n; i += 1) {
    for (let j = i; j < n; j += 1) {
      cov[i][j] /= N - 1;
      cov[j][i] = cov[i][j];
    }
  }
  const total = cov.reduce((s, row, i) => s + row[i], 0);
  const [pc1, pc2] = topEigenvectors(cov, 2);
  const align = (vec, loadings) => {
    const dot = order.reduce((s, name, i) => s + vec[i] * (loadings?.[name] || 0), 0);
    return dot < 0 ? vec.map((x) => -x) : vec;
  };
  const v1 = align(pc1.vector, space.loadings_pc1);
  const v2 = align(pc2.vector, space.loadings_pc2);
  const project = (r) => ({
    PC1: r.reduce((s, x, i) => s + x * v1[i], 0),
    PC2: r.reduce((s, x, i) => s + x * v2[i], 0),
  });
  const coords = centered.map(project);

  return {
    ...space,
    recomputed: true,
    n_points: N,
    explained_variance_ratio: [pc1.value / total, pc2.value / total],
    imputer_mean: imputerMean,
    scaler_min: scalerMin,
    scaler_scale: scale,
    pca_mean: mean,
    loadings_pc1: Object.fromEntries(order.map((name, i) => [name, v1[i]])),
    loadings_pc2: Object.fromEntries(order.map((name, i) => [name, v2[i]])),
    basePoints: base.map((p, i) => ({ ...p, ...coords[i] })),
    userCoords: users.map((d, i) => ({ id: d._id, ...coords[base.length + i] })),
  };
}

function pearson(xs, ys) {
  let n = 0;
  let sx = 0;
  let sy = 0;
  for (let i = 0; i < xs.length; i += 1) {
    if (Number.isNaN(xs[i]) || Number.isNaN(ys[i])) continue;
    n += 1;
    sx += xs[i];
    sy += ys[i];
  }
  if (n < 5) return NaN;
  const mx = sx / n;
  const my = sy / n;
  let sxy = 0;
  let sxx = 0;
  let syy = 0;
  for (let i = 0; i < xs.length; i += 1) {
    if (Number.isNaN(xs[i]) || Number.isNaN(ys[i])) continue;
    const dx = xs[i] - mx;
    const dy = ys[i] - my;
    sxy += dx * dy;
    sxx += dx * dx;
    syy += dy * dy;
  }
  return sxx && syy ? sxy / Math.sqrt(sxx * syy) : NaN;
}

export function greedyLeastCorrelated(features, matrix) {
  const n = features.length;
  const abs = (i, j) => Math.abs(matrix[i][j]);
  const meanAbs = features.map((_, i) => {
    let s = 0;
    let c = 0;
    for (let j = 0; j < n; j += 1) {
      if (Number.isFinite(matrix[i][j])) {
        s += abs(i, j);
        c += 1;
      }
    }
    return c ? s / c : Infinity;
  });
  const first = meanAbs.indexOf(Math.min(...meanAbs));
  const chosen = [first];
  const available = new Set(features.map((_, i) => i).filter((i) => i !== first));
  const maxTo = features.map((_, i) => abs(i, first));
  while (available.size) {
    let best = null;
    available.forEach((i) => {
      if (best === null || maxTo[i] < maxTo[best]) best = i;
    });
    chosen.push(best);
    available.delete(best);
    available.forEach((i) => {
      maxTo[i] = Math.max(maxTo[i], abs(i, best));
    });
  }
  return chosen.map((i) => features[i]);
}

export function recomputeFeatureSelection(selection, datasets) {
  const withFeatures = datasets.filter((d) => d.feeed_features);
  const users = withFeatures.filter((d) => d._userAdded);
  const features = selection.features;
  const columns = features.map((name) => withFeatures.map((d) => (isNum(d.feeed_features[name]) ? d.feeed_features[name] : NaN)));
  const matrix = features.map(() => new Array(features.length).fill(0));
  for (let i = 0; i < features.length; i += 1) {
    matrix[i][i] = 1;
    for (let j = i + 1; j < features.length; j += 1) {
      const r = pearson(columns[i], columns[j]);
      const value = Number.isNaN(r) ? selection.correlation_matrix[i][j] : r;
      matrix[i][j] = value;
      matrix[j][i] = value;
    }
  }
  return {
    ...selection,
    recomputed: true,
    n_logs: withFeatures.length,
    n_user_logs: users.length,
    correlation_matrix: matrix,
    greedy_order: greedyLeastCorrelated(features, matrix),
  };
}
