import FEATURE_SETS from './featureSets.json';

export const FEATURE_SET_IDS = ['default', 'all'];

const EXCLUDED = new Set(FEATURE_SETS.excluded || []);

export function normalizeFeatureSet(id) {
  return FEATURE_SET_IDS.includes(id) ? id : 'default';
}

export function isExcludedFeature(name) {
  return EXCLUDED.has(name);
}

export function featureSetNames(id) {
  const groups = FEATURE_SET_IDS.includes(id) ? FEATURE_SETS[id] : null;
  return groups ? Object.values(groups).flat().filter((name) => !EXCLUDED.has(name)) : null;
}
