import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { ThemeProvider } from '@/lib/theme';
import EventDatasetsPage from '@/views/EventDatasetsPage';
import EventDatasetDetailPage from '@/views/EventDatasetDetailPage';
import FeatureSpaceExplorationPage from '@/views/FeatureSpaceExplorationPage';
import FeatureSelectionPage from '@/views/FeatureSelectionPage';
import AboutPage from '@/views/AboutPage';

import '@/styles/global.css';
import './styles/app.css';

const basename = import.meta.env.BASE_URL;

export default function App() {
  return (
    <ThemeProvider>
      <BrowserRouter basename={basename}>
        <Routes>
          <Route path="/" element={<EventDatasetsPage />} />
          <Route path="/datasets/:id" element={<EventDatasetDetailPage />} />
          <Route path="/feature-space" element={<FeatureSpaceExplorationPage />} />
          <Route path="/feature-selection" element={<FeatureSelectionPage />} />
          <Route path="/about" element={<AboutPage />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </BrowserRouter>
    </ThemeProvider>
  );
}
