import { useEffect, useRef } from 'react';
import { createCorrelationHeatmap } from '@/viz/correlationHeatmap';

export default function CorrelationHeatmap({ orderedFeatures, matrix, featureIndex, groupBoundaries, highlighted }) {
  const containerRef = useRef(null);

  useEffect(() => {
    if (!containerRef.current || orderedFeatures.length === 0) return undefined;
    const opts = { orderedFeatures, matrix, featureIndex, groupBoundaries, highlighted };

    let instance = createCorrelationHeatmap(containerRef.current, opts);

    const handleResize = () => {
      instance.destroy();
      instance = createCorrelationHeatmap(containerRef.current, opts);
    };
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      instance.destroy();
    };
  }, [orderedFeatures, matrix, featureIndex, groupBoundaries, highlighted]);

  return <div className="heatmap-viz" ref={containerRef} />;
}
