import * as d3 from 'd3';

export const CORRELATION_COLOR = 'var(--nord15)';
export const EXPLAINED_COLOR = 'var(--nord14)';

export function createCorrelationCurve(container, curve, { selected, onSelect } = {}) {
  const width = container.clientWidth || 360;
  const height = 240;
  const margin = { top: 16, right: 52, bottom: 40, left: 56 };

  const x = d3
    .scaleLinear()
    .domain(d3.extent(curve, (d) => d.k))
    .range([margin.left, width - margin.right]);
  const yMean = d3
    .scaleLinear()
    .domain([0, d3.max(curve, (d) => d.mean) || 1])
    .nice()
    .range([height - margin.bottom, margin.top]);
  const yExplained = d3.scaleLinear().domain([0, 1]).range([height - margin.bottom, margin.top]);

  const svg = d3
    .select(container)
    .append('svg')
    .attr('width', width)
    .attr('height', height)
    .attr('viewBox', [0, 0, width, height]);

  const axisStyle = (color) => (g) => {
    g.selectAll('text').attr('fill', color);
    g.selectAll('line,path').attr('stroke', 'var(--border)');
  };

  svg
    .append('g')
    .attr('transform', `translate(0,${height - margin.bottom})`)
    .call(d3.axisBottom(x).ticks(5).tickFormat(d3.format('d')))
    .call(axisStyle('var(--text-muted)'));
  svg
    .append('g')
    .attr('transform', `translate(${margin.left},0)`)
    .call(d3.axisLeft(yMean).ticks(5))
    .call(axisStyle(CORRELATION_COLOR));
  svg
    .append('g')
    .attr('transform', `translate(${width - margin.right},0)`)
    .call(d3.axisRight(yExplained).ticks(5).tickFormat(d3.format('.0%')))
    .call(axisStyle(EXPLAINED_COLOR));

  svg
    .append('text')
    .attr('x', (margin.left + width - margin.right) / 2)
    .attr('y', height - 6)
    .attr('text-anchor', 'middle')
    .attr('fill', 'var(--text-muted)')
    .attr('font-size', 11)
    .text('Number of least-correlated features (k)');
  svg
    .append('text')
    .attr('transform', `translate(12,${(margin.top + height - margin.bottom) / 2}) rotate(-90)`)
    .attr('text-anchor', 'middle')
    .attr('fill', CORRELATION_COLOR)
    .attr('font-size', 11)
    .text('Average pairwise correlation');
  svg
    .append('text')
    .attr('transform', `translate(${width - 10},${(margin.top + height - margin.bottom) / 2}) rotate(90)`)
    .attr('text-anchor', 'middle')
    .attr('fill', EXPLAINED_COLOR)
    .attr('font-size', 11)
    .text('Variance Explained');

  const series = [
    { key: 'mean', y: yMean, color: CORRELATION_COLOR },
    { key: 'explained', y: yExplained, color: EXPLAINED_COLOR },
  ];
  series.forEach(({ key, y, color }) => {
    svg
      .append('path')
      .datum(curve)
      .attr('fill', 'none')
      .attr('stroke', color)
      .attr('stroke-width', 1.75)
      .attr('d', d3.line().x((d) => x(d.k)).y((d) => y(d[key])));
  });

  const current = curve.find((d) => d.k === selected);
  if (current) {
    svg
      .append('line')
      .attr('x1', x(current.k))
      .attr('x2', x(current.k))
      .attr('y1', margin.top)
      .attr('y2', height - margin.bottom)
      .attr('stroke', 'var(--text-muted)')
      .attr('stroke-dasharray', '2,2');
    series.forEach(({ key, y, color }) => {
      svg
        .append('circle')
        .attr('cx', x(current.k))
        .attr('cy', y(current[key]))
        .attr('r', 5.5)
        .attr('fill', color)
        .attr('stroke', 'var(--text)')
        .attr('stroke-width', 1.5);
    });
    const right = x(current.k) > (margin.left + width - margin.right) / 2;
    svg
      .append('text')
      .attr('x', x(current.k) + (right ? -8 : 8))
      .attr('y', height - margin.bottom - 8)
      .attr('text-anchor', right ? 'end' : 'start')
      .attr('fill', 'var(--text)')
      .attr('font-size', 12)
      .attr('font-weight', 600)
      .text(`k = ${current.k}`);
  }

  const tooltip = d3.select(container).append('div').attr('class', 'landscape-tooltip').style('opacity', 0);
  const markers = series.map(({ color }) =>
    svg.append('circle').attr('r', 4).attr('fill', color).style('opacity', 0).style('pointer-events', 'none')
  );
  const nearest = (event) => {
    const [mx] = d3.pointer(event, svg.node());
    const k = Math.round(x.invert(mx));
    return curve.find((d) => d.k === k) || null;
  };

  svg
    .append('rect')
    .attr('x', margin.left)
    .attr('y', margin.top)
    .attr('width', width - margin.left - margin.right)
    .attr('height', height - margin.top - margin.bottom)
    .attr('fill', 'transparent')
    .style('cursor', onSelect ? 'pointer' : 'default')
    .on('mousemove', (event) => {
      const d = nearest(event);
      if (!d) return;
      series.forEach(({ key, y }, i) => markers[i].attr('cx', x(d.k)).attr('cy', y(d[key])).style('opacity', 1));
      const [mx, my] = d3.pointer(event, container);
      const tooltipWidth = tooltip.node().offsetWidth;
      const left = mx + 12 + tooltipWidth > container.clientWidth ? mx - 12 - tooltipWidth : mx + 12;
      tooltip
        .style('opacity', 1)
        .style('left', `${left}px`)
        .style('top', `${my + 12}px`)
        .html(
          `k = ${d.k}<br/>Average pairwise correlation: <strong>${d.mean.toFixed(3)}</strong><br/>Variance Explained: <strong>${(d.explained * 100).toFixed(1)}%</strong>`
        );
    })
    .on('mouseleave', () => {
      markers.forEach((m) => m.style('opacity', 0));
      tooltip.style('opacity', 0);
    })
    .on('click', (event) => {
      const d = nearest(event);
      if (d && onSelect) onSelect(d.k);
    });

  return {
    destroy: () => {
      tooltip.remove();
      svg.remove();
    },
  };
}
