import * as d3 from 'd3';
import { isHidden } from '@/lib/filters';
import { escapeHtml } from '@/lib/humanize';
import { conceptValue } from '@/lib/concepts';

export function createLandscape(container, datasets, { concept, colors, onDatasetClick } = {}) {
  const width = container.clientWidth || 900;

  const years = datasets.map((d) => d.academic_context?.year).filter(Boolean);
  const yearExtent = d3.extent(years);
  const yearDomain = yearExtent[0] === yearExtent[1] ? [yearExtent[0] - 1, yearExtent[0] + 1] : yearExtent;

  const domainCounts = new Map();
  datasets.forEach((d) => {
    const value = conceptValue(concept, d);
    domainCounts.set(value, (domainCounts.get(value) || 0) + 1);
  });
  const domains = [...domainCounts.entries()]
    .sort((a, b) => (b[0] === 'Not given') - (a[0] === 'Not given') || b[1] - a[1])
    .map(([value]) => value);

  const margin = { top: 20, right: 24, bottom: 40, left: 0 };

  const height = Math.max(360, margin.top + margin.bottom + domains.length * 32);

  const y = d3.scaleBand().domain(domains).range([height - margin.bottom, margin.top]).paddingOuter(0.5);

  const caseExtent = d3.extent(datasets, (d) => d.basic_info?.number_of_cases || 0);
  const radiusScale = d3.scaleSqrt().domain([0, caseExtent[1] || 1]).range([4, 12]).clamp(true);

  const svg = d3
    .select(container)
    .append('svg')
    .attr('width', width)
    .attr('height', height)
    .attr('viewBox', [0, 0, width, height]);

  const yAxis = svg
    .append('g')
    .call(d3.axisLeft(y))
    .call((g) => g.selectAll('text').attr('fill', 'var(--text-muted)'))
    .call((g) => g.selectAll('line,path').attr('stroke', 'var(--border)'));
  const labelWidth = d3.max(yAxis.selectAll('text').nodes(), (node) => node.getBBox().width) || 0;
  margin.left = Math.ceil(labelWidth) + 16;
  yAxis.attr('transform', `translate(${margin.left},0)`);

  const x = d3.scaleLinear().domain(yearDomain).range([margin.left, width - margin.right]).nice();

  svg
    .append('g')
    .attr('transform', `translate(0,${height - margin.bottom})`)
    .call(d3.axisBottom(x).tickFormat(d3.format('d')).ticks(Math.min(yearDomain[1] - yearDomain[0] + 1, 10)))
    .call((g) => g.selectAll('text').attr('fill', 'var(--text-muted)'))
    .call((g) => g.selectAll('line,path').attr('stroke', 'var(--border)'));

  const jitterY = () => (Math.random() - 0.5) * y.bandwidth() * 0.7;

  const points = datasets
    .filter((d) => d.academic_context?.year)
    .map((d) => {
      const domain = conceptValue(concept, d);
      return {
        dataset: d,
        x: d.academic_context.year,
        y: y(domain) + y.bandwidth() / 2 + jitterY(),
        value: domain,
        color: colors[domain] || '#88c0d0',
        radius: radiusScale(d.basic_info?.number_of_cases || 0),
        hidden: isHidden(d),
        userAdded: Boolean(d._userAdded),
      };
    });

  const tooltip = d3.select(container).append('div').attr('class', 'landscape-tooltip').style('opacity', 0);

  const pointsLayer = svg.append('g');

  pointsLayer
    .selectAll('circle.user-added-ring')
    .data(points.filter((d) => d.userAdded))
    .join('circle')
    .attr('class', 'user-added-ring')
    .attr('cx', (d) => x(d.x))
    .attr('cy', (d) => d.y)
    .attr('r', (d) => d.radius + 4)
    .attr('fill', 'none')
    .attr('stroke', 'var(--accent)')
    .attr('stroke-width', 1.5)
    .attr('stroke-dasharray', '3,2')
    .style('pointer-events', 'none');

  const circles = pointsLayer
    .selectAll('circle.landscape-point')
    .data([...points].sort((a, b) => b.hidden - a.hidden))
    .join('circle')
    .attr('class', 'landscape-point')
    .attr('cx', (d) => x(d.x))
    .attr('cy', (d) => d.y)
    .attr('r', (d) => d.radius)
    .attr('fill', (d) => d.color)
    .attr('fill-opacity', (d) => (d.hidden ? 0.28 : 0.75))
    .attr('stroke', (d) => (d.hidden ? 'var(--bg)' : 'var(--text)'))
    .attr('stroke-width', 1)
    .style('cursor', (d) => (d.hidden ? 'default' : 'pointer'))
    .on('mouseenter', (event, d) => {
      if (d.hidden) return;
      const cases = d.dataset.basic_info?.number_of_cases;
      tooltip
        .style('opacity', 1)
        .html(
          `<strong>${escapeHtml(d.dataset.basic_info.event_log_name)}</strong>` +
            (d.userAdded ? ' <span style="color:var(--accent-text)">· Added by you</span>' : '') +
            `<br/>${d.x} · ${escapeHtml(d.value)}` +
            (cases ? `<br/>${cases.toLocaleString()} cases` : '')
        );
    })
    .on('mousemove', (event) => {
      const [mx, my] = d3.pointer(event, container);
      const tooltipWidth = tooltip.node().offsetWidth;
      const overflowsRight = mx + 12 + tooltipWidth > container.clientWidth;
      const left = overflowsRight ? mx - 12 - tooltipWidth : mx + 12;
      tooltip.style('left', `${left}px`).style('top', `${my + 12}px`);
    })
    .on('mouseleave', () => tooltip.style('opacity', 0))
    .on('click', (event, d) => {
      if (!d.hidden && onDatasetClick) onDatasetClick(d.dataset._id);
    });

  return {
    destroy: () => {
      circles.interrupt();
      tooltip.remove();
      svg.remove();
    },
  };
}
