export const NOT_GIVEN = 'Not given';
export const NOT_GIVEN_COLOR = '#8a93a3';

const EVENT_LOG_TYPE_COLORS = {
  'Real-life': 'var(--nord10)',
  Synthetic: 'var(--nord14)',
  'IoT Lab Logs': 'var(--nord15)',
};

export const CONCEPTS = [
  { key: 'domain_application', label: 'Domain Application', get: (d) => d.domain_context?.domain_application },
  { key: 'event_log_type', label: 'Event Log Type', get: (d) => d.domain_context?.event_log_type },
  { key: 'process_type', label: 'Process Type', get: (d) => d.domain_context?.process_type },
  { key: 'publication_type', label: 'Publication Type', get: (d) => d.academic_context?.publication_type },
  { key: 'dataset_format', label: 'Dataset Format', get: (d) => d.basic_info?.dataset_format },
  {
    key: 'resource_availability',
    label: 'Resource Availability',
    get: (d) => {
      const r = d.basic_info?.resource_availability;
      if (r === null || r === undefined) return null;
      return r ? 'With resources' : 'Without resources';
    },
  },
];

export function conceptByKey(key) {
  return CONCEPTS.find((c) => c.key === key) || CONCEPTS[0];
}

export function conceptValue(concept, dataset) {
  return concept.get(dataset) || NOT_GIVEN;
}

export function conceptValues(concept, datasets) {
  const counts = new Map();
  datasets.forEach((d) => {
    const v = conceptValue(concept, d);
    counts.set(v, (counts.get(v) || 0) + 1);
  });
  return [...counts.entries()]
    .sort((a, b) => (a[0] === NOT_GIVEN) - (b[0] === NOT_GIVEN) || b[1] - a[1] || String(a[0]).localeCompare(String(b[0])))
    .map(([v]) => v);
}

export function conceptColors(concept, values, config) {
  const palette = (config?.domainApplications || []).map((d) => d.color);
  const fixed =
    concept.key === 'domain_application'
      ? Object.fromEntries((config?.domainApplications || []).map((d) => [d.id, d.color]))
      : concept.key === 'event_log_type'
        ? EVENT_LOG_TYPE_COLORS
        : {};
  const used = new Set(Object.values(fixed));
  const free = palette.filter((c) => !used.has(c));
  let next = 0;
  const map = {};
  values.forEach((v) => {
    if (v === NOT_GIVEN) map[v] = NOT_GIVEN_COLOR;
    else if (fixed[v]) map[v] = fixed[v];
    else {
      map[v] = free.length ? free[next % free.length] : NOT_GIVEN_COLOR;
      next += 1;
    }
  });
  return map;
}
