import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import Header from '@/components/Header';
import { loadDatasets, loadConfig } from '@/lib/data';
import { getDomainApplication } from '@/lib/filters';

export default function AboutPage() {
  const [datasets, setDatasets] = useState(null);
  const [config, setConfig] = useState(null);

  useEffect(() => {
    Promise.all([loadDatasets(), loadConfig()]).then(([d, c]) => {
      setDatasets(d);
      setConfig(c);
    });
  }, []);

  if (!datasets || !config) {
    return (
      <div className="main-layout">
        <div className="loading">
          <div className="loading__spinner" />
          <p>Loading...</p>
        </div>
      </div>
    );
  }

  const about = config.about || {};
  const invites = (about.sections || []).filter((section) => section.invite);
  const contactEmail = config.contribute?.email;
  const counts = {};
  datasets.forEach((d) => {
    const domain = getDomainApplication(d);
    if (domain) counts[domain] = (counts[domain] || 0) + 1;
  });

  return (
    <div className="main-layout">
      <Header config={config} />
      <main className="main-content about-page">
        <h1>{about.title || 'About'}</h1>
        <p className="about-page__intro">{about.introduction}</p>

        {invites.map((section) => (
          <section className="contribute-cta about-page__invite" key={section.title}>
            <div className="contribute-cta__text">
              <h2 className="contribute-cta__title">{section.title}</h2>
              <p>{section.content}</p>
              {contactEmail && (
                <p className="about-page__contact">
                  Contact: <a href={`mailto:${contactEmail}`}>{contactEmail}</a>
                </p>
              )}
            </div>
            <div className="contribute-cta__actions">
              <Link className="btn btn--primary btn--lg" to="/?add=1">
                + Add Event Log
              </Link>
            </div>
          </section>
        ))}

        {(config.domainApplications || []).length > 0 && (
          <section className="detail-section">
            <h2 className="detail-section__title">Domain Applications</h2>
            <ul className="about-page__domain-list">
              {config.domainApplications.map((d) => (
                <li key={d.id} className="about-page__domain-item">
                  <span className="domain-card__swatch" style={{ '--domain-color': d.color }} />
                  <div>
                    <strong style={{ color: d.color }}>{d.label}</strong> — {counts[d.id] || 0}{' '}
                    {counts[d.id] === 1 ? 'event log' : 'event logs'}
                  </div>
                </li>
              ))}
            </ul>
          </section>
        )}

        {(about.sections || []).filter((section) => !section.invite).map((section) => (
          <section className="detail-section" key={section.title}>
            <h2 className="detail-section__title">{section.title}</h2>
            <p>{section.content}</p>
          </section>
        ))}

        {(about.references || []).length > 0 && (
          <section className="detail-section">
            <h2 className="detail-section__title">References</h2>
            <ol className="about-page__references">
              {about.references.map((ref) => (
                <li key={ref.url || ref.text}>
                  {ref.text}{' '}
                  {ref.url && (
                    <a href={ref.url} target="_blank" rel="noopener noreferrer">
                      {ref.url}
                    </a>
                  )}
                </li>
              ))}
            </ol>
          </section>
        )}

        {about.license && (
          <section className="detail-section">
            <h2 className="detail-section__title">License</h2>
            <p className="about-page__license">
              {about.license.text}{' '}
              <a
                className="about-page__license-link"
                href={about.license.url}
                target="_blank"
                rel="noopener noreferrer license"
              >
                {about.license.fullName || about.license.name}
              </a>
            </p>
          </section>
        )}

        <p className="about-page__count">Total event log datasets indexed: {datasets.length}</p>
      </main>
    </div>
  );
}
