import { parseTimeMicros } from './parseXes.js';

const DELIMITERS = [',', ';', '\t', '|'];

function countOutsideQuotes(line, delimiter) {
  let n = 0;
  let quoted = false;
  for (const ch of line) {
    if (ch === '"') quoted = !quoted;
    else if (ch === delimiter && !quoted) n += 1;
  }
  return n;
}

export function detectDelimiter(text) {
  const lines = text.split(/\r?\n/, 6).filter((l) => l.trim());
  let best = ',';
  let bestScore = 0;
  DELIMITERS.forEach((d) => {
    const counts = lines.map((l) => countOutsideQuotes(l, d));
    const min = Math.min(...counts);
    if (min > bestScore) {
      best = d;
      bestScore = min;
    }
  });
  return best;
}

export function parseCsvText(text) {
  const source = text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
  const delimiter = detectDelimiter(source);
  const rows = [];
  let row = [];
  let field = '';
  let quoted = false;
  let i = 0;
  const n = source.length;
  while (i < n) {
    const ch = source[i];
    if (quoted) {
      if (ch === '"') {
        if (source[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }
        quoted = false;
      } else {
        field += ch;
      }
      i += 1;
      continue;
    }
    if (ch === '"' && field === '') {
      quoted = true;
    } else if (ch === delimiter) {
      row.push(field);
      field = '';
    } else if (ch === '\n' || ch === '\r') {
      row.push(field);
      field = '';
      if (row.length > 1 || row[0] !== '') rows.push(row);
      row = [];
      if (ch === '\r' && source[i + 1] === '\n') i += 1;
    } else {
      field += ch;
    }
    i += 1;
  }
  if (field !== '' || row.length) {
    row.push(field);
    if (row.length > 1 || row[0] !== '') rows.push(row);
  }
  if (rows.length < 2) throw new Error('The CSV file needs a header row and at least one row of events.');
  const seen = new Map();
  const header = rows[0].map((h, idx) => {
    const base = h.trim() || `Column ${idx + 1}`;
    const n = (seen.get(base) || 0) + 1;
    seen.set(base, n);
    return n > 1 ? `${base} (${n})` : base;
  });
  return { header, rows: rows.slice(1), delimiter };
}

const GUESSES = {
  caseId: [/^case:concept:name$/i, /^case[\s_:-]*id$/i, /^case$/i, /^caseid$/i, /^case[\s_]*(number|nr|no)$/i, /^trace[\s_:-]*id$/i, /case/i],
  activity: [/^concept:name$/i, /^activity$/i, /^activity[\s_]*(name|id|label)$/i, /^event[\s_]*(name|type)?$/i, /^task$/i, /activity/i],
  timestamp: [/^time:timestamp$/i, /^(complete[\s_]*)?timestamp$/i, /^time$/i, /^(end|complete)[\s_]*time(stamp)?$/i, /^date[\s_]*time$/i, /timestamp/i, /time|date/i],
  resource: [/^org:resource$/i, /^resource$/i, /^(user|performer|employee|actor|agent)$/i, /resource/i],
};

export function guessMapping(header) {
  const used = new Set();
  const mapping = {};
  Object.entries(GUESSES).forEach(([role, patterns]) => {
    for (const pattern of patterns) {
      const hit = header.find((h) => !used.has(h) && pattern.test(h.trim()));
      if (hit) {
        mapping[role] = hit;
        used.add(hit);
        return;
      }
    }
    mapping[role] = '';
  });
  return mapping;
}

const ISO_LIKE = /^(\d{4}-\d{2}-\d{2})(?:[T ](\d{1,2}):(\d{2})(?::(\d{2})(\.\d+)?)?)?\s*(Z|[+-]\d{2}:?\d{2})?$/;
const NUMERIC_DATE = /^(\d{1,2})[./-](\d{1,2})[./-](\d{4})(?:[T ,]+(\d{1,2}):(\d{2})(?::(\d{2})(\.\d+)?)?)?$/;

function pad(n) {
  return String(n).padStart(2, '0');
}

export function detectDateOrder(values) {
  let dayFirst = false;
  let monthFirst = false;
  let numeric = false;
  values.forEach((v) => {
    const m = NUMERIC_DATE.exec(String(v).trim());
    if (!m) return;
    numeric = true;
    if (Number(m[1]) > 12) dayFirst = true;
    if (Number(m[2]) > 12) monthFirst = true;
  });
  if (!numeric) return null;
  if (dayFirst && !monthFirst) return 'dmy';
  if (monthFirst && !dayFirst) return 'mdy';
  return 'ambiguous';
}

export function parseCsvTimestamp(raw, dateOrder = 'dmy') {
  const value = String(raw ?? '').trim();
  if (!value) return null;
  const iso = ISO_LIKE.exec(value);
  if (iso) {
    const [, date, h = '0', min = '00', sec = '00', frac = '', zone = 'Z'] = iso;
    const tz = /^[+-]\d{4}$/.test(zone) ? `${zone.slice(0, 3)}:${zone.slice(3)}` : zone;
    return parseTimeMicros(`${date}T${pad(h)}:${min}:${sec}${frac}${tz}`);
  }
  const num = NUMERIC_DATE.exec(value);
  if (num) {
    const [, a, b, year, h = '0', min = '00', sec = '00', frac = ''] = num;
    const [day, month] = dateOrder === 'mdy' ? [b, a] : [a, b];
    if (Number(month) > 12 || Number(day) > 31) return null;
    return parseTimeMicros(`${year}-${pad(month)}-${pad(day)}T${pad(h)}:${min}:${sec}${frac}Z`);
  }
  if (/^\d+(\.\d+)?$/.test(value)) return null;
  const ms = Date.parse(value);
  return Number.isNaN(ms) ? null : ms * 1000;
}

export function csvToTraces({ header, rows }, mapping, { dateOrder = 'dmy' } = {}) {
  const col = (name) => header.indexOf(name);
  const caseIdx = col(mapping.caseId);
  const activityIdx = col(mapping.activity);
  const timeIdx = col(mapping.timestamp);
  const resourceIdx = mapping.resource ? col(mapping.resource) : -1;
  const roles = new Set([caseIdx, activityIdx, timeIdx, resourceIdx]);
  const extra = header.map((name, idx) => [name, idx]).filter(([, idx]) => !roles.has(idx));

  const cases = new Map();
  let noCase = 0;
  let badTime = 0;
  let example = null;
  let order = 0;
  rows.forEach((row) => {
    const caseId = (row[caseIdx] ?? '').trim();
    if (!caseId) {
      noCase += 1;
      return;
    }
    const rawTime = row[timeIdx];
    const timeMicros = parseCsvTimestamp(rawTime, dateOrder);
    if (timeMicros === null) {
      badTime += 1;
      if (example === null && String(rawTime ?? '').trim()) example = String(rawTime).trim();
    }
    const attributes = {
      'concept:name': row[activityIdx] ?? '',
      'time:timestamp': rawTime ?? '',
    };
    const resource = resourceIdx >= 0 ? (row[resourceIdx] ?? '').trim() : '';
    if (resource) attributes['org:resource'] = resource;
    extra.forEach(([name, idx]) => {
      const v = row[idx];
      if (v !== undefined && v !== '') attributes[name] = v;
    });
    if (!cases.has(caseId)) cases.set(caseId, []);
    cases.get(caseId).push({
      activity: (row[activityIdx] ?? '').trim() || '(unnamed activity)',
      timestamp: timeMicros === null ? null : new Date(timeMicros / 1000),
      timeMicros,
      resource: resource || null,
      attributes,
      order: (order += 1),
    });
  });

  const total = rows.length - noCase;
  if (total === 0) throw new Error(`The column "${mapping.caseId}" has no case IDs.`);
  if (badTime > total / 2) {
    throw new Error(
      `Most values in the column "${mapping.timestamp}" could not be read as timestamps${example ? `, for example "${example}"` : ''}. Please choose the timestamp column, or check the date order.`
    );
  }

  const byTime = (x, y) => {
    if (x.timeMicros === null || y.timeMicros === null) return x.order - y.order;
    return x.timeMicros - y.timeMicros || x.order - y.order;
  };
  const traces = [...cases.entries()]
    .map(([caseId, events]) => {
      events.sort(byTime);
      return { caseId, first: events.find((e) => e.timeMicros !== null) || events[0], events };
    })
    .sort((x, y) => byTime(x.first, y.first))
    .map(({ caseId, events }) => ({
      caseId,
      attributes: { 'concept:name': caseId },
      events: events.map(({ order: _order, ...e }) => e),
    }));

  const warnings = [];
  if (noCase) warnings.push(`${noCase.toLocaleString()} rows without a case ID were left out.`);
  if (badTime) {
    warnings.push(
      `${badTime.toLocaleString()} timestamps could not be read${example ? `, for example "${example}"` : ''}. These events have no timestamp.`
    );
  }
  return { traces, warnings };
}
